    color: #fde68a;
    font-size: 20px;
    line-height: 1.25;
}

.ship-evolution-ok {
    display: block;
    min-width: 120px;
    min-height: 38px;
    margin: 16px auto 0;
    padding: 8px 16px;
    border: none;
    border-radius: 6px;
    background: #facc15;
    color: #111827;
    font-size: 13px;
    font-weight: 800;
    opacity: 0;
    transform: translateY(8px);
    transition: opacity 180ms ease, transform 180ms ease;
}

.ship-evolution-overlay.is-finished .ship-evolution-ok {
    opacity: 1;
    transform: translateY(0);
}

@keyframes shipEvolutionWake {
    from { transform: translateX(0); }
    to { transform: translateX(-48px); }
}

@keyframes shipEvolutionLight {
    0% { opacity: 0; transform: scale(0.65); }
    28% { opacity: 0.82; transform: scale(0.92); }
    66% { opacity: 1; transform: scale(1.12); }
    100% { opacity: 0.22; transform: scale(1.3); }
}

@keyframes shipEvolutionBefore {
    0% { opacity: 1; transform: translateX(-96px) scale(2.2); }
    38% { opacity: 1; transform: translateX(0) scale(2.34); }
    58% { opacity: 0; transform: translateX(0) scale(0.85) rotate(8deg); }
    100% { opacity: 0; transform: translateX(0) scale(0.85) rotate(8deg); }
}

@keyframes shipEvolutionAfter {
    0%, 58% { opacity: 0; transform: translateX(0) scale(0.85) rotate(-8deg); }
    72% { opacity: 1; transform: translateX(0) scale(2.55) rotate(0); }
    100% { opacity: 1; transform: translateX(0) scale(2.2); }
}

@keyframes shipEvolutionBurst {
    0% { opacity: 0; transform: translate(-50%, -50%) rotate(calc(var(--i) * 22.5deg)) translateY(0) scaleY(0.4); }
    18% { opacity: 1; }
    100% { opacity: 0; transform: translate(-50%, -50%) rotate(calc(var(--i) * 22.5deg)) translateY(-86px) scaleY(1); }
}

