/* --- ホーム画面: アバターと装備 --- */
#homeLayout {
    display: flex;
    flex-direction: column;
    gap: 16px;
    align-items: center;
}

.avatar-card {
    position: relative;
    width: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    background:
        radial-gradient(ellipse at 50% 25%, rgba(30, 64, 120, 0.55) 0%, transparent 65%),
        linear-gradient(180deg, rgba(10, 20, 40, 0.97), rgba(6, 14, 28, 0.99));
    border-radius: 16px;
    padding: 20px;
    border: 1px solid rgba(245, 158, 11, 0.32);
    box-shadow:
        0 0 0 1px rgba(245, 158, 11, 0.1),
        0 20px 40px rgba(0, 0, 0, 0.5),
        inset 0 1px 0 rgba(255, 255, 255, 0.06);
    overflow: hidden;
}

.avatar-card::before {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 40%;
    background: linear-gradient(0deg, rgba(6, 24, 50, 0.6), transparent);
    pointer-events: none;
}

.avatar-container {
    position: relative;
    width: 64px;
    height: 64px;
    transform: scale(2.0);
    transform-origin: center center;
    margin: 32px 0; /* scale分の余白確保 */
    image-rendering: pixelated;
}

/* ステータス詳細 */
.avatar-layer {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-repeat: no-repeat;
}

.avatar-combat-actor {
    --avatar-attack-duration: 520ms;
    --avatar-attack-start-x: 0px;
    --avatar-attack-x: -34px;
    --avatar-attack-recoil-x: -24px;
    --avatar-attack-y: 0px;
    --avatar-motion-forward-x: -16px;
    --avatar-motion-recoil-x: 4px;
    --avatar-motion-lift-y: 0px;
    --avatar-combat-scale: 1;
    --avatar-combat-scale-hit: var(--avatar-combat-scale);
    --avatar-facing-scale-x: 1;
    --avatar-slash-left: -26px;
    --avatar-slash-top: 10px;
    --avatar-foot-shadow-left: 50%;
    --avatar-foot-shadow-width: 58px;
    --avatar-foot-shadow-height: 12px;
    --avatar-foot-shadow-bottom: -4px;
    transform: translateX(var(--avatar-attack-start-x)) translateY(var(--avatar-attack-y)) scale(var(--avatar-combat-scale)) scaleX(var(--avatar-facing-scale-x));
    transform-origin: center bottom;
    isolation: isolate;
}

.avatar-combat-actor.is-avatar-attack-right {
    --avatar-attack-x: 34px;
    --avatar-attack-recoil-x: 24px;
}

.avatar-combat-actor.is-avatar-attacking {
    animation: avatarCombatAttack var(--avatar-attack-duration) cubic-bezier(0.2, 0.76, 0.24, 1) both;
}

.avatar-combat-actor.is-avatar-attacking.is-avatar-weapon-unarmed {
    animation-name: avatarCombatUnarmed;
}

.avatar-combat-actor.is-avatar-attacking.is-avatar-weapon-sword {
    animation-name: avatarCombatSword;
}

.avatar-combat-actor.is-avatar-attacking.is-avatar-weapon-dagger {
    animation-name: avatarCombatDagger;
}

.avatar-combat-actor.is-avatar-attacking.is-avatar-weapon-polearm {
    animation-name: avatarCombatPolearm;
}

.avatar-combat-actor.is-avatar-attacking.is-avatar-weapon-blunt {
    animation-name: avatarCombatBlunt;
}

.avatar-combat-actor.is-avatar-attacking.is-avatar-weapon-axe {
    animation-name: avatarCombatAxe;
}

.avatar-combat-actor.is-avatar-attacking.is-avatar-weapon-sword-big {
    animation-name: avatarCombatGreatsword;
}

.avatar-combat-actor.is-avatar-attacking.is-avatar-weapon-axe-big {
    animation-name: avatarCombatGreataxe;
}

.avatar-combat-actor.is-avatar-attacking.is-avatar-weapon-staff {
    animation-name: avatarCombatStaff;
}

.avatar-combat-actor.is-avatar-attacking.is-avatar-weapon-wand {
    animation-name: avatarCombatWand;
}

.avatar-combat-actor.is-avatar-attacking.is-avatar-weapon-bow {
    animation-name: avatarCombatBow;
}

.avatar-combat-actor.is-avatar-attacking.is-avatar-weapon-gun {
    animation-name: avatarCombatGun;
}

.avatar-combat-actor.is-avatar-attacking.is-avatar-weapon-gun-big {
    animation-name: avatarCombatBigGun;
}

.avatar-combat-actor.is-avatar-attacking.is-avatar-weapon-shield {
    animation-name: avatarCombatShield;
}

.avatar-combat-actor::before {
    content: "";
    position: absolute;
    left: var(--avatar-foot-shadow-left);
    bottom: var(--avatar-foot-shadow-bottom);
    z-index: 0;
    width: var(--avatar-foot-shadow-width);
    height: var(--avatar-foot-shadow-height);
    pointer-events: none;
    border-radius: 50%;
    background:
        radial-gradient(ellipse, rgba(0, 0, 0, 0.54), rgba(0, 0, 0, 0.28) 48%, transparent 72%),
        radial-gradient(ellipse, rgba(248, 216, 136, 0.14), transparent 62%);
    transform: translateX(-50%) scaleX(var(--avatar-foot-shadow-scale-x, 1));
    transform-origin: center;
}

.avatar-combat-actor::after {
    content: "";
    position: absolute;
    left: var(--avatar-slash-left);
    top: var(--avatar-slash-top);
    width: 48px;
    height: 34px;
    opacity: 0;
    pointer-events: none;
    border-top: 3px solid rgba(254, 243, 199, 0.95);
    border-right: 2px solid rgba(251, 191, 36, 0.72);
    border-radius: 50%;
    filter: drop-shadow(0 0 8px rgba(250, 204, 21, 0.82));
    transform: rotate(-24deg) scale(0.5);
