    top: 9px;
    left: 4px;
    display: none;
    width: 56px;
    height: 55px;
    pointer-events: none;
    background-image: url("./Sprites/Characters/body/death.png");
    background-repeat: no-repeat;
    background-position: 0 0;
    background-size: 448px 110px;
    image-rendering: pixelated;
}

