.inventory-loadout-stats {
    width: 100%;
    align-self: stretch;
    margin: 6px 0 10px;
}

.inventory-stats-header {
    margin-bottom: 10px;
}

.stats-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
    width: 100%;
}

.stat-item {
    background: linear-gradient(180deg, rgba(15, 23, 42, 0.92), rgba(22, 32, 52, 0.92));
    padding: 12px 10px;
    border-radius: 14px;
    display: flex;
    flex-direction: column;
    gap: 6px;
    border: 1px solid rgba(148, 163, 184, 0.14);
    position: relative;
    overflow: hidden;
}

.stat-item[data-stat="atk"] { border-color: rgba(239, 68, 68, 0.35); }
.stat-item[data-stat="def"] { border-color: rgba(59, 130, 246, 0.35); }
.stat-item[data-stat="agi"] { border-color: rgba(16, 185, 129, 0.35); }
.stat-item[data-stat="int"] { border-color: rgba(139, 92, 246, 0.35); }

.stat-label {
    font-size: 11px;
    font-weight: 700;
    color: var(--text-sub);
    display: flex;
    align-items: center;
    gap: 5px;
    letter-spacing: 0.04em;
}

.stat-item[data-stat="atk"] .stat-label { color: #fca5a5; }
.stat-item[data-stat="def"] .stat-label { color: #93c5fd; }
.stat-item[data-stat="agi"] .stat-label { color: #6ee7b7; }
.stat-item[data-stat="int"] .stat-label { color: #c4b5fd; }

.stat-value {
    font-size: 22px;
    font-weight: 900;
    color: #f8fafc;
    line-height: 1;
}

.stat-item[data-stat="atk"] .stat-value { color: #fca5a5; }
.stat-item[data-stat="def"] .stat-value { color: #93c5fd; }
.stat-item[data-stat="agi"] .stat-value { color: #6ee7b7; }
.stat-item[data-stat="int"] .stat-value { color: #c4b5fd; }

.stat-value-group {
    display: inline-flex;
    align-items: baseline;
    gap: 6px;
}
.stat-bonus {
    font-size: 12px;
    color: var(--hp-color);
    font-weight: 700;
}
.stat-bonus.is-zero {
    color: var(--text-sub);
}

/* セクションヘッダー共通 */
.section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 10px;
}

.section-header-btn {
    padding: 6px 12px;
    font-size: 12px;
    min-height: 32px;
    border-radius: 999px;
    background: rgba(31, 41, 55, 0.9);
    border: 1px solid var(--border-color);
    color: var(--text-main);
    box-shadow: none;
}

.section-header-btn::before {
    content: "";
    width: 18px;
    height: 18px;
    display: inline-block;
    margin-right: 5px;
    vertical-align: -4px;
    background: url("./assets/ui/buttons/action-refresh.png") center / contain no-repeat;
    filter: drop-shadow(0 1px 1px rgba(0, 0, 0, 0.45));
}

/* インベントリソートセレクト */
.sort-select {
    background: #374151;
    color: #fff;
    border: 1px solid var(--border-color);
    padding: 5px 8px;
    border-radius: 8px;
    font-size: 12px;
    font-family: 'Noto Sans JP', sans-serif;
}

#pointMessage {
    font-size: 12px;
    color: var(--text-sub);
    margin: 4px 0 10px;
}


/* --- バトル --- */
#battleArea {
    background-color: #1a202c;
    border-left: none;
    padding: 0;
    border-radius: 4px;
    margin-bottom: 0;
    background: transparent;
}

/* --- 下部ナビゲーション --- */
#bottomNav {
    position: fixed;
    bottom: 8px;
    left: 8px;
    width: calc(100% - 16px);
    height: var(--nav-height);
    background: linear-gradient(180deg, rgba(12, 8, 5, 0.42), rgba(3, 3, 4, 0.82)),
        repeating-linear-gradient(90deg, rgba(108, 64, 28, 0.18) 0 30px, rgba(23, 12, 6, 0.14) 30px 60px);
    backdrop-filter: none;
    border-top: 1px solid rgba(220, 169, 82, 0.42);
    display: flex;
    justify-content: stretch;
    align-items: center;
    z-index: 900;
    padding-bottom: env(safe-area-inset-bottom);
    opacity: 0;
    transform: translateY(calc(100% + 12px));
    pointer-events: none;
    transition: transform 460ms cubic-bezier(0.22, 1.2, 0.36, 1), opacity 280ms ease;
    will-change: transform, opacity;
    gap: 5px;
    padding: 8px max(8px, env(safe-area-inset-left)) calc(8px + env(safe-area-inset-bottom)) max(8px, env(safe-area-inset-right));
    border-radius: 24px;
    border: 1px solid transparent;
    box-shadow: 0 -10px 24px rgba(0, 0, 0, 0.42);
    overflow: hidden;
    flex-wrap: nowrap;
    border-image: url("./assets/ui/panels/panel-plank-wide.png") 34 fill / 10px / 0 stretch;
}

body.tabs-ready #bottomNav {
    opacity: 1;
    transform: translateY(0);
    pointer-events: auto;
}

.nav-button {
    background: linear-gradient(180deg, rgba(69, 39, 19, 0.94), rgba(24, 15, 9, 0.98)),
