    border: 1px solid rgba(220, 169, 82, 0.38);
    box-shadow: inset 0 1px 0 rgba(255, 239, 192, 0.12);
    color: #f0d7a4;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 0;
    width: 72px;
    height: 68px;
    font-size: 10px;
    transition: transform 160ms ease, background 160ms ease, color 160ms ease, box-shadow 160ms ease;
    flex: 1 1 0;
    border-radius: 8px;
    gap: 2px;
    min-width: 0;
    max-width: none;
    overflow: hidden;
}

.nav-button.active {
    color: #fff1bd;
    background: linear-gradient(180deg, rgba(255, 244, 189, 0.22), rgba(113, 63, 18, 0.18)),
        radial-gradient(ellipse at 50% 0%, rgba(255, 225, 136, 0.18), transparent 58%);
    border-color: rgba(255, 229, 149, 0.78);
    box-shadow: 0 0 18px rgba(217, 164, 65, 0.28), inset 0 1px 0 rgba(255, 247, 214, 0.26);
    border: 1px solid transparent;
    border-image: url("./assets/ui/panels/panel-gold-square.png") 24 fill / 10px / 0 stretch;
