/* --- モーダル --- */
.modal-overlay {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(10, 12, 18, 0.7);
    backdrop-filter: blur(2px);
    z-index: 4000;
    align-items: center;
    justify-content: center;
    opacity: 0;
    transition: opacity 0.2s ease-in;
    inset: 0;
    pointer-events: auto;
}

.modal-overlay[style*="display: flex"] {
    opacity: 1;
}

.modal-content {
    background: var(--card-bg);
    color: var(--text-main);
    width: 90%;
    max-width: 360px;
    border-radius: 16px;
    padding: 24px;
    border: 1px solid var(--border-color);
    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.5);
    text-align: center;
}

.modal-buttons {
    display: flex;
    gap: 12px;
    justify-content: center;
    margin-top: 20px;
}

.modal-buttons button {
    flex: 1;
}

#btnCancelTransfer, #btnCancelSell {
    background: #4b5563;
}

.world-map-modal-card {
    width: min(640px, 92vw);
    max-height: 85vh;
    overflow: auto;
    background: #0b1220;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 16px;
    padding: 16px;
    color: #fff;
    box-shadow: 0 12px 20px rgba(0, 0, 0, 0.45);
}

.world-map-modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 12px;
}

.world-map-modal-title {
    font-size: 16px;
    font-weight: 700;
}

.world-map-modal-close {
    background: transparent;
    color: #fff;
    border: none;
    font-size: 18px;
    cursor: pointer;
}

.world-map-modal-grid {
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    grid-template-rows: repeat(5, minmax(0, 1fr));
    gap: 8px;
    width: 100%;
    aspect-ratio: 3 / 5;
}

.world-map-modal-cell {
    background: rgba(15, 23, 42, 0.45);
    border: 1px solid rgba(148, 163, 184, 0.25);
    border-radius: 10px;
    padding: 10px 8px 12px;
    font-size: 12px;
    text-align: center;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-end;
    line-height: 1.35;
    position: relative;
    z-index: 0;
}

.world-map-modal-cell.is-capital {
    background: rgba(59, 130, 246, 0.2);
    border-color: rgba(96, 165, 250, 0.6);
    font-weight: 700;
}

.world-map-modal-cell.is-world {
    background: rgba(245, 158, 11, 0.2);
    border-color: rgba(251, 191, 36, 0.6);
    font-weight: 700;
}

.world-map-modal-cell.has-tarot::before {
    content: '';
    position: absolute;
    left: 50%;
    top: 8px;
    width: var(--tarot-tile-w, 48px);
    height: var(--tarot-tile-h, 80px);
    transform: translateX(-50%);
    background-image: url('Sprites/Buildings/tarot.png');
    background-repeat: no-repeat;
    background-size: var(--tarot-sheet-w, 480px) var(--tarot-sheet-h, 960px);
    background-position: calc(var(--tarot-x, 0px) * -1) calc(var(--tarot-y, 0px) * -1);
    z-index: 0;
    image-rendering: pixelated;
}

.world-map-modal-label {
    position: relative;
    z-index: 2;
    margin-top: auto;
    display: inline-block;
    max-width: 100%;
    padding: 3px 6px;
    font-weight: 700;
    font-size: clamp(9px, 2.2vw, 12px);
    color: rgba(248, 250, 252, 0.95);
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.6);
    background: rgba(15, 23, 42, 0.75);
    border: 1px solid rgba(148, 163, 184, 0.4);
    border-radius: 8px;
    box-sizing: border-box;
    white-space: nowrap;
}

.world-map-modal-cell.has-tarot {
    padding-top: calc(var(--tarot-tile-h, 80px) + 10px);
}

.world-map-modal-cell.is-current {
    border-color: #ffffff;
    box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.6), 0 0 12px rgba(255, 255, 255, 0.5);
}

.world-map-modal-cell.is-selected {
    border-color: #38bdf8;
    box-shadow: 0 0 0 2px rgba(56, 189, 248, 0.6), 0 0 12px rgba(56, 189, 248, 0.45);
}

.world-map-modal-cell.is-occupied-fire {
    background: rgba(239, 68, 68, 0.22);
}

.world-map-modal-cell.is-occupied-water {
    background: rgba(59, 130, 246, 0.22);
}

.world-map-modal-cell.is-occupied-earth {
    background: rgba(34, 197, 94, 0.22);
}

.world-map-modal-cell.is-occupied-wind {
    background: rgba(245, 158, 11, 0.22);
}

.world-map-modal-cell.is-occupied-neutral {
    background: rgba(148, 163, 184, 0.18);
}

.world-map-modal-cell[data-letter]::after {
    content: attr(data-letter);
    position: absolute;
    bottom: 6px;
    left: 8px;
    font-size: 10px;
    font-weight: 700;
    color: rgba(226, 232, 240, 0.9);
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.6);
    z-index: 3;
}

.world-map-modal-note {
    margin-top: 12px;
    font-size: 11px;
    color: var(--text-sub);
    text-align: center;
}

body.modal-lock {
    overflow: hidden;
    touch-action: none;
}

body.modal-lock #tabContainer,
body.modal-lock #globalStatusBar,
body.modal-lock #bottomNav,
body.modal-lock #phaser-container,
body.modal-lock canvas {
    pointer-events: none;
}

body.modal-lock .modal-overlay {
    pointer-events: auto;
}

/* チャット */
#tabContentMap {
