/* バトル画面調整 */
/* 順位切り替えボタン */
#rankingToggleButtons {
    display: grid;
    margin-bottom: 12px;
    background: linear-gradient(180deg, rgba(8, 11, 14, 0.94), rgba(2, 4, 7, 0.98));
    padding: 0;
    border-radius: 8px;
    gap: 0;
    overflow-x: auto;
    scrollbar-width: none;
