.ranking-toggle-btn.active {
    background: linear-gradient(180deg, rgba(255, 227, 139, 0.18), rgba(86, 48, 12, 0.18));
    color: #fff1c2;
    box-shadow: inset 0 1px 0 rgba(255, 247, 214, 0.28);
    border-color: rgba(255, 229, 149, 0.74);
    text-shadow: 0 2px 0 rgba(0, 0, 0, 0.78), 0 0 8px rgba(255, 222, 128, 0.28);
}

.rank-icon {
