}

.map-loading-overlay {
    position: absolute;
    inset: 0;
    background: radial-gradient(circle at 30% 20%, rgba(15, 23, 42, 0.95), #020617 55%, #000 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1200;
    opacity: 1;
    transition: opacity 0.4s ease;
}

.map-loading-overlay.is-modal {
    position: fixed;
    z-index: 4000;
    opacity: 1;
    pointer-events: auto;
}

.map-loading-world {
    position: relative;
    width: min(90vw, 72vh, 520px);
    aspect-ratio: 3 / 5;
    border-radius: 18px;
    border: 1px solid rgba(148, 163, 184, 0.4);
    background: linear-gradient(145deg, rgba(15, 23, 42, 0.9), rgba(2, 6, 23, 0.95));
    box-shadow: 0 20px 40px rgba(0, 0, 0, 0.45);
    overflow: hidden;
    transform: scale(1);
    opacity: 1;
}

.map-loading-status {
    position: absolute;
    top: 10px;
    left: 50%;
    transform: translateX(-50%);
    padding: 6px 12px;
    border-radius: 999px;
    background: rgba(15, 23, 42, 0.8);
    border: 1px solid rgba(148, 163, 184, 0.45);
    color: #f8fafc;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.08em;
    z-index: 4;
    transition: opacity 0.25s ease;
}

.map-loading-status.is-hidden {
    opacity: 0;
    pointer-events: none;
}

.map-loading-world.is-animating {
    animation: mapZoomIn 1.35s ease forwards;
}

.map-loading-close {
    position: absolute;
    top: 4px;
    right: 4px;
    display: none;
    z-index: 2;
}

.map-loading-overlay.is-modal .map-loading-close {
    display: inline-flex;
}

.map-loading-grid {
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(to right, rgba(148, 163, 184, 0.25) 1px, transparent 1px),
        linear-gradient(to bottom, rgba(148, 163, 184, 0.25) 1px, transparent 1px);
    background-size: 20% 20%;
    opacity: 0.8;
}

.map-loading-world .world-map-modal-grid {
    position: absolute;
    inset: 0;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    grid-template-rows: repeat(5, minmax(0, 1fr));
    gap: 6px;
    padding: 10px;
    pointer-events: none;
}

.map-loading-world .world-map-modal-cell {
    padding: 8px 6px 10px;
    border: 1px solid rgba(148, 163, 184, 0.08);
    line-height: 1.2;
    font-size: 10px;
    color: rgba(226, 232, 240, 0.9);
    background: rgba(15, 23, 42, 0.35);
    align-items: center;
    justify-content: flex-end;
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.6);
}


.map-loading-world .world-map-modal-cell.is-capital {
    color: #fde68a;
    font-weight: 700;
}

.map-loading-world .world-map-modal-cell.is-world {
    color: #fca5a5;
    font-weight: 700;
}

.map-loading-world .world-map-modal-cell.is-current {
    border-color: rgba(255, 255, 255, 0.9);
    box-shadow: inset 0 0 8px rgba(255, 255, 255, 0.5);
}

.map-loading-world .world-map-modal-cell.is-occupied-fire {
    background: rgba(239, 68, 68, 0.22);
}

.map-loading-world .world-map-modal-cell.is-occupied-water {
    background: rgba(59, 130, 246, 0.22);
}

.map-loading-world .world-map-modal-cell.is-occupied-earth {
    background: rgba(34, 197, 94, 0.22);
}

.map-loading-world .world-map-modal-cell.is-occupied-wind {
    background: rgba(245, 158, 11, 0.22);
}

.map-loading-world .world-map-modal-cell.is-occupied-neutral {
    background: rgba(148, 163, 184, 0.18);
}


.map-loading-labels {
    position: absolute;
    left: 12px;
    bottom: 12px;
    display: grid;
    gap: 4px;
    padding: 8px 10px;
    border-radius: 10px;
    background: rgba(15, 23, 42, 0.75);
    border: 1px solid rgba(148, 163, 184, 0.3);
    color: #f8fafc;
}

.map-loading-title {
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.12em;
}

.map-loading-current {
    font-size: 12px;
    font-weight: 600;
}

.map-loading-sub {
    font-size: 11px;
    color: rgba(226, 232, 240, 0.7);
}

@keyframes mapZoomIn {
    0% {
        transform: scale(1);
        opacity: 1;
    }
    70% {
        transform: scale(2.1);
        opacity: 0.95;
    }
    100% {
        transform: scale(2.4);
        opacity: 0.85;
    }
}


.modal-overlay.active {
    display: flex;
}

.player-link {
    background: none;
    border: none;
