}

.tarot-poker-root {
    overflow: visible;
    position: relative;
    --tarot-card-w: 54px;
    --tarot-card-h: 88px;
    --tarot-art-w: 48px;
    --tarot-art-h: 80px;
    --tarot-art-left: 5px;
    --tarot-art-top: 8px;
    --tarot-card-radius: 10px;
    --tarot-card-padding: 4px;
    --tarot-card-number-size: 22px;
    --tarot-card-title-size: 10px;
    --tarot-interact-border: rgba(244, 114, 182, 0.95);
    --tarot-interact-border-soft: rgba(244, 114, 182, 0.78);
    --tarot-interact-glow: rgba(236, 72, 153, 0.45);
    --tarot-interact-selected: rgba(255, 225, 244, 0.98);
}

.tarot-kingdom-root {
    --tarot-card-w: 54px;
    --tarot-card-h: 88px;
    --tarot-art-w: 48px;
    --tarot-art-h: 80px;
    --tarot-kingdom-mobile-height: auto;
    padding-bottom: calc(env(safe-area-inset-bottom, 0px) + 136px);
}

.tarot-kingdom-root.is-trick-shake-normal {
    animation: tarotKingdomTrickShakeNormal 100ms ease-out 1;
}

.tarot-kingdom-root.is-trick-shake-special {
    animation: tarotKingdomTrickShakeSpecial 150ms ease-out 1;
}

.tarot-kingdom-root.is-trick-shake-heavy {
    animation: tarotKingdomTrickShakeHeavy 190ms ease-out 1;
}

.tarot-kingdom-root.is-trick-shake-ultra {
    animation: tarotKingdomTrickShakeUltra 230ms cubic-bezier(0.2, 0.84, 0.24, 1) 1;
}

.tarot-kingdom-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 6px;
    margin-bottom: 5px;
}

.tarot-kingdom-header h2 {
    margin: 0;
    font-size: clamp(13px, 1.7vw, 16px);
    line-height: 1.1;
}

.tarot-kingdom-title-wrap {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    min-width: 0;
}

.tarot-kingdom-header-meta {
    display: flex;
    gap: 4px;
    flex-wrap: wrap;
    justify-content: flex-end;
}

.tarot-kingdom-chip {
    display: inline-flex;
    align-items: center;
    min-height: 21px;
    padding: 0 8px;
    border-radius: 999px;
    border: 1px solid rgba(255, 255, 255, 0.22);
    background: rgba(15, 23, 42, 0.62);
    color: #e5e7eb;
    font-size: 11px;
    font-weight: 700;
}

.tarot-kingdom-chip--reverse {
    border-color: rgba(251, 191, 36, 0.78);
    background: linear-gradient(180deg, rgba(113, 63, 18, 0.7), rgba(120, 53, 15, 0.84));
    color: #fde68a;
    text-shadow: 0 1px 1px rgba(0, 0, 0, 0.55);
    box-shadow:
        0 0 0 1px rgba(251, 191, 36, 0.24),
        0 0 14px rgba(251, 191, 36, 0.26);
    animation: tarotKingdomReversePulse 1.2s ease-in-out infinite;
}

.tarot-kingdom-chip--lock {
    border-color: rgba(148, 163, 184, 0.72);
    background: linear-gradient(180deg, rgba(30, 41, 59, 0.74), rgba(15, 23, 42, 0.82));
    color: #e2e8f0;
    text-shadow: 0 1px 1px rgba(0, 0, 0, 0.45);
}

.tarot-kingdom-chip--lock.is-lock-wand {
    border-color: rgba(220, 38, 38, 0.78);
    background: linear-gradient(180deg, rgba(127, 29, 29, 0.76), rgba(153, 27, 27, 0.84));
    color: #fecaca;
}

.tarot-kingdom-chip--lock.is-lock-cup {
    border-color: rgba(37, 99, 235, 0.78);
    background: linear-gradient(180deg, rgba(30, 64, 175, 0.76), rgba(29, 78, 216, 0.84));
    color: #bfdbfe;
}

.tarot-kingdom-chip--lock.is-lock-sword {
    border-color: rgba(217, 119, 6, 0.78);
    background: linear-gradient(180deg, rgba(146, 64, 14, 0.78), rgba(180, 83, 9, 0.86));
    color: #fde68a;
}

.tarot-kingdom-chip--lock.is-lock-pentacle {
    border-color: rgba(22, 163, 74, 0.78);
    background: linear-gradient(180deg, rgba(21, 128, 61, 0.76), rgba(22, 163, 74, 0.84));
    color: #bbf7d0;
}

.tarot-kingdom-chip--owner {
    border-color: rgba(148, 163, 184, 0.64);
    background: linear-gradient(180deg, rgba(30, 41, 59, 0.72), rgba(15, 23, 42, 0.8));
    color: #cbd5e1;
    max-width: min(58vw, 420px);
    justify-content: flex-start;
    text-align: left;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.tarot-kingdom-chip--chain {
    border-color: rgba(250, 204, 21, 0.82);
    background: linear-gradient(180deg, rgba(88, 28, 135, 0.9), rgba(49, 10, 101, 0.94));
    color: #fff7c2;
    font-family: "Times New Roman", serif;
    font-weight: 900;
    letter-spacing: 0.08em;
    text-shadow: 0 1px 2px #000, 0 0 7px rgba(250, 204, 21, 0.72);
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.12), 0 0 10px rgba(168, 85, 247, 0.38);
}

.tarot-kingdom-chip--chain[data-chain-level="3"] {
    border-color: rgba(216, 180, 254, 0.9);
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.16), 0 0 13px rgba(192, 132, 252, 0.58);
}

.tarot-kingdom-chip--chain[data-chain-level="4"] {
    border-color: rgba(254, 240, 138, 0.96);
    background: linear-gradient(180deg, rgba(153, 27, 27, 0.94), rgba(76, 5, 25, 0.96));
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.2), 0 0 16px rgba(251, 113, 133, 0.64);
}

.tarot-kingdom-root.is-reverse .tarot-kingdom-panel {
    border-color: rgba(251, 191, 36, 0.4);
    box-shadow: inset 0 0 0 1px rgba(251, 191, 36, 0.14);
}

@keyframes tarotKingdomReversePulse {
    0%,
    100% {
        transform: translateY(0);
        filter: saturate(1);
    }
    50% {
        transform: translateY(-1px);
        filter: saturate(1.15);
    }
}

.tarot-kingdom-controls {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
    align-items: flex-start;
    margin-bottom: 8px;
}

.tarot-kingdom-controls[hidden],
