    box-shadow:
        0 0 0 1px rgba(5, 46, 22, 0.55),
        0 3px 10px rgba(0, 0, 0, 0.45);
    pointer-events: none;
    z-index: 6;
}

.tarot-kingdom-hand .tarot-card.is-opening-flip {
    /*
     * The sheet contains the back-to-face turn at indices 110-119, followed by
     * the complete blank face at index 105. The button itself never transforms.
     */
    animation: none !important;
    isolation: isolate;
    transform: none;
}

.tarot-kingdom-hand .tarot-card.is-opening-flip > .tarot-card-art:not(.tarot-card-flip-sprite),
.tarot-kingdom-hand .tarot-card.is-opening-flip > .tarot-card-title,
.tarot-kingdom-hand .tarot-card.is-opening-flip > .tarot-card-number,
.tarot-kingdom-hand .tarot-card.is-opening-flip > .tarot-card-ap-cost {
    animation: tarotKingdomCardFaceReveal var(--tk-card-flip-duration, 330ms) steps(1, end) both;
}

.tarot-kingdom-hand .tarot-card.is-opening-flip > .tarot-card-flip-sprite {
    z-index: 20;
    pointer-events: none;
    animation: tarotKingdomCardSpriteFlip var(--tk-card-flip-duration, 330ms) steps(1, end) both;
    will-change: background-position, opacity;
}

@keyframes tarotKingdomCardSpriteFlip {
    0% { background-position: 0 -880px; opacity: 1; }
    9% { background-position: -48px -880px; }
    18% { background-position: -96px -880px; }
    27% { background-position: -144px -880px; }
    36% { background-position: -192px -880px; }
    45% { background-position: -240px -880px; }
    54% { background-position: -288px -880px; }
    63% { background-position: -336px -880px; }
    72% { background-position: -384px -880px; }
    81% { background-position: -432px -880px; }
    90% { background-position: calc(var(--tarot-flip-face-x, 240px) * -1) calc(var(--tarot-flip-face-y, 800px) * -1); opacity: 1; }
    100% { background-position: calc(var(--tarot-flip-face-x, 240px) * -1) calc(var(--tarot-flip-face-y, 800px) * -1); opacity: 0; }
}

@keyframes tarotKingdomCardFaceReveal {
    0%,
    90% {
        opacity: 0;
    }

    100% {
        opacity: 1;
    }
}

@media (prefers-reduced-motion: reduce) {
    .tarot-kingdom-hand .tarot-card.is-opening-flip > .tarot-card-art,
    .tarot-kingdom-hand .tarot-card.is-opening-flip > .tarot-card-title,
    .tarot-kingdom-hand .tarot-card.is-opening-flip > .tarot-card-number,
    .tarot-kingdom-hand .tarot-card.is-opening-flip > .tarot-card-ap-cost {
        animation: none !important;
        opacity: 1;
    }

    .tarot-kingdom-hand .tarot-card.is-opening-flip > .tarot-card-flip-sprite {
        display: none;
    }
}

/* Five-card role formation: build the hand on the field before it becomes a summon seal. */
:is(body, #tabContentTarot) #tarotKingdomRoot.tarot-kingdom-reference-ui.tarot-kingdom-reference-v2
    #tarotKingdomTrick > .tarot-card.is-role-field-clearing {
    pointer-events: none;
    transform-origin: 50% 100%;
    animation: tarotKingdomRoleFieldClear var(--role-field-clear-ms, 160ms) cubic-bezier(0.4, 0, 0.78, 0.34) forwards !important;
    animation-play-state: running !important;
}

:is(body, #tabContentTarot) #tarotKingdomRoot.tarot-kingdom-reference-ui.tarot-kingdom-reference-v2
    #tarotKingdomTrick > .tarot-card.is-role-arriving {
    opacity: 0;
    pointer-events: none;
    transform-origin: 50% 68%;
    animation-timing-function: cubic-bezier(0.16, 0.84, 0.22, 1) !important;
    animation-fill-mode: both !important;
    animation-play-state: running !important;
    backface-visibility: hidden;
    will-change: transform, opacity;
}

:is(body, #tabContentTarot) #tarotKingdomRoot.tarot-kingdom-reference-ui.tarot-kingdom-reference-v2
    #tarotKingdomTrick > .tarot-card.is-role-entry-from-right {
    animation-name: tarotKingdomRoleCardFromRight !important;
}

:is(body, #tabContentTarot) #tarotKingdomRoot.tarot-kingdom-reference-ui.tarot-kingdom-reference-v2
    #tarotKingdomTrick > .tarot-card.is-role-entry-from-top {
    animation-name: tarotKingdomRoleCardFromTop !important;
}

:is(body, #tabContentTarot) #tarotKingdomRoot.tarot-kingdom-reference-ui.tarot-kingdom-reference-v2
    #tarotKingdomTrick > .tarot-card.is-role-entry-fade {
    animation-name: tarotKingdomRoleCardFade !important;
}

:is(body, #tabContentTarot) #tarotKingdomRoot.tarot-kingdom-reference-ui.tarot-kingdom-reference-v2
    #tarotKingdomTrick > .tarot-card.is-role-entry-slam {
    animation-name: tarotKingdomRoleCardSlam !important;
}

:is(body, #tabContentTarot) #tarotKingdomRoot.tarot-kingdom-reference-ui.tarot-kingdom-reference-v2
    #tarotKingdomTrick > .tarot-card.is-role-entry-orbit {
    animation-name: tarotKingdomRoleCardOrbit !important;
}

:is(body, #tabContentTarot) #tarotKingdomRoot.tarot-kingdom-reference-ui.tarot-kingdom-reference-v2
    #tarotKingdomTrick > .tarot-card.is-role-entry-fan-left {
    animation-name: tarotKingdomRoleCardFanLeft !important;
}

:is(body, #tabContentTarot) #tarotKingdomRoot.tarot-kingdom-reference-ui.tarot-kingdom-reference-v2
    #tarotKingdomTrick > .tarot-card.is-role-entry-fan-right {
    animation-name: tarotKingdomRoleCardFanRight !important;
}

:is(body, #tabContentTarot) #tarotKingdomRoot.tarot-kingdom-reference-ui.tarot-kingdom-reference-v2
    #tarotKingdomTrick > .tarot-card.is-role-entry-converge {
    animation-name: tarotKingdomRoleCardConverge !important;
}

@keyframes tarotKingdomRoleFieldClear {
    0% { opacity: 1; transform: translate3d(0, 0, 0) scale(1); filter: brightness(1); }
    100% { opacity: 0; transform: translate3d(-10px, 12px, 0) scale(0.9) rotate(-2deg); filter: brightness(0.55) saturate(0.6); }
}

@keyframes tarotKingdomRoleCardFromRight {
    0% { opacity: 0; transform: translate3d(92px, -4px, 0) rotate(9deg) scale(0.9); }
    68% { opacity: 1; transform: translate3d(-3px, 0, 0) rotate(-1deg) scale(1.025); }
    100% { opacity: 1; transform: none; }
}

@keyframes tarotKingdomRoleCardFromTop {
    0% { opacity: 0; transform: translate3d(0, -82px, 0) rotate(calc(var(--role-entry-angle, 0deg) * 0.35)) scale(0.94); }
    70% { opacity: 1; transform: translate3d(0, 4px, 0) rotate(0deg) scale(1.035); }
    84% { opacity: 1; transform: translate3d(0, -2px, 0) scale(0.99); }
    100% { opacity: 1; transform: none; }
}

@keyframes tarotKingdomRoleCardFade {
    0% { opacity: 0; transform: scale(0.96); filter: brightness(1.65) saturate(0.82); }
    58% { opacity: 1; transform: scale(1.025); filter: brightness(1.24) saturate(1.08); }
    100% { opacity: 1; transform: none; filter: none; }
}

@keyframes tarotKingdomRoleCardSlam {
    0% { opacity: 0; transform: translate3d(0, -66px, 0) scale(1.08); }
    58% { opacity: 1; transform: translate3d(0, 5px, 0) scale(0.98); }
    72% { opacity: 1; transform: translate3d(calc(var(--role-entry-direction, 1) * 2px), -2px, 0) scale(1.025); }
    100% { opacity: 1; transform: none; }
}

@keyframes tarotKingdomRoleCardOrbit {
    0% {
        opacity: 0;
        transform: translate3d(calc(var(--role-entry-direction, 1) * 76px), -38px, 0)
            rotate(calc(var(--role-entry-angle, 0deg) + 34deg)) scale(0.68);
    }
    62% { opacity: 1; transform: translate3d(calc(var(--role-entry-direction, 1) * -4px), 2px, 0) rotate(-2deg) scale(1.03); }
    100% { opacity: 1; transform: none; }
}

@keyframes tarotKingdomRoleCardFanLeft {
    0% { opacity: 0; transform: translate3d(-78px, 28px, 0) rotate(-22deg) scale(0.82); }
    68% { opacity: 1; transform: translate3d(3px, -2px, 0) rotate(2deg) scale(1.025); }
    100% { opacity: 1; transform: none; }
}

@keyframes tarotKingdomRoleCardFanRight {
    0% { opacity: 0; transform: translate3d(78px, 28px, 0) rotate(22deg) scale(0.82); }
    68% { opacity: 1; transform: translate3d(-3px, -2px, 0) rotate(-2deg) scale(1.025); }
    100% { opacity: 1; transform: none; }
}

@keyframes tarotKingdomRoleCardConverge {
    0% {
        opacity: 0;
        transform: translate3d(calc(var(--role-entry-direction, 1) * 58px), -52px, 0)
            rotate(var(--role-entry-angle, 0deg)) scale(0.72);
    }
    62% { opacity: 1; transform: translate3d(0, 3px, 0) rotate(0) scale(1.06); }
    78% { opacity: 1; transform: translate3d(0, -2px, 0) scale(0.99); }
    100% { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
    :is(body, #tabContentTarot) #tarotKingdomRoot.tarot-kingdom-reference-ui.tarot-kingdom-reference-v2
        #tarotKingdomTrick > .tarot-card:is(.is-role-field-clearing, .is-role-arriving) {
        animation: none !important;
        transform: none !important;
        filter: none !important;
    }

    :is(body, #tabContentTarot) #tarotKingdomRoot.tarot-kingdom-reference-ui.tarot-kingdom-reference-v2
        #tarotKingdomTrick > .tarot-card.is-role-field-clearing {
        opacity: 0 !important;
    }

    :is(body, #tabContentTarot) #tarotKingdomRoot.tarot-kingdom-reference-ui.tarot-kingdom-reference-v2
        #tarotKingdomTrick > .tarot-card.is-role-arriving {
        opacity: 1 !important;
    }
}

