.tarot-kingdom-trick {
    --kingdom-field-scene: url("./assets/ui/tarot-kingdom/field-calm-sea.webp");
    --kingdom-field-tint: linear-gradient(transparent, transparent);
    --kingdom-field-shade: linear-gradient(180deg, rgba(2, 6, 23, 0.28), rgba(2, 6, 23, 0.5));
    --kingdom-field-glow: rgba(56, 189, 248, 0.12);
    --kingdom-field-position: center, center, center;
    --kingdom-field-size: 100% 100%, 100% 100%, cover;
    --kingdom-field-motion-y: 50%;
    --kingdom-role-chain-ring-width: 0px;
    --kingdom-role-chain-ring-color: transparent;
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    min-height: calc(var(--tarot-card-h, 88px) + 4px);
    position: relative;
    isolation: isolate;
    overflow: visible;
    background-color: #020617;
    background-image:
        linear-gradient(transparent, transparent),
        linear-gradient(180deg, rgba(2, 6, 23, 0.28), rgba(2, 6, 23, 0.5)),
        url("./assets/ui/tarot-kingdom/field-calm-sea.webp");
    background-position: center;
    background-repeat: no-repeat;
    background-size: 100% 100%, 100% 100%, cover;
    border-radius: 10px;
    box-shadow:
        inset 0 0 0 1px rgba(255, 255, 255, 0.06),
        inset 0 -16px 24px rgba(2, 6, 23, 0.22),
        0 0 18px var(--kingdom-field-glow);
    transition: box-shadow 180ms ease;
}

.tarot-kingdom-field-scene-layer {
    position: absolute;
    inset: 0;
    z-index: 0;
    pointer-events: none;
    border-radius: inherit;
    background-repeat: no-repeat;
    opacity: 0;
    transition: opacity 420ms ease-in-out;
    will-change: opacity;
}

.tarot-kingdom-field-scene-layer.is-active {
    opacity: 1;
}

.tarot-kingdom-trick:not(.is-scene-world):not(.is-scene-cut):not(.is-scene-back)
    > .tarot-kingdom-field-scene-layer.is-active {
    animation: tarotKingdomSceneGentleFlow 2.4s cubic-bezier(0.45, 0.05, 0.55, 0.95) infinite;
}

.tarot-kingdom-trick > .tarot-card,
.tarot-kingdom-trick > .tarot-kingdom-field-slot {
    position: relative;
    z-index: 2;
}

.tarot-kingdom-trick.is-scene-role {
    --kingdom-field-shade: linear-gradient(180deg, rgba(2, 6, 23, 0.08), rgba(2, 6, 23, 0.34));
    --kingdom-field-glow: rgba(186, 230, 253, 0.24);
    --kingdom-role-suit-tint: rgba(186, 230, 253, 0.08);
    --kingdom-field-tint:
        radial-gradient(ellipse at 50% 58%, var(--kingdom-role-suit-tint), transparent 72%);
    --kingdom-field-position: center, center, center 58%;
    --kingdom-field-motion-y: 58%;
    animation: tarotKingdomSceneRolePulse 1.65s ease-in-out infinite alternate;
}

.tarot-kingdom-trick.is-scene-role[data-role-chain="2"] {
    --kingdom-role-chain-ring-width: 1px;
    --kingdom-role-chain-ring-color: rgba(250, 204, 21, 0.34);
}

.tarot-kingdom-trick.is-scene-role[data-role-chain="3"] {
    --kingdom-role-chain-ring-width: 2px;
    --kingdom-role-chain-ring-color: rgba(216, 180, 254, 0.46);
}

.tarot-kingdom-trick.is-scene-role[data-role-chain]:not([data-role-chain=""]):not([data-role-chain="2"]):not([data-role-chain="3"]) {
    --kingdom-role-chain-ring-width: 3px;
    --kingdom-role-chain-ring-color: rgba(254, 240, 138, 0.58);
}

.tarot-kingdom-trick.is-scene-role-straight {
    --kingdom-field-scene: url("./assets/ui/tarot-kingdom/field-role-straight.webp?v=2");
}

.tarot-kingdom-trick.is-scene-role-flush {
    --kingdom-field-scene: url("./assets/ui/tarot-kingdom/field-role-flush.webp");
}

.tarot-kingdom-trick.is-scene-role-full-house {
    --kingdom-field-scene: url("./assets/ui/tarot-kingdom/field-role-full-house.webp");
}

.tarot-kingdom-trick.is-scene-role-four-kind {
    --kingdom-field-scene: url("./assets/ui/tarot-kingdom/field-role-four-kind.webp");
}

.tarot-kingdom-trick.is-scene-role-world {
    --kingdom-field-scene: url("./assets/ui/tarot-kingdom/field-role-world.webp");
}

.tarot-kingdom-trick.is-scene-role-straight-flush {
    --kingdom-field-scene: url("./assets/ui/tarot-kingdom/field-role-straight-flush.webp");
}

.tarot-kingdom-trick.is-scene-role-five-kind {
    --kingdom-field-scene: url("./assets/ui/tarot-kingdom/field-role-five-kind.webp");
}

.tarot-kingdom-trick:is(.is-scene-role-flush, .is-scene-role-straight-flush).is-scene-role-suit-wand {
    --kingdom-role-suit-tint: rgba(211, 74, 64, 0.36);
    --kingdom-field-glow: rgba(211, 74, 64, 0.28);
}

.tarot-kingdom-trick:is(.is-scene-role-flush, .is-scene-role-straight-flush).is-scene-role-suit-cup {
    --kingdom-role-suit-tint: rgba(63, 137, 207, 0.36);
    --kingdom-field-glow: rgba(63, 137, 207, 0.3);
}

.tarot-kingdom-trick:is(.is-scene-role-flush, .is-scene-role-straight-flush).is-scene-role-suit-sword {
    --kingdom-role-suit-tint: rgba(155, 114, 230, 0.38);
    --kingdom-field-glow: rgba(155, 114, 230, 0.3);
}

.tarot-kingdom-trick:is(.is-scene-role-flush, .is-scene-role-straight-flush).is-scene-role-suit-pentacle {
    --kingdom-role-suit-tint: rgba(58, 166, 109, 0.36);
    --kingdom-field-glow: rgba(58, 166, 109, 0.28);
}

.tarot-kingdom-trick.is-scene-lock {
    --kingdom-field-scene: url("./assets/ui/tarot-kingdom/field-lock-rock.webp?v=3");
    --kingdom-field-shade: linear-gradient(180deg, rgba(15, 23, 42, 0.18), rgba(2, 6, 23, 0.42));
    --kingdom-field-glow: rgba(251, 191, 36, 0.22);
}

.tarot-kingdom-trick.is-scene-lock.is-scene-lock-wand {
    --kingdom-field-scene: url("./assets/ui/tarot-kingdom/field-lock-lava.webp");
    --kingdom-field-shade: linear-gradient(180deg, rgba(69, 10, 10, 0.12), rgba(20, 4, 4, 0.38));
    --kingdom-field-glow: rgba(248, 113, 113, 0.3);
}

.tarot-kingdom-trick.is-scene-lock.is-scene-lock-cup {
    --kingdom-field-scene: url("./assets/ui/tarot-kingdom/field-lock-ice.webp");
    --kingdom-field-shade: linear-gradient(180deg, rgba(14, 116, 144, 0.08), rgba(8, 47, 73, 0.38));
    --kingdom-field-glow: rgba(103, 232, 249, 0.28);
}

.tarot-kingdom-trick.is-scene-lock.is-scene-lock-sword {
    --kingdom-field-scene: url("./assets/ui/tarot-kingdom/field-lock-storm.webp");
    --kingdom-field-shade: linear-gradient(180deg, rgba(76, 29, 149, 0.08), rgba(30, 10, 58, 0.38));
    --kingdom-field-glow: rgba(196, 181, 253, 0.3);
}

.tarot-kingdom-trick.is-scene-lock.is-scene-lock-pentacle {
    --kingdom-field-scene: url("./assets/ui/tarot-kingdom/field-lock-rock.webp?v=3");
    --kingdom-field-shade: linear-gradient(180deg, rgba(63, 48, 24, 0.08), rgba(20, 36, 27, 0.38));
    --kingdom-field-glow: rgba(74, 222, 128, 0.26);
}

.tarot-kingdom-trick.is-scene-back {
    --kingdom-field-scene: url("./assets/ui/tarot-kingdom/field-reverse-whirlpool.webp");
    --kingdom-field-shade: radial-gradient(circle at 50% 52%, rgba(2, 6, 23, 0.04), rgba(2, 6, 23, 0.52) 76%);
    --kingdom-field-glow: rgba(251, 191, 36, 0.2);
    --kingdom-field-size: 100% 100%, 100% 100%, 108% 112%;
    --kingdom-field-position: center, center, 48.5% 49%;
}

.tarot-kingdom-trick.is-scene-back > .tarot-kingdom-field-scene-layer.is-active {
    animation: tarotKingdomSceneBackFlow 1.2s cubic-bezier(0.42, 0.02, 0.58, 0.98) infinite;
}

.tarot-kingdom-trick.is-scene-cut {
    --kingdom-field-scene: url("./assets/ui/tarot-kingdom/field-cut-crack.webp");
    --kingdom-field-shade: linear-gradient(180deg, rgba(2, 6, 23, 0.06), rgba(2, 6, 23, 0.4));
    --kingdom-field-glow: rgba(125, 211, 252, 0.3);
    animation: tarotKingdomSceneCutPulse 560ms ease-out 1;
}

.tarot-kingdom-trick.is-scene-cut > .tarot-kingdom-field-scene-layer {
    transition-duration: 0s;
}

.tarot-kingdom-trick.is-scene-skip {
    --kingdom-field-shade: linear-gradient(180deg, rgba(255, 255, 255, 0.02), rgba(2, 6, 23, 0.38));
    --kingdom-field-glow: rgba(186, 230, 253, 0.32);
}

.tarot-kingdom-trick.is-scene-skip::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 1;
    pointer-events: none;
    border-radius: inherit;
    background: url("./assets/ui/tarot-kingdom/field-skip-wave.webp") center 26% / cover no-repeat;
    opacity: 0;
    will-change: background-position, opacity;
    animation: tarotKingdomSceneSkipWave 900ms cubic-bezier(0.32, 0.02, 0.3, 1) 1 both;
}

.tarot-kingdom-trick.is-scene-skip > .tarot-card,
.tarot-kingdom-trick.is-scene-skip > .tarot-kingdom-field-slot {
    z-index: 2;
}

.tarot-kingdom-trick.is-scene-world {
    --kingdom-field-scene: url("./assets/ui/tarot-kingdom/field-world-clock.webp?v=2");
    --kingdom-field-shade: radial-gradient(circle at 50% 64%, rgba(2, 6, 23, 0.02), rgba(2, 6, 23, 0.5) 82%);
    --kingdom-field-glow: rgba(226, 232, 240, 0.24);
    animation: tarotKingdomSceneWorldStill 1.8s ease-in-out infinite alternate;
}

@keyframes tarotKingdomSceneBackFlow {
    0% {
        background-position: center, center, 46% 47.5%;
        box-shadow:
            inset 0 0 0 1px rgba(251, 191, 36, 0.12),
            inset 0 -16px 24px rgba(2, 6, 23, 0.2),
            0 0 12px rgba(251, 191, 36, 0.12);
    }
    22% {
        background-position: center, center, 53.5% 51.5%;
    }
    48% {
        background-position: center, center, 47.2% 54%;
        box-shadow:
            inset 0 0 0 1px rgba(251, 191, 36, 0.28),
            inset 0 -16px 24px rgba(2, 6, 23, 0.32),
            0 0 24px rgba(251, 191, 36, 0.22);
    }
    72% {
        background-position: center, center, 54% 46.5%;
    }
    100% {
        background-position: center, center, 46% 47.5%;
        box-shadow:
            inset 0 0 0 1px rgba(251, 191, 36, 0.12),
            inset 0 -16px 24px rgba(2, 6, 23, 0.2),
            0 0 12px rgba(251, 191, 36, 0.12);
    }
}

@keyframes tarotKingdomSceneGentleFlow {
    0%,
    100% {
        background-position: center, center, 49.4% var(--kingdom-field-motion-y);
    }
    28% {
        background-position: center, center, 50.7% calc(var(--kingdom-field-motion-y) + 0.5%);
    }
    56% {
        background-position: center, center, 49.7% calc(var(--kingdom-field-motion-y) + 1%);
    }
    78% {
        background-position: center, center, 50.5% calc(var(--kingdom-field-motion-y) - 0.4%);
    }
}

@media (prefers-reduced-motion: reduce) {
    .tarot-kingdom-field-scene-layer {
        transition: none;
    }

    .tarot-kingdom-trick.is-scene-back > .tarot-kingdom-field-scene-layer.is-active {
        animation: none;
        background-position: center, center, center;
    }

    .tarot-kingdom-trick:not(.is-scene-world):not(.is-scene-cut):not(.is-scene-back)
        > .tarot-kingdom-field-scene-layer.is-active {
        animation: none;
    }

    .tarot-kingdom-trick.is-scene-skip {
        animation: none;
        background-position: center, center, center;
    }

    .tarot-kingdom-trick.is-scene-skip::after {
        animation: none;
        background-position: center;
        opacity: 0.72;
    }

    .tarot-kingdom-trick.is-scene-role {
        animation: none;
        box-shadow:
            inset 0 0 0 var(--kingdom-role-chain-ring-width) var(--kingdom-role-chain-ring-color),
            inset 0 -12px 22px rgba(2, 6, 23, 0.18),
            0 0 14px var(--kingdom-field-glow);
    }
}

@keyframes tarotKingdomSceneRolePulse {
    from {
        box-shadow:
            inset 0 0 0 var(--kingdom-role-chain-ring-width) var(--kingdom-role-chain-ring-color),
            inset 0 0 0 1px rgba(186, 230, 253, 0.12),
            inset 0 -12px 22px rgba(2, 6, 23, 0.18),
            0 0 12px var(--kingdom-field-glow);
    }
    to {
        box-shadow:
            inset 0 0 0 calc(var(--kingdom-role-chain-ring-width) + 1px) var(--kingdom-role-chain-ring-color),
            inset 0 0 0 1px rgba(224, 242, 254, 0.25),
            inset 0 -12px 24px rgba(2, 6, 23, 0.28),
            0 0 24px var(--kingdom-field-glow);
    }
}

@keyframes tarotKingdomSceneCutPulse {
    0%,
    100% {
        box-shadow:
            inset 0 0 0 1px rgba(125, 211, 252, 0.12),
            0 0 14px rgba(125, 211, 252, 0.16);
    }
    50% {
        box-shadow:
            inset 0 0 0 2px rgba(224, 242, 254, 0.34),
            0 0 28px rgba(125, 211, 252, 0.38);
    }
}

@keyframes tarotKingdomSceneSkipWave {
    0% {
        background-position: center 26%;
        opacity: 0;
        box-shadow:
            inset 0 0 0 1px rgba(186, 230, 253, 0.08),
            0 0 8px rgba(186, 230, 253, 0.08);
    }
    12% {
        opacity: 0.82;
    }
    52% {
        background-position: center 78%;
        opacity: 1;
        box-shadow:
            inset 0 0 0 2px rgba(240, 249, 255, 0.4),
            0 0 32px rgba(125, 211, 252, 0.42);
    }
    86% {
        background-position: center 34%;
        opacity: 0.68;
        box-shadow:
            inset 0 0 0 1px rgba(224, 242, 254, 0.2),
            0 0 18px rgba(125, 211, 252, 0.22);
    }
    100% {
        background-position: center 26%;
        opacity: 0;
        box-shadow:
            inset 0 0 0 1px rgba(186, 230, 253, 0.1),
            0 0 12px rgba(186, 230, 253, 0.12);
    }
}

@keyframes tarotKingdomSceneWorldStill {
    from {
        box-shadow:
            inset 0 0 0 1px rgba(226, 232, 240, 0.12),
            inset 0 0 26px rgba(15, 23, 42, 0.22),
            0 0 12px rgba(226, 232, 240, 0.12);
    }
    to {
        box-shadow:
            inset 0 0 0 1px rgba(226, 232, 240, 0.26),
            inset 0 0 34px rgba(15, 23, 42, 0.38),
            0 0 22px rgba(226, 232, 240, 0.22);
    }
}

.tarot-kingdom-trick.is-clear-sweep::before {
