.tarot-pot-label {
    font-size: 11px;
    letter-spacing: 0.12em;
    color: rgba(254, 243, 199, 0.82);
    white-space: nowrap;
}

.tarot-pot-slit {
    display: inline-flex;
    align-items: baseline;
    justify-content: flex-end;
    min-width: 52px;
    overflow: hidden;
}

.tarot-pot-value {
    display: inline-block;
