    pointer-events: none;
}

.tarot-pot-chip.is-hot {
    border-color: rgba(251, 191, 36, 0.75);
    box-shadow: 0 0 0 1px rgba(251, 191, 36, 0.3), 0 0 20px rgba(251, 191, 36, 0.26), 0 8px 20px rgba(0, 0, 0, 0.45);
}

.tarot-pot-chip.is-rolling .tarot-pot-value {
    animation: tarotPotRoll 0.12s linear infinite;
}

.tarot-poker-controls {
    display: flex;
    align-items: stretch;
    flex-wrap: wrap;
    gap: 10px;
    margin-bottom: 10px;
}

.tarot-poker-controls button {
    flex: 1;
}

.tarot-poker-mode-toggle {
    flex: 0 0 auto;
    min-width: 240px;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
}

.tarot-poker-mode-btn {
    min-height: 44px;
    padding: 10px 12px;
    border-radius: 14px;
    border: 1px solid rgba(148, 163, 184, 0.22);
    background: linear-gradient(180deg, rgba(30, 41, 59, 0.94), rgba(15, 23, 42, 0.98));
    color: #cbd5e1;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.03em;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
    transition: transform 0.16s ease, border-color 0.16s ease, color 0.16s ease, box-shadow 0.16s ease;
}

.tarot-poker-mode-btn.is-active {
    color: #fff3c4;
    border-color: rgba(251, 191, 36, 0.52);
    background:
        radial-gradient(140% 120% at 50% 0%, rgba(245, 158, 11, 0.2), rgba(255, 255, 255, 0) 52%),
        linear-gradient(180deg, rgba(71, 85, 105, 0.94), rgba(17, 24, 39, 0.98));
    box-shadow:
        0 0 0 1px rgba(251, 191, 36, 0.18),
        0 10px 18px rgba(2, 6, 23, 0.22),
        inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.tarot-poker-mode-btn:disabled {
    opacity: 0.58;
}

.tarot-draw-guide {
    margin: 6px 0 10px;
    padding: 6px 10px;
    border-radius: 10px;
    border: 1px solid rgba(148, 163, 184, 0.45);
    background: rgba(15, 23, 42, 0.65);
    color: #e2e8f0;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.01em;
}

.tarot-betting-info {
    margin: 0 0 8px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 10px;
    background: rgba(15, 23, 42, 0.45);
    padding: 6px 8px;
}

.tarot-betting-points {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    font-size: 12px;
    color: #e8eef8;
    margin-bottom: 6px;
}

.tarot-betting-hint {
    font-size: 12px;
    color: #ffd98f;
    margin-bottom: 8px;
}

.tarot-betting-actions {
    display: flex;
    flex-wrap: nowrap;
    gap: 8px;
    justify-content: center;
    overflow-x: auto;
    padding-bottom: 2px;
}

.tarot-betting-actions button,
.tarot-kingdom-controls button:not(#tarotKingdomStartButton):not(#tarotKingdomStartOnlineButton):not(#tarotKingdomStartOfflineButton):not(#tarotKingdomRestartButton) {
    flex: 0 0 var(--tarot-card-w, 58px);
    width: var(--tarot-card-w, 58px);
    height: var(--tarot-card-h, 96px);
    min-height: var(--tarot-card-h, 96px);
    font-size: 12px;
    font-weight: 900;
    letter-spacing: 0.03em;
    padding: 5px 2px;
    border-radius: var(--tarot-card-radius, 10px);
    border: 1px solid rgba(255, 255, 255, 0.44);
    color: #f8fafc;
    text-shadow:
        0 1px 2px rgba(0, 0, 0, 0.78),
        0 0 10px rgba(255, 255, 255, 0.14);
    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.2),
        inset 0 -8px 14px rgba(0, 0, 0, 0.24),
        0 10px 18px rgba(0, 0, 0, 0.46),
        0 0 0 1px rgba(255, 255, 255, 0.1);
    transition: transform 0.14s ease, filter 0.2s ease, box-shadow 0.24s ease, opacity 0.2s ease;
    display: flex;
    align-items: center;
    justify-content: center;
    writing-mode: vertical-rl;
    text-orientation: upright;
    white-space: pre-line;
    overflow: hidden;
    text-overflow: ellipsis;
    line-height: 1.08;
    position: relative;
    isolation: isolate;
    background:
        radial-gradient(130% 90% at 50% -20%, rgba(255, 255, 255, 0.22), rgba(255, 255, 255, 0) 44%),
        linear-gradient(180deg, #475569, #1f2937);
}

.tarot-betting-actions button::before,
.tarot-kingdom-controls button:not(#tarotKingdomStartButton):not(#tarotKingdomStartOnlineButton):not(#tarotKingdomStartOfflineButton):not(#tarotKingdomRestartButton)::before {
    content: "";
    position: absolute;
    inset: -18% auto -18% -58%;
    width: 46%;
    background: linear-gradient(100deg, rgba(255, 255, 255, 0), rgba(255, 255, 255, 0.28), rgba(255, 255, 255, 0));
    transform: translateX(-130%) rotate(8deg);
    z-index: -1;
    pointer-events: none;
    animation: tarotActionSheen 3.2s linear infinite;
}

.tarot-betting-actions button::after,
.tarot-kingdom-controls button:not(#tarotKingdomStartButton):not(#tarotKingdomStartOnlineButton):not(#tarotKingdomStartOfflineButton):not(#tarotKingdomRestartButton)::after {
    content: "";
    position: absolute;
    inset: 1px;
    border-radius: inherit;
    border: 1px solid rgba(255, 255, 255, 0.12);
    pointer-events: none;
    z-index: -1;
}

.tarot-betting-actions button:not(:disabled):active,
.tarot-kingdom-controls button:not(#tarotKingdomStartButton):not(#tarotKingdomStartOnlineButton):not(#tarotKingdomStartOfflineButton):not(#tarotKingdomRestartButton):not(:disabled):active {
    transform: translateY(1px) scale(0.982);
}

.tarot-betting-actions button:not(:disabled):hover,
.tarot-kingdom-controls button:not(#tarotKingdomStartButton):not(#tarotKingdomStartOnlineButton):not(#tarotKingdomStartOfflineButton):not(#tarotKingdomRestartButton):not(:disabled):hover {
    filter: brightness(1.12) saturate(1.06);
    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.26),
        inset 0 -8px 14px rgba(0, 0, 0, 0.26),
        0 12px 22px rgba(0, 0, 0, 0.52),
        0 0 0 1px rgba(255, 255, 255, 0.16);
}

.tarot-betting-actions button.is-ready,
.tarot-kingdom-controls button:not(#tarotKingdomStartButton):not(#tarotKingdomStartOnlineButton):not(#tarotKingdomStartOfflineButton):not(#tarotKingdomRestartButton).is-ready {
    border-color: rgba(250, 204, 21, 0.86);
    box-shadow:
        0 0 0 1px rgba(250, 204, 21, 0.42),
        0 0 18px rgba(250, 204, 21, 0.35),
        0 10px 20px rgba(0, 0, 0, 0.5);
    animation: tarotKingdomReadyButtonPulse 0.92s ease-in-out infinite;
}

/* Tarot Kingdom: 自分ターン時のアクションボタン揺れを停止（強調は維持） */
#tarotKingdomActionPopup .tarot-betting-actions button.is-ready {
    animation: none;
    transform: none;
}

.tarot-betting-actions button:disabled,
.tarot-kingdom-controls button:not(#tarotKingdomStartButton):not(#tarotKingdomStartOnlineButton):not(#tarotKingdomStartOfflineButton):not(#tarotKingdomRestartButton):disabled {
    opacity: 0.42;
    filter: grayscale(0.34) brightness(0.82);
}

.tarot-betting-actions button:disabled::before,
.tarot-kingdom-controls button:not(#tarotKingdomStartButton):not(#tarotKingdomStartOnlineButton):not(#tarotKingdomStartOfflineButton):not(#tarotKingdomRestartButton):disabled::before {
    animation: none;
    opacity: 0;
}

#tarotBetCheck,
#tarotKingdomPassButton {
    background:
        radial-gradient(120% 90% at 50% -10%, rgba(226, 232, 240, 0.24), rgba(255, 255, 255, 0) 40%),
        linear-gradient(180deg, #475569, #111827);
}

#tarotKingdomFoldButton {
    background:
        radial-gradient(120% 90% at 50% -10%, rgba(253, 186, 116, 0.28), rgba(255, 255, 255, 0) 40%),
        linear-gradient(180deg, #c2410c, #7c2d12);
}

#tarotKingdomActionPopup .tarot-betting-actions > button {
    flex: 1 1 0;
    width: auto;
    min-width: 0;
}

#tarotKingdomFoldButton.is-active {
    border-color: rgba(251, 191, 36, 0.9);
    box-shadow:
        0 0 0 1px rgba(251, 191, 36, 0.52),
        0 0 20px rgba(249, 115, 22, 0.42),
        0 10px 20px rgba(0, 0, 0, 0.52);
    filter: none;
}

#tarotBetCall,
#tarotKingdomClearButton {
    background:
        radial-gradient(120% 90% at 50% -10%, rgba(186, 230, 253, 0.3), rgba(255, 255, 255, 0) 40%),
        linear-gradient(180deg, #0ea5b7, #155e75);
}

#tarotBetBet,
#tarotKingdomPlayButton {
    background:
        radial-gradient(120% 90% at 50% -10%, rgba(233, 213, 255, 0.3), rgba(255, 255, 255, 0) 40%),
        linear-gradient(180deg, #a855f7, #6d28d9);
}

#tarotBetRaise {
    background:
        radial-gradient(120% 90% at 50% -10%, rgba(254, 215, 170, 0.32), rgba(255, 255, 255, 0) 40%),
        linear-gradient(180deg, #d97706, #9a3412);
}

#tarotBetFold,
#tarotKingdomFoldButton.is-major-draw {
    background:
        radial-gradient(120% 90% at 50% -10%, rgba(254, 202, 202, 0.28), rgba(255, 255, 255, 0) 40%),
        linear-gradient(180deg, #ef4444, #991b1b);
}

#tarotKingdomPassButton.is-minor-draw {
    background:
        radial-gradient(120% 90% at 50% -10%, rgba(187, 247, 208, 0.28), rgba(255, 255, 255, 0) 40%),
        linear-gradient(180deg, #16a34a, #14532d);
}

#tarotKingdomGraveToggleButton {
    background:
        radial-gradient(120% 90% at 50% -10%, rgba(199, 210, 254, 0.3), rgba(255, 255, 255, 0) 40%),
        linear-gradient(180deg, #4f46e5, #312e81);
}

.tarot-bet-popup {
    position: fixed;
    left: 50%;
    bottom: calc(env(safe-area-inset-bottom, 0px) + 10px);
    transform: translateX(-50%);
    width: fit-content;
    max-width: calc(100% - 12px);
    z-index: 3400;
    border: 1px solid var(--action-panel-border);
    border-radius: 12px;
    background: var(--action-panel-bg);
    backdrop-filter: blur(4px);
    box-shadow: var(--action-panel-shadow);
    padding: 24px 10px 10px;
    pointer-events: auto;
    touch-action: manipulation;
}

.tarot-bet-popup::before {
    content: "ベッティングタイム";
    position: absolute;
    top: 5px;
    left: 50%;
    transform: translateX(-50%);
    font-size: 11px;
    font-weight: 900;
    letter-spacing: 0.14em;
    color: #fde68a;
    text-shadow: 0 0 10px rgba(251, 191, 36, 0.55);
    pointer-events: none;
    animation: tarotBettingTextPulse 0.9s ease-in-out infinite;
}

.tarot-bet-popup.tarot-kingdom-action-popup::before {
    content: "プレイヤーアクション";
}

@keyframes tarotBettingTextPulse {
    0%,
    100% {
        opacity: 0.78;
    }
    50% {
        opacity: 1;
    }
}

@keyframes tarotActionSheen {
    0% {
        transform: translateX(-130%) rotate(8deg);
        opacity: 0;
    }
    12% {
        opacity: 0.24;
    }
    36% {
        transform: translateX(320%) rotate(8deg);
        opacity: 0.12;
    }
    100% {
        transform: translateX(320%) rotate(8deg);
        opacity: 0;
    }
}

@keyframes tarotKingdomHumanTurnPulse {
    0%,
    100% {
        transform: translateY(0);
        box-shadow:
            0 0 0 1px rgba(250, 204, 21, 0.5),
            0 0 20px rgba(250, 204, 21, 0.36),
            0 0 34px rgba(59, 130, 246, 0.26);
    }
    50% {
        transform: translateY(-1px);
        box-shadow:
            0 0 0 1px rgba(250, 204, 21, 0.7),
            0 0 24px rgba(250, 204, 21, 0.46),
            0 0 40px rgba(59, 130, 246, 0.34);
    }
}

@keyframes tarotKingdomReadyButtonPulse {
    0%,
    100% {
        transform: translateY(0);
        filter: brightness(1);
    }
    50% {
        transform: translateY(-1px);
        filter: brightness(1.1);
    }
}

@keyframes tarotKingdomLastOnePulse {
    0%,
    100% {
        box-shadow:
            0 0 0 1px rgba(248, 113, 113, 0.34),
            0 0 14px rgba(248, 113, 113, 0.22);
    }
    50% {
        box-shadow:
            0 0 0 1px rgba(248, 113, 113, 0.56),
            0 0 26px rgba(248, 113, 113, 0.4);
    }
}

@keyframes tarotKingdomHandCriticalPulse {
    0%,
    100% {
        transform: scale(1);
        filter: brightness(1);
    }
    50% {
        transform: scale(1.06);
        filter: brightness(1.12);
    }
}

@keyframes tarotKingdomYourTurnBadgePulse {
    0% {
        transform: translateY(4px) scale(0.92);
        opacity: 0;
    }
    55% {
        transform: translateY(0) scale(1.03);
        opacity: 1;
    }
    100% {
        transform: translateY(0) scale(1);
        opacity: 1;
    }
}

@keyframes tarotKingdomYourTurnCutinPulse {
    0% {
        transform: translate(-50%, -12px) skewX(-12deg) scale(0.98);
        filter: brightness(0.92);
    }
    50% {
        transform: translate(-50%, 0) skewX(-12deg) scale(1.02);
        filter: brightness(1.08);
    }
    100% {
        transform: translate(-50%, 0) skewX(-12deg) scale(1);
        filter: brightness(1);
    }
}

@media (max-width: 560px) {
    .tarot-bet-popup {
        width: calc(100% - 10px);
        padding: 22px 8px 8px;
    }

    .tarot-betting-actions button,
    .tarot-kingdom-controls button:not(#tarotKingdomStartButton):not(#tarotKingdomStartOnlineButton):not(#tarotKingdomStartOfflineButton):not(#tarotKingdomRestartButton) {
        width: var(--tarot-card-w, 58px);
        min-width: var(--tarot-card-w, 58px);
        height: var(--tarot-card-h, 96px);
        min-height: var(--tarot-card-h, 96px);
        font-size: 12px;
        padding: 4px 2px;
