}

.tarot-card-row.is-draw-phase .tarot-card.is-clickable:not(.is-leaving) {
    animation: tarotDrawCardWiggle 2.6s ease-in-out infinite;
    will-change: transform;
}

.tarot-card-row.is-draw-phase .tarot-card.is-clickable:nth-child(2n):not(.is-leaving) {
    animation-delay: 0.14s;
}

.tarot-card-row.is-draw-phase .tarot-card.is-clickable:nth-child(3n):not(.is-leaving) {
    animation-delay: 0.28s;
}

.tarot-card-row.is-draw-phase .tarot-card.is-clickable:nth-child(4n):not(.is-leaving) {
    animation-delay: 0.42s;
}

.tarot-card-row.is-draw-phase .tarot-card.is-clickable:hover,
.tarot-card-row.is-draw-phase .tarot-card.is-clickable:active {
    animation-play-state: paused;
}

.tarot-card-row .tarot-card.is-selected {
    border-color: var(--tarot-interact-border);
    box-shadow:
        0 0 0 1px var(--tarot-interact-border-soft),
        0 0 16px var(--tarot-interact-glow),
        inset 0 0 0 1px rgba(255, 255, 255, 0.28);
    transform: translateY(-6px);
    animation: none !important;
}

.tarot-grave-row .tarot-card.is-selected {
    border-color: var(--tarot-interact-border);
    box-shadow:
        0 0 0 1px var(--tarot-interact-border-soft),
        0 0 14px var(--tarot-interact-glow),
        inset 0 0 0 1px rgba(255, 255, 255, 0.25);
    transform: translateY(-4px) scale(0.92);
    animation: none !important;
}

@keyframes tarotDrawCardWiggle {
    0%,
    78%,
    100% {
        transform: translate3d(0, 0, 0) rotate(0deg);
    }
    81% {
        transform: translate3d(-0.8px, 0, 0) rotate(-0.7deg);
    }
    84% {
        transform: translate3d(0.9px, -0.2px, 0) rotate(0.8deg);
    }
    87% {
        transform: translate3d(-0.6px, 0.1px, 0) rotate(-0.45deg);
    }
    90% {
        transform: translate3d(0.45px, 0, 0) rotate(0.35deg);
    }
}

@keyframes tarotCardEnterFromBottom {
    0% {
        opacity: 0;
        transform: translateY(10px) scale(0.97);
        filter: saturate(0.9);
    }
    100% {
        opacity: 1;
        transform: translateY(0) scale(1);
        filter: saturate(1);
    }
}

@keyframes tarotKingdomCallCardFromRight {
    0% {
        opacity: 0;
        transform: translateX(54px) translateY(2px) scale(0.94);
        filter: saturate(0.9);
    }
    70% {
        opacity: 1;
        transform: translateX(-3px) translateY(0) scale(1.01);
        filter: saturate(1.05);
    }
    100% {
        opacity: 1;
        transform: translateX(0) translateY(0) scale(1);
        filter: saturate(1);
    }
}

@keyframes tarotKingdomChariotSplitLeft {
    0% {
        opacity: 0;
        transform: translate(-50%, -50%) scale(0.96) rotate(0deg);
        filter: brightness(1.15) saturate(1.06);
    }
    22% {
        opacity: 1;
        transform: translate(calc(-50% - 8px), calc(-50% - 1px)) scale(1.02) rotate(-4deg);
        filter: brightness(1.26) saturate(1.16);
    }
    100% {
        opacity: 0;
        transform: translate(calc(-50% - 46px), calc(-50% - 7px)) scale(0.86) rotate(-16deg);
        filter: brightness(1.03) saturate(1.02);
    }
}

@keyframes tarotKingdomChariotSplitRight {
    0% {
        opacity: 0;
        transform: translate(-50%, -50%) scale(0.96) rotate(0deg);
        filter: brightness(1.15) saturate(1.06);
    }
    22% {
        opacity: 1;
        transform: translate(calc(-50% + 8px), calc(-50% - 1px)) scale(1.02) rotate(4deg);
        filter: brightness(1.26) saturate(1.16);
    }
    100% {
        opacity: 0;
        transform: translate(calc(-50% + 46px), calc(-50% - 7px)) scale(0.86) rotate(16deg);
        filter: brightness(1.03) saturate(1.02);
    }
}

.tarot-card-row .tarot-card,
.tarot-poker-board .tarot-card {
    flex: 0 0 var(--tarot-card-w, 64px);
}

.tarot-card {
    width: var(--tarot-card-w, 64px);
    min-width: var(--tarot-card-w, 64px);
    height: var(--tarot-card-h, 100px);
    border-radius: var(--tarot-card-radius, 10px);
    border: 1px solid rgba(255, 255, 255, 0.22);
    padding: var(--tarot-card-padding, 6px);
    position: relative;
    text-align: left;
    color: #fff;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.15);
    transition: transform 160ms ease, box-shadow 180ms ease, opacity 140ms ease, filter 180ms ease;
}

.tarot-card.wand {
    background: linear-gradient(180deg, #b11818, #7a0e0e);
}

.tarot-card.sword {
    background: linear-gradient(180deg, #c29b14, #856a06);
}

.tarot-card.cup {
    background: linear-gradient(180deg, #1e63c6, #123d7b);
}

.tarot-card.pentacle {
    background: linear-gradient(180deg, #1e8f3c, #15632b);
}

.tarot-card.none {
    background: linear-gradient(180deg, #5b6472, #343b45);
}

.tarot-card.all-suit {
    background:
        radial-gradient(circle at 10% 10%, rgba(220, 38, 38, 0.95) 0 7px, transparent 8px),
        radial-gradient(circle at 90% 10%, rgba(250, 204, 21, 0.95) 0 7px, transparent 8px),
        radial-gradient(circle at 10% 90%, rgba(59, 130, 246, 0.95) 0 7px, transparent 8px),
        radial-gradient(circle at 90% 90%, rgba(34, 197, 94, 0.95) 0 7px, transparent 8px),
        linear-gradient(180deg, #4b5563, #1f2937);
    border-color: rgba(255, 255, 255, 0.34);
}

.tarot-card.is-hidden {
    background: linear-gradient(180deg, #374151, #1f2937);
    border-color: rgba(255, 255, 255, 0.14);
}

.tarot-card.is-clickable {
    cursor: pointer;
    transition: transform 120ms ease, box-shadow 200ms ease, opacity 120ms ease, filter 180ms ease;
    animation: none;
    border-color: rgba(255, 255, 255, 0.22);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.15);
}

.tarot-card.is-clickable:active {
    transform: translateY(1px) scale(0.97);
}

.tarot-card.is-static {
    cursor: default;
}

.tarot-card.is-arcana-match {
    box-shadow:
        0 0 0 1px rgba(239, 246, 255, 0.7),
        0 0 18px rgba(125, 211, 252, 0.32),
        0 0 26px rgba(250, 204, 21, 0.24),
        inset 0 1px 0 rgba(255, 255, 255, 0.34);
    animation: tarotArcanaAura 2.9s ease-in-out infinite;
}

.tarot-card.is-arcana-match::before {
    content: "";
    position: absolute;
    inset: -2px;
    border-radius: inherit;
    z-index: 1;
    pointer-events: none;
    background:
        conic-gradient(
            from 0deg,
            rgba(56, 189, 248, 0.24),
            rgba(250, 204, 21, 0.2),
            rgba(167, 139, 250, 0.2),
            rgba(56, 189, 248, 0.24)
        );
    mix-blend-mode: screen;
    filter: blur(2px) saturate(1.1);
    opacity: 0.34;
    animation: tarotArcanaHaloSpin 7.8s linear infinite, tarotArcanaHaloBreath 2.6s ease-in-out infinite;
}

.tarot-card.is-arcana-match.is-selected::before {
    filter: saturate(1.1);
}

.tarot-card.is-arcana-match .tarot-card-number {
    will-change: filter;
    animation: tarotArcanaSparkle 2.4s ease-in-out infinite;
}

.tarot-card.is-leaving {
    transition: opacity 130ms ease, transform 130ms ease, filter 130ms ease;
    opacity: 0.58 !important;
    transform: translateY(-8px) scale(0.97) rotate(-2deg);
    filter: saturate(1.1);
}

.tarot-card.is-clear-sweep-leaving {
    pointer-events: none !important;
    will-change: transform, opacity, filter;
    animation: tarotKingdomClearSweepCard var(--clear-card-ms, 260ms) cubic-bezier(0.16, 0.84, 0.24, 1) forwards;
}

.tarot-card.is-defeat-transition {
    pointer-events: none !important;
    will-change: transform, opacity, filter;
    z-index: 4;
}

.tarot-card.is-defeat-transition::after {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    font-size: 32px;
    line-height: 1;
    pointer-events: none;
    text-shadow: 0 0 12px rgba(0, 0, 0, 0.52), 0 0 18px rgba(255, 255, 255, 0.24);
    opacity: 0;
}

.tarot-card.is-defeat-normal {
    animation: tarotKingdomDefeatNormal var(--defeat-card-ms, 420ms) cubic-bezier(0.22, 0.82, 0.24, 1) forwards;
}

.tarot-card.is-defeat-primary.is-defeat-normal::after {
    content: var(--defeat-marker-content, "💥");
    animation: tarotKingdomDefeatMarker var(--defeat-marker-ms, 820ms) ease-out forwards;
}

.tarot-card.is-defeat-slash {
    animation: tarotKingdomDefeatSlash var(--defeat-card-ms, 620ms) cubic-bezier(0.2, 0.84, 0.24, 1) forwards;
}

.tarot-card.is-defeat-primary.is-defeat-slash::after {
    content: var(--defeat-marker-content, "\1F5E1");
    left: 50%;
    top: 12%;
    font-size: 40px;
    transform-origin: 84% 14%;
    filter: drop-shadow(0 0 4px rgba(255, 255, 255, 0.44)) drop-shadow(0 0 8px rgba(250, 204, 21, 0.28));
    animation: tarotKingdomDefeatSlashMarker var(--defeat-marker-ms, 920ms) cubic-bezier(0.16, 0.82, 0.24, 1) forwards;
}

.tarot-card.is-defeat-rock {
    animation: tarotKingdomDefeatRock var(--defeat-card-ms, 620ms) cubic-bezier(0.22, 0.82, 0.24, 1) forwards;
}

.tarot-card.is-defeat-primary.is-defeat-rock::after {
    content: var(--defeat-marker-content, "🪦");
    top: 44%;
    font-size: 30px;
    animation: tarotKingdomDefeatRockMarker var(--defeat-marker-ms, 900ms) ease-out forwards;
}

.tarot-card.is-defeat-water {
    animation: tarotKingdomDefeatWater var(--defeat-card-ms, 620ms) cubic-bezier(0.22, 0.82, 0.24, 1) forwards;
}

.tarot-card.is-defeat-primary.is-defeat-water::after {
    content: var(--defeat-marker-content, "💦");
    top: 36%;
    font-size: 30px;
    animation: tarotKingdomDefeatWaterMarker var(--defeat-marker-ms, 900ms) ease-out forwards;
}

.tarot-card.is-defeat-fire {
    animation: tarotKingdomDefeatFire var(--defeat-card-ms, 620ms) cubic-bezier(0.2, 0.84, 0.24, 1) forwards;
}

.tarot-card.is-defeat-primary.is-defeat-fire::after {
    content: var(--defeat-marker-content, "🔥");
    top: 48%;
    font-size: 30px;
    animation: tarotKingdomDefeatFireMarker var(--defeat-marker-ms, 900ms) ease-out forwards;
}

.tarot-card.is-defeat-arcana {
    animation: tarotKingdomDefeatArcana var(--defeat-card-ms, 760ms) cubic-bezier(0.18, 0.82, 0.24, 1) forwards;
}

.tarot-card.is-defeat-arcana.is-defeat-arcana-orbit { animation-name: tarotKingdomDefeatArcanaOrbit; }
.tarot-card.is-defeat-arcana.is-defeat-arcana-float { animation-name: tarotKingdomDefeatArcanaFloat; }
.tarot-card.is-defeat-arcana.is-defeat-arcana-slam { animation-name: tarotKingdomDefeatArcanaSlam; }
.tarot-card.is-defeat-arcana.is-defeat-arcana-burst { animation-name: tarotKingdomDefeatArcanaBurst; }
.tarot-card.is-defeat-arcana.is-defeat-arcana-rush { animation-name: tarotKingdomDefeatArcanaRush; }
.tarot-card.is-defeat-arcana.is-defeat-arcana-trickster { animation-name: tarotKingdomDefeatArcanaTrickster; }
.tarot-card.is-defeat-arcana.is-defeat-arcana-throne { animation-name: tarotKingdomDefeatArcanaThrone; }
.tarot-card.is-defeat-arcana.is-defeat-arcana-edict { animation-name: tarotKingdomDefeatArcanaEdict; }
.tarot-card.is-defeat-arcana.is-defeat-arcana-sanctum { animation-name: tarotKingdomDefeatArcanaSanctum; }
.tarot-card.is-defeat-arcana.is-defeat-arcana-halo { animation-name: tarotKingdomDefeatArcanaHalo; }
.tarot-card.is-defeat-arcana.is-defeat-arcana-verdict { animation-name: tarotKingdomDefeatArcanaVerdict; }
.tarot-card.is-defeat-arcana.is-defeat-arcana-rift { animation-name: tarotKingdomDefeatArcanaRift; }
.tarot-card.is-defeat-arcana.is-defeat-arcana-world { animation-name: tarotKingdomDefeatArcanaWorld; }

.tarot-card.is-defeat-primary.is-defeat-arcana::after {
    content: var(--defeat-marker-content, "✦");
    left: 50%;
    top: 46%;
    font-size: 30px;
    transform: translate(-50%, -50%);
    text-shadow:
        0 0 10px rgba(0, 0, 0, 0.56),
        0 0 18px rgba(255, 255, 255, 0.24),
        0 0 28px rgba(148, 163, 184, 0.18);
    animation: tarotKingdomDefeatArcanaMarker var(--defeat-marker-ms, 980ms) cubic-bezier(0.16, 0.82, 0.24, 1) forwards;
}

.tarot-card.is-entering {
    opacity: 0 !important;
    transform: translateY(10px) scale(0.97);
    animation: tarotCardEnterFromBottom 190ms cubic-bezier(0.2, 0.75, 0.25, 1) forwards;
}

.tarot-card.is-call-arriving {
    opacity: 0;
    transform: translateX(58px) translateY(2px) scale(0.92);
    animation: tarotKingdomCallCardFromRight 360ms cubic-bezier(0.2, 0.82, 0.24, 1) forwards;
    filter: saturate(1.18) brightness(1.08);
}

.tarot-card.is-call-arriving::after {
    content: "";
    position: absolute;
    inset: 14% 74% 14% -26%;
