/* Tarot Kingdom v14: battlefield-integrated summon and action cut-ins. */
:is(body, #tabContentTarot) #tarotKingdomRoot #tarotKingdomBattleStage > #tarotKingdomCutin.tarot-cutin {
    --tk-action-accent: #9ab6ce;
    --tk-action-surface: rgba(9, 17, 28, 0.92);
    position: absolute;
    z-index: 64;
    top: var(--tk-action-cutin-y, 42%);
    right: 6px;
    left: auto;
    display: grid;
    grid-template-columns: auto 1fr;
    align-items: center;
    width: min(68%, 310px);
    min-width: 0;
    max-width: calc(100% - 12px);
    min-height: 38px;
    padding: 4px 13px 5px 16px;
    overflow: hidden;
    border: 0;
    border-left: 3px solid var(--tk-action-accent);
    border-radius: 2px 0 0 2px;
    color: #f8fbff;
    background:
        linear-gradient(90deg, color-mix(in srgb, var(--tk-action-accent) 20%, transparent), transparent 42%),
        linear-gradient(90deg, var(--tk-action-surface), rgba(3, 7, 13, 0.74));
    box-shadow:
        -8px 0 18px color-mix(in srgb, var(--tk-action-accent) 24%, transparent),
        0 5px 12px rgba(0, 0, 0, 0.56);
    opacity: 0;
    transform: translate(0, -50%) scaleX(0.14);
    transform-origin: 100% 50%;
    clip-path: inset(0 0 0 86%);
    transition: none;
    animation: none !important;
    pointer-events: none;
    isolation: isolate;
}

:is(body, #tabContentTarot) #tarotKingdomRoot #tarotKingdomBattleStage > #tarotKingdomCutin.tarot-cutin::before {
    content: "";
    position: absolute;
    z-index: -1;
    inset: 0;
    background: linear-gradient(112deg, transparent 0 54%, color-mix(in srgb, var(--tk-action-accent) 38%, transparent) 55% 57%, transparent 58%);
    transform: translateX(-45%);
}

:is(body, #tabContentTarot) #tarotKingdomRoot #tarotKingdomBattleStage > #tarotKingdomCutin.tarot-cutin.show {
    animation: tarotKingdomActionCutinSweep var(--tk-action-cutin-duration, 680ms) cubic-bezier(0.2, 0.78, 0.18, 1) both !important;
}

#tarotKingdomCutin .tarot-action-cutin-actor {
    min-width: 58px;
    max-width: 98px;
    overflow: hidden;
    color: color-mix(in srgb, var(--tk-action-accent) 72%, white);
    font: 800 9px/1.05 Arial, sans-serif;
    letter-spacing: 0.04em;
    text-align: left;
    text-overflow: ellipsis;
    white-space: nowrap;
}

#tarotKingdomCutin .tarot-action-cutin-keyword {
    min-width: 0;
