.tarot-kingdom-skill-cutin {
    --skill-accent: #6fb7ff;
    position: absolute;
    z-index: 52;
    inset: 0;
    display: grid;
    align-content: center;
    justify-items: center;
    gap: 12px;
    overflow: hidden;
    color: #fff;
    background: radial-gradient(circle at 50% 53%, color-mix(in srgb, var(--skill-accent) 28%, transparent), rgba(0, 0, 0, 0.84) 62%);
    pointer-events: none;
    isolation: isolate;
}

.tarot-kingdom-skill-cutin::before,
.tarot-kingdom-skill-cutin::after {
    content: "";
    position: absolute;
    z-index: -1;
    inset: 42% -20%;
    border-top: 1px solid var(--skill-accent);
    border-bottom: 1px solid var(--skill-accent);
    background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--skill-accent) 36%, transparent), transparent);
    transform: skewY(-5deg);
    filter: drop-shadow(0 0 12px var(--skill-accent));
}

.tarot-kingdom-skill-cutin::after {
    inset: 0;
    border: 0;
    background: radial-gradient(circle, transparent 42%, rgba(0, 0, 0, 0.78) 82%);
    transform: none;
    filter: none;
}

.tarot-kingdom-skill-cutin-title {
    font-family: Georgia, "Yu Mincho", serif;
    font-size: clamp(25px, 8vw, 48px);
    letter-spacing: 0.12em;
    text-shadow: 0 2px 1px #000, 0 0 8px var(--skill-accent), 0 0 18px var(--skill-accent);
}

