    color: #baffbb;
    text-shadow: 0 2px 1px #12371a, 0 0 8px #67e879, 0 0 16px rgba(75, 216, 111, 0.72);
}

.tarot-kingdom-damage-number.is-status {
    font-size: clamp(17px, 5.5vw, 30px);
}

.tarot-kingdom-damage-number.is-status-poison {
    color: #baff87;
    text-shadow: 0 2px 1px #0b2405, 0 0 8px #65d638, 0 0 16px rgba(84, 206, 46, 0.72);
}

.tarot-kingdom-damage-number.is-status-burn {
    color: #ffc27d;
    text-shadow: 0 2px 1px #341000, 0 0 8px #ff7a2f, 0 0 16px rgba(255, 75, 29, 0.74);
}

.tarot-kingdom-damage-number:is(.is-status-confusion, .is-status-mixed) {
    color: #dfb8ff;
    text-shadow: 0 2px 1px #20062f, 0 0 8px #ad64ec, 0 0 16px rgba(153, 73, 226, 0.72);
}

.tarot-kingdom-damage-number.is-status-effect {
