}

.tarot-kingdom-damage-number.is-show {
    animation: tarotKingdomDamagePop 420ms cubic-bezier(0.15, 0.8, 0.25, 1) both;
}

#tarotKingdomBattleStage.is-battle-charging .tarot-kingdom-battle-player.is-battle-charging .tarot-kingdom-battle-player-avatar {
    filter: brightness(1.24) drop-shadow(0 0 8px #ffd66a) drop-shadow(0 0 16px rgba(255, 123, 45, 0.7));
}

