    animation-play-state: paused !important;
    filter: brightness(2.1) contrast(1.25) drop-shadow(0 0 10px #fff3bb);
}

#tarotKingdomBattleStage.is-battle-skill.is-battle-damage .tarot-kingdom-battle-arena {
    animation: tarotKingdomSkillImpact 260ms steps(2, end) both;
}

#tarotKingdomBattleStage.is-weapon-impact-shake:not(.is-battle-skill) .tarot-kingdom-battle-arena {
    animation: tarotKingdomWeaponImpactShake var(--tk-weapon-impact-duration, 180ms) steps(4, end) both;
}

@keyframes tarotKingdomDamagePop {
    0% { opacity: 0; transform: translate(-50%, 12px) scale(0.72); }
    24% { opacity: 1; transform: translate(-50%, -8px) scale(1.18); }
    68% { opacity: 1; transform: translate(-50%, -16px) scale(1); }
    100% { opacity: 0; transform: translate(-50%, -28px) scale(0.94); }
}

@keyframes tarotKingdomSkillImpact {
    0% { transform: translate(0, 0); filter: brightness(1); }
    25% { transform: translate(-5px, 2px); filter: brightness(1.9); }
    50% { transform: translate(5px, -2px); }
    75% { transform: translate(-3px, 1px); }
    100% { transform: translate(0, 0); filter: brightness(1); }
}

@keyframes tarotKingdomWeaponImpactShake {
    0%, 100% { transform: translate3d(0, 0, 0); filter: brightness(1); }
    18% { transform: translate3d(calc(var(--tk-weapon-impact-x, 3px) * -1), var(--tk-weapon-impact-y, 1px), 0); filter: brightness(1.28); }
    38% { transform: translate3d(var(--tk-weapon-impact-x, 3px), calc(var(--tk-weapon-impact-y, 1px) * -1), 0); }
    58% { transform: translate3d(calc(var(--tk-weapon-impact-x, 3px) * -0.55), 0, 0); }
    78% { transform: translate3d(calc(var(--tk-weapon-impact-x, 3px) * 0.3), var(--tk-weapon-impact-y, 1px), 0); filter: brightness(1.08); }
}

