.tarot-card.is-chariot-splitting {
    opacity: 0.34 !important;
    filter: brightness(1.2) saturate(1.15);
}

.tarot-kingdom-split-card {
    position: fixed;
    z-index: 3950;
    pointer-events: none;
    margin: 0;
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.96);
    box-shadow:
        0 0 0 1px rgba(255, 255, 255, 0.48),
        0 0 18px rgba(148, 163, 184, 0.34),
        0 0 24px rgba(56, 189, 248, 0.24);
    will-change: transform, opacity, filter;
}

.tarot-kingdom-split-card.run.is-left {
    animation: tarotKingdomChariotSplitLeft 620ms cubic-bezier(0.22, 0.82, 0.24, 1) forwards;
}

.tarot-kingdom-split-card.run.is-right {
    animation: tarotKingdomChariotSplitRight 620ms cubic-bezier(0.22, 0.82, 0.24, 1) forwards;
}

.tarot-card.is-undealt {
    opacity: 0 !important;
    transform: scale(0.96);
    pointer-events: none;
}

.tarot-card-title {
    position: absolute;
    left: 4px;
    right: 4px;
    top: 3px;
    z-index: 2;
    font-size: var(--tarot-card-title-size, 11px);
    font-weight: 700;
    opacity: 0.94;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.6);
    -webkit-text-stroke: 1px #000;
    paint-order: stroke fill;
    text-align: center;
}

.tarot-card-number {
    position: absolute;
    left: 5px;
    bottom: 3px;
    z-index: 2;
    font-size: var(--tarot-card-number-size, 24px);
    line-height: 1;
    font-weight: 900;
    text-shadow:
        -1px -1px 0 #000,
        -1px 1px 0 #000,
        1px -1px 0 #000,
        1px 1px 0 #000,
        0 1px 0 rgba(0, 0, 0, 0.45);
    -webkit-text-stroke: 1.6px #000;
    paint-order: stroke fill;
}

.tarot-card-number.is-center-range {
    left: 50%;
    right: auto;
    bottom: 4px;
    width: max-content;
    max-width: calc(100% - 8px);
    text-align: center;
    transform: translateX(-50%);
    font-size: calc(var(--tarot-card-number-size, 24px) - 2px);
    letter-spacing: -0.04em;
}

/* Reuse the existing pot-roll motion for card number value shifts. */
.tarot-card-number.is-rolling {
    animation: tarotPotRoll 0.11s linear 4;
    transform-origin: 50% 58%;
}

.tarot-card:not(.is-arcana).wand .tarot-card-number {
    color: #fecaca;
}

.tarot-card:not(.is-arcana).sword .tarot-card-number {
    color: #fde047;
}

.tarot-card:not(.is-arcana).cup .tarot-card-number {
    color: #bfdbfe;
}

.tarot-card:not(.is-arcana).pentacle .tarot-card-number {
    color: #bbf7d0;
}

.tarot-card:not(.is-arcana).all-suit .tarot-card-number {
    color: #f8fafc;
}

.tarot-card:not(.is-arcana).none .tarot-card-number {
    color: #e5e7eb;
}

.tarot-card-art {
    position: absolute;
    left: 50%;
    right: auto;
    top: 50%;
    width: var(--tarot-art-w, 48px);
    height: var(--tarot-art-h, 80px);
    margin-left: 0;
    margin-right: 0;
    transform: translate(-50%, -50%);
    transform-origin: top center;
    border-radius: 4px;
    border: 1px solid rgba(255, 255, 255, 0.25);
    image-rendering: pixelated;
    background-image: var(--tarot-sprite-src);
    background-repeat: no-repeat;
    background-size: var(--tarot-sheet-w, 512px) var(--tarot-sheet-h, 1024px);
    background-position: calc(var(--tarot-x, 0px) * -1) calc(var(--tarot-y, 0px) * -1);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.18);
}

.tarot-card.is-arcana {
    background:
        radial-gradient(circle at 16% 14%, rgba(255, 255, 255, 0.82) 0 16%, rgba(255, 255, 255, 0) 42%),
        linear-gradient(165deg, #f8fafc 0%, #eef2ff 48%, #e2e8f0 100%);
    color: #ffffff;
    border-color: rgba(255, 255, 255, 0.94);
    box-shadow:
        0 0 0 1px rgba(239, 246, 255, 0.7),
        0 0 18px rgba(125, 211, 252, 0.32),
        0 0 26px rgba(250, 204, 21, 0.24),
        inset 0 1px 0 rgba(255, 255, 255, 0.34);
    animation: tarotArcanaAura 2.9s ease-in-out infinite;
}

.tarot-card.is-arcana::before {
    content: "";
    position: absolute;
    inset: -2px;
    border-radius: inherit;
    z-index: 1;
    pointer-events: none;
    background:
        conic-gradient(
            from 0deg,
            rgba(56, 189, 248, 0.24),
            rgba(250, 204, 21, 0.2),
            rgba(167, 139, 250, 0.2),
            rgba(56, 189, 248, 0.24)
        );
    mix-blend-mode: screen;
    filter: saturate(1.1);
    opacity: 0.34;
    animation: tarotArcanaHaloSpin 7.8s linear infinite, tarotArcanaHaloBreath 2.6s ease-in-out infinite;
}

.tarot-card.is-arcana .tarot-card-title,
.tarot-card.is-arcana .tarot-card-number {
    color: #ffffff;
}

.tarot-card.is-arcana .tarot-card-number {
    will-change: filter;
    animation: tarotArcanaSparkle 2.4s ease-in-out infinite;
}

.tarot-card.is-arcana.arcana-all-corners {
    background:
        radial-gradient(circle at 10% 10%, rgba(220, 38, 38, 0.95) 0 7px, transparent 8px),
        radial-gradient(circle at 90% 10%, rgba(250, 204, 21, 0.95) 0 7px, transparent 8px),
        radial-gradient(circle at 10% 90%, rgba(59, 130, 246, 0.95) 0 7px, transparent 8px),
        radial-gradient(circle at 90% 90%, rgba(34, 197, 94, 0.95) 0 7px, transparent 8px),
        linear-gradient(180deg, #f8fafc, #e5e7eb);
}

.tarot-card.is-arcana.arcana-suit-hybrid {
    background:
        linear-gradient(
            135deg,
            rgba(248, 250, 252, 0.98) 0 52%,
            var(--arcana-color, #b11818) 52% 100%
        ),
        linear-gradient(180deg, #f8fafc, #e5e7eb);
}

.tarot-card.is-arcana.arcana-suit-hybrid .tarot-card-title {
    color: #f8fafc;
}

.tarot-card.is-arcana.arcana-suit-hybrid .tarot-card-number {
    color: var(--arcana-number-color, #f8fafc);
    text-shadow: 0 0 8px rgba(2, 6, 23, 0.36);
}

.tarot-card.is-arcana.arcana-suit-hybrid.arcana-suit-wand {
    --arcana-number-color: #fecaca;
}

.tarot-card.is-arcana.arcana-suit-hybrid.arcana-suit-sword {
    --arcana-number-color: #fde047;
}

.tarot-card.is-arcana.arcana-suit-hybrid.arcana-suit-cup {
    --arcana-number-color: #bfdbfe;
}

.tarot-card.is-arcana.arcana-suit-hybrid.arcana-suit-pentacle {
    --arcana-number-color: #bbf7d0;
}

/* Mini tarot cards: reduce white arcana outline so suit color stays visible. */
.tarot-kingdom-hand .tarot-card.is-arcana,
.tarot-kingdom-grave-slot .tarot-card.is-arcana,
.tarot-poker-column--npc-mini .tarot-card.is-arcana {
    border-color: rgba(15, 23, 42, 0.82);
    box-shadow:
        0 0 0 1px rgba(15, 23, 42, 0.5),
        0 0 8px rgba(56, 189, 248, 0.18),
        inset 0 1px 0 rgba(255, 255, 255, 0.12);
}

.tarot-kingdom-hand .tarot-card.is-arcana::before,
.tarot-kingdom-grave-slot .tarot-card.is-arcana::before,
.tarot-poker-column--npc-mini .tarot-card.is-arcana::before {
    opacity: 0.14;
    filter: saturate(1.02);
}

.tarot-kingdom-hand .tarot-card.is-arcana.arcana-suit-hybrid,
.tarot-kingdom-grave-slot .tarot-card.is-arcana.arcana-suit-hybrid,
.tarot-poker-column--npc-mini .tarot-card.is-arcana.arcana-suit-hybrid {
    background:
        linear-gradient(
            135deg,
            rgba(248, 250, 252, 0.96) 0 40%,
            var(--arcana-color, #b11818) 40% 100%
        ),
        linear-gradient(180deg, #f8fafc, #e5e7eb);
}

@keyframes tarotArcanaSparkle {
    0%,
    100% {
        filter:
            drop-shadow(0 0 0 rgba(255, 255, 255, 0))
            drop-shadow(0 0 0 rgba(56, 189, 248, 0));
    }
    32% {
        filter:
            drop-shadow(0 0 3px rgba(255, 255, 255, 0.9))
            drop-shadow(0 0 6px rgba(253, 224, 71, 0.75))
            drop-shadow(0 0 9px rgba(56, 189, 248, 0.52));
    }
    58% {
        filter:
            drop-shadow(0 0 1px rgba(255, 255, 255, 0.7))
            drop-shadow(0 0 4px rgba(253, 224, 71, 0.6))
            drop-shadow(0 0 6px rgba(167, 139, 250, 0.4));
    }
}

@keyframes tarotArcanaAura {
    0%,
    100% {
        box-shadow:
            0 0 0 1px rgba(239, 246, 255, 0.7),
            0 0 16px rgba(125, 211, 252, 0.28),
            0 0 24px rgba(250, 204, 21, 0.22),
            inset 0 1px 0 rgba(255, 255, 255, 0.34);
    }
    52% {
        box-shadow:
            0 0 0 1px rgba(255, 255, 255, 0.82),
            0 0 22px rgba(56, 189, 248, 0.38),
            0 0 32px rgba(250, 204, 21, 0.3),
            inset 0 1px 0 rgba(255, 255, 255, 0.42);
    }
}

@keyframes tarotArcanaHaloSpin {
    from {
        transform: rotate(0deg) scale(1);
    }
    to {
        transform: rotate(360deg) scale(1);
    }
}

@keyframes tarotArcanaHaloBreath {
    0%,
    100% {
        opacity: 0.26;
    }
    50% {
        opacity: 0.46;
    }
}

@keyframes tarotArcanaMatchGlow {
    0%,
    100% {
        box-shadow:
            0 0 0 1px rgba(255, 255, 255, 0.28),
            0 0 8px rgba(255, 255, 255, 0.18),
            inset 0 1px 0 rgba(255, 255, 255, 0.15);
        filter: brightness(1);
    }
    50% {
        box-shadow:
            0 0 0 1px rgba(255, 255, 255, 0.76),
            0 0 16px rgba(255, 255, 255, 0.82),
            0 0 24px rgba(254, 240, 138, 0.66),
            inset 0 1px 0 rgba(255, 255, 255, 0.28);
        filter: brightness(1.08);
    }
}

