.tarot-judgment-options button {
    width: 100%;
}

.tarot-effect-overlay {
    position: fixed;
    inset: 0;
    z-index: 3600;
    pointer-events: none;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    transition: opacity 0.2s ease;
    background: radial-gradient(circle, rgba(255, 231, 153, 0.24), rgba(0, 0, 0, 0.78));
    color: #fff;
    font-size: clamp(22px, 5vw, 42px);
    font-weight: 900;
    letter-spacing: 0.1em;
    text-shadow: 0 0 24px rgba(255, 217, 122, 0.8);
}

.tarot-effect-overlay.show {
    opacity: 1;
}

.tarot-effect-overlay.is-kingdom-clear {
    background: radial-gradient(circle, rgba(56, 189, 248, 0.24), rgba(0, 0, 0, 0.78));
}

.tarot-effect-overlay.is-kingdom-draw {
    background: radial-gradient(circle, rgba(52, 211, 153, 0.22), rgba(0, 0, 0, 0.78));
}

.tarot-effect-overlay.is-kingdom-call {
    background:
        radial-gradient(circle at 50% 40%, rgba(96, 165, 250, 0.34), rgba(0, 0, 0, 0.82)),
        conic-gradient(from 0deg at 50% 50%, rgba(59, 130, 246, 0.22), rgba(14, 116, 144, 0.18), rgba(59, 130, 246, 0.22));
}

.tarot-effect-overlay.is-kingdom-call.is-kingdom-call-freeze {
    animation: tarotKingdomCallFreeze 640ms cubic-bezier(0.2, 0.8, 0.22, 1) 1;
}

.tarot-effect-overlay.is-kingdom-roundend {
    background:
        radial-gradient(circle at 50% 38%, rgba(255, 239, 178, 0.34), rgba(0, 0, 0, 0.78)),
        conic-gradient(from 0deg at 50% 50%, rgba(250, 204, 21, 0.24), rgba(245, 158, 11, 0.16), rgba(250, 204, 21, 0.24));
    animation: tarotKingdomRoundEndFlash 740ms ease-out 1;
}

.tarot-effect-overlay.is-kingdom-grandfinal {
    background:
        radial-gradient(circle at 50% 34%, rgba(255, 246, 201, 0.5), rgba(32, 16, 0, 0.86)),
        conic-gradient(from 0deg at 50% 50%, rgba(250, 204, 21, 0.38), rgba(245, 158, 11, 0.28), rgba(217, 119, 6, 0.34), rgba(250, 204, 21, 0.38));
    animation: tarotKingdomGrandFinalFlash 1300ms ease-out 1;
}

.tarot-cutin {
    position: fixed;
    left: 50%;
    top: clamp(56px, 16vh, 150px);
    transform: translate(-50%, -18px) skewX(-12deg);
    min-width: min(560px, calc(100% - 20px));
    max-width: calc(100% - 20px);
    text-align: center;
    padding: 10px 16px;
    border-radius: 10px;
    border: 1px solid rgba(255, 255, 255, 0.2);
    background: linear-gradient(120deg, rgba(15, 23, 42, 0.92), rgba(30, 41, 59, 0.92));
    color: #fff;
    font-size: clamp(18px, 4.6vw, 34px);
    font-weight: 900;
    letter-spacing: 0.08em;
    white-space: pre-line;
    text-shadow:
        -1px -1px 0 #000,
        -1px 1px 0 #000,
        1px -1px 0 #000,
        1px 1px 0 #000;
    box-shadow: 0 12px 28px rgba(0, 0, 0, 0.45);
    z-index: 3590;
    pointer-events: none;
    opacity: 0;
    transition: opacity 220ms ease, transform 260ms ease;
}

.tarot-cutin.show {
    opacity: 1;
    transform: translate(-50%, 0) skewX(-12deg);
}

.tarot-cutin.is-player {
    border-color: rgba(34, 197, 94, 0.55);
    box-shadow: 0 10px 30px rgba(34, 197, 94, 0.25);
}

.tarot-cutin.is-kingdom-your-turn {
    border-color: rgba(250, 204, 21, 0.9);
    background: linear-gradient(120deg, rgba(120, 53, 15, 0.94), rgba(180, 83, 9, 0.9));
    color: #fff7d1;
    box-shadow:
        0 0 0 1px rgba(250, 204, 21, 0.45),
        0 0 28px rgba(250, 204, 21, 0.34),
        0 12px 28px rgba(0, 0, 0, 0.5);
    animation: tarotKingdomYourTurnCutinPulse 0.58s ease-out 1;
}

.tarot-cutin.is-cpu {
    border-color: rgba(239, 68, 68, 0.55);
    box-shadow: 0 10px 30px rgba(239, 68, 68, 0.25);
}

.tarot-cutin.is-kingdom-skip {
    border-color: rgba(56, 189, 248, 0.82);
    background: linear-gradient(120deg, rgba(8, 47, 73, 0.96), rgba(12, 74, 110, 0.96));
    color: #e0f2fe;
}

.tarot-cutin.is-kingdom-raid-transform {
    border-color: rgba(248, 113, 113, 0.94);
    background:
        radial-gradient(circle at 50% 50%, rgba(255, 93, 70, 0.24), transparent 48%),
        linear-gradient(120deg, rgba(45, 5, 14, 0.98), rgba(107, 13, 29, 0.97));
    color: #fff1e6;
    box-shadow:
        0 14px 36px rgba(127, 29, 29, 0.46),
        0 0 30px rgba(248, 113, 113, 0.3);
}

.tarot-cutin.is-kingdom-cut {
    border-color: rgba(244, 114, 182, 0.85);
    background: linear-gradient(120deg, rgba(80, 7, 36, 0.96), rgba(131, 24, 67, 0.96));
    color: #fce7f3;
}

.tarot-cutin.is-kingdom-reverse {
    border-color: rgba(251, 191, 36, 0.92);
    background: linear-gradient(120deg, rgba(69, 26, 3, 0.97), rgba(120, 53, 15, 0.97));
    color: #fef3c7;
    box-shadow:
        0 14px 36px rgba(245, 158, 11, 0.38),
        0 0 28px rgba(251, 191, 36, 0.3);
}

.tarot-cutin.is-kingdom-lock {
    border-color: rgba(34, 197, 94, 0.85);
    background: linear-gradient(120deg, rgba(5, 46, 22, 0.96), rgba(22, 101, 52, 0.96));
    color: #dcfce7;
}

.tarot-cutin.is-kingdom-clear-combo {
    border-color: rgba(56, 189, 248, 0.96);
    background: linear-gradient(120deg, rgba(8, 47, 73, 0.97), rgba(3, 105, 161, 0.96));
    color: #e0f2fe;
    box-shadow:
        0 14px 36px rgba(14, 116, 144, 0.42),
        0 0 28px rgba(56, 189, 248, 0.36);
    animation: tarotKingdomClearComboCutin 860ms cubic-bezier(0.2, 0.86, 0.2, 1) 1;
}

.tarot-cutin.is-kingdom-clear-gold {
    border-color: rgba(251, 191, 36, 0.98);
    background: linear-gradient(120deg, rgba(120, 53, 15, 0.98), rgba(180, 83, 9, 0.97));
    color: #fff7db;
    box-shadow:
        0 16px 40px rgba(245, 158, 11, 0.5),
        0 0 34px rgba(251, 191, 36, 0.38);
    animation:
        tarotKingdomClearGoldCutin 980ms cubic-bezier(0.2, 0.86, 0.2, 1) 1,
        tarotKingdomClearGoldPulse 520ms ease-in-out 2;
}

.tarot-cutin.is-kingdom-call {
    border-color: rgba(59, 130, 246, 0.92);
    background: linear-gradient(120deg, rgba(15, 23, 42, 0.97), rgba(30, 64, 175, 0.97));
    color: #dbeafe;
    box-shadow:
        0 14px 36px rgba(59, 130, 246, 0.42),
        0 0 30px rgba(96, 165, 250, 0.32);
    animation: tarotKingdomCallDon 820ms cubic-bezier(0.2, 0.8, 0.2, 1) 1;
}

.tarot-cutin.is-kingdom-role {
    border-color: rgba(192, 132, 252, 0.9);
    background: linear-gradient(120deg, rgba(59, 7, 100, 0.96), rgba(88, 28, 135, 0.96));
    color: #f3e8ff;
    box-shadow:
        0 14px 36px rgba(168, 85, 247, 0.36),
        0 0 26px rgba(216, 180, 254, 0.28);
}

.tarot-cutin.is-kingdom-round-end {
    border-color: rgba(250, 204, 21, 0.96);
    background: linear-gradient(120deg, rgba(120, 53, 15, 0.97), rgba(146, 64, 14, 0.97));
    color: #fff7db;
    box-shadow:
        0 16px 40px rgba(245, 158, 11, 0.46),
        0 0 34px rgba(250, 204, 21, 0.32);
    animation: tarotKingdomRoundEndCutin 920ms cubic-bezier(0.18, 0.86, 0.22, 1) 1;
}

.tarot-cutin.is-kingdom-round-out {
    border-color: rgba(251, 191, 36, 0.96);
    background:
        linear-gradient(120deg, rgba(120, 53, 15, 0.98), rgba(180, 83, 9, 0.96));
    color: #fff9de;
    box-shadow:
        0 16px 42px rgba(245, 158, 11, 0.5),
        0 0 36px rgba(250, 204, 21, 0.36);
    animation: tarotKingdomRoundOutCutin 1100ms cubic-bezier(0.16, 0.84, 0.2, 1) 1;
}

.tarot-cutin.is-kingdom-grand-win {
    border-color: rgba(250, 204, 21, 0.98);
    background:
        linear-gradient(120deg, rgba(101, 23, 0, 0.99), rgba(146, 64, 14, 0.98));
    color: #fffbe9;
    font-size: clamp(24px, 6.3vw, 56px);
    letter-spacing: 0.1em;
    box-shadow:
        0 18px 48px rgba(245, 158, 11, 0.56),
        0 0 44px rgba(250, 204, 21, 0.42);
    animation:
        tarotKingdomGrandWinCutin 2200ms cubic-bezier(0.2, 0.86, 0.2, 1) 1,
        tarotKingdomGrandWinPulse 560ms ease-in-out 3;
}

@keyframes tarotKingdomCallDon {
    0% {
        transform: translate(-50%, 8px) skewX(-12deg) scale(0.92);
        filter: saturate(0.9) brightness(0.9);
    }
    36% {
        transform: translate(-50%, 6px) skewX(-12deg) scale(0.9);
        filter: saturate(0.95) brightness(0.95);
    }
    62% {
        transform: translate(-50%, -2px) skewX(-12deg) scale(1.08);
        filter: saturate(1.2) brightness(1.22);
    }
    100% {
        transform: translate(-50%, 0) skewX(-12deg) scale(1);
        filter: saturate(1) brightness(1);
    }
}

@keyframes tarotKingdomCallTrail {
    0% {
        opacity: 0.1;
        transform: translateX(16px) scaleX(0.92);
    }
    55% {
        opacity: 1;
        transform: translateX(4px) scaleX(1.02);
    }
    100% {
        opacity: 0;
        transform: translateX(0) scaleX(1.08);
    }
}

@keyframes tarotKingdomCallFreeze {
    0% {
        opacity: 0;
        filter: saturate(0.86) brightness(0.82);
    }
    35% {
        opacity: 1;
        filter: saturate(1.08) brightness(1.04);
    }
    100% {
        opacity: 1;
        filter: saturate(1) brightness(1);
    }
}

@keyframes tarotKingdomCallPotPulse {
    0% {
        filter: brightness(1) saturate(1);
    }
    45% {
        filter: brightness(1.22) saturate(1.2);
    }
    100% {
        filter: brightness(1) saturate(1);
    }
}

.tarot-coin-fx {
    position: fixed;
    z-index: 3605;
    pointer-events: none;
    user-select: none;
    line-height: 1;
    font-size: clamp(18px, 2.8vw, 26px);
    filter: drop-shadow(0 2px 5px rgba(0, 0, 0, 0.55));
    will-change: left, top, opacity, transform;
}

.tarot-coin-fx.is-player {
    text-shadow: 0 0 10px rgba(34, 197, 94, 0.75);
}

.tarot-coin-fx.is-cpu {
    text-shadow: 0 0 10px rgba(248, 113, 113, 0.75);
}

.tarot-coin-fx.is-payout {
    font-size: clamp(20px, 3.1vw, 30px);
    filter: drop-shadow(0 3px 8px rgba(0, 0, 0, 0.58));
}

.tarot-coin-fx.is-call-bet {
    text-shadow:
        0 0 12px rgba(147, 197, 253, 0.85),
        0 0 24px rgba(59, 130, 246, 0.58);
}

.is-call-pulse {
    animation: tarotKingdomCallPotPulse 620ms ease-out 1;
}

.tarot-cutin.is-showdown-win {
    border-color: rgba(34, 197, 94, 0.9);
    background: linear-gradient(120deg, rgba(5, 46, 22, 0.96), rgba(20, 83, 45, 0.96));
    color: #dcfce7;
    box-shadow:
        0 14px 36px rgba(34, 197, 94, 0.4),
        0 0 28px rgba(34, 197, 94, 0.32);
    animation: tarotShowdownCutinPulse 520ms ease-out 2;
}

.tarot-cutin.is-showdown-lose {
    border-color: rgba(248, 113, 113, 0.95);
    background: linear-gradient(120deg, rgba(69, 10, 10, 0.96), rgba(127, 29, 29, 0.96));
    color: #fee2e2;
    box-shadow:
        0 14px 36px rgba(239, 68, 68, 0.4),
        0 0 28px rgba(239, 68, 68, 0.28);
    animation: tarotShowdownCutinPulse 520ms ease-out 2;
}

.tarot-cutin.is-showdown-draw {
    border-color: rgba(250, 204, 21, 0.95);
    background: linear-gradient(120deg, rgba(69, 26, 3, 0.96), rgba(120, 53, 15, 0.96));
    color: #fef3c7;
    box-shadow:
        0 14px 36px rgba(245, 158, 11, 0.38),
        0 0 28px rgba(250, 204, 21, 0.25);
    animation: tarotShowdownCutinPulse 520ms ease-out 2;
}

@keyframes tarotShowdownCutinPulse {
    0% {
        transform: translate(-50%, 4px) skewX(-12deg) scale(0.98);
        filter: saturate(1);
    }
    55% {
        transform: translate(-50%, -1px) skewX(-12deg) scale(1.03);
        filter: saturate(1.3);
    }
    100% {
        transform: translate(-50%, 0) skewX(-12deg) scale(1);
        filter: saturate(1);
    }
}

@keyframes tarotKingdomRoundEndFlash {
    0% {
        opacity: 0;
        filter: saturate(0.9) brightness(0.88);
    }
    45% {
        opacity: 1;
        filter: saturate(1.12) brightness(1.08);
    }
    100% {
        opacity: 1;
        filter: saturate(1) brightness(1);
    }
}

@keyframes tarotKingdomClearSweepLine {
    0% {
        opacity: 0;
        transform: translateX(0) skewX(-14deg);
    }
    18% {
        opacity: 1;
        transform: translateX(18%) skewX(-14deg);
    }
    100% {
        opacity: 0;
        transform: translateX(300%) skewX(-14deg);
    }
}

@keyframes tarotKingdomClearSweepCard {
    0% {
        opacity: 1;
        transform: translateY(0) scale(1) rotate(0deg);
        filter: none;
    }
    26% {
        opacity: 1;
        transform: translateY(-2px) scale(0.99) rotate(-1deg);
        filter: brightness(1.06) saturate(1.08);
    }
    100% {
        opacity: 0;
        transform: translateX(24px) translateY(-8px) scale(0.9) rotate(-6deg);
        filter: brightness(1.12) saturate(1.22);
    }
}

@keyframes tarotKingdomClearComboCutin {
    0% {
        transform: translate(-50%, 8px) skewX(-12deg) scale(0.94);
        filter: saturate(0.9) brightness(0.9);
    }
    56% {
        transform: translate(-50%, -1px) skewX(-12deg) scale(1.06);
        filter: saturate(1.2) brightness(1.12);
    }
    100% {
        transform: translate(-50%, 0) skewX(-12deg) scale(1);
        filter: saturate(1) brightness(1);
    }
}

@keyframes tarotKingdomClearGoldCutin {
    0% {
        transform: translate(-50%, 10px) skewX(-12deg) scale(0.9);
        filter: saturate(0.86) brightness(0.86);
    }
    54% {
        transform: translate(-50%, -2px) skewX(-12deg) scale(1.08);
        filter: saturate(1.24) brightness(1.18);
    }
    100% {
        transform: translate(-50%, 0) skewX(-12deg) scale(1);
        filter: saturate(1) brightness(1);
    }
}

@keyframes tarotKingdomClearGoldPulse {
    0% { filter: saturate(1) brightness(1); }
    50% { filter: saturate(1.2) brightness(1.18); }
    100% { filter: saturate(1) brightness(1); }
}

@keyframes tarotKingdomRoundEndCutin {
    0% {
        transform: translate(-50%, 12px) skewX(-12deg) scale(0.92);
        filter: brightness(0.9) saturate(0.92);
    }
    55% {
        transform: translate(-50%, -2px) skewX(-12deg) scale(1.06);
        filter: brightness(1.12) saturate(1.2);
    }
    100% {
        transform: translate(-50%, 0) skewX(-12deg) scale(1);
        filter: brightness(1) saturate(1);
    }
}

@keyframes tarotKingdomRoundOutCutin {
    0% {
        transform: translate(-50%, 16px) skewX(-12deg) scale(0.88);
        filter: brightness(0.88) saturate(0.88);
    }
    48% {
        transform: translate(-50%, -4px) skewX(-12deg) scale(1.08);
        filter: brightness(1.16) saturate(1.24);
    }
    100% {
        transform: translate(-50%, 0) skewX(-12deg) scale(1);
        filter: brightness(1) saturate(1);
    }
}

@keyframes tarotKingdomGrandWinCutin {
    0% {
        transform: translate(-50%, 24px) skewX(-12deg) scale(0.84);
        filter: brightness(0.8) saturate(0.84);
    }
    30% {
        transform: translate(-50%, 2px) skewX(-12deg) scale(1.08);
        filter: brightness(1.2) saturate(1.28);
    }
    68% {
        transform: translate(-50%, -2px) skewX(-12deg) scale(1.04);
        filter: brightness(1.12) saturate(1.2);
    }
    100% {
        transform: translate(-50%, 0) skewX(-12deg) scale(1);
        filter: brightness(1) saturate(1);
    }
}

@keyframes tarotKingdomGrandWinPulse {
    0% {
        filter: brightness(1) saturate(1);
    }
    45% {
        filter: brightness(1.22) saturate(1.26);
    }
    100% {
        filter: brightness(1) saturate(1);
    }
}

@keyframes tarotKingdomGrandFinalFlash {
    0% {
        opacity: 0;
        filter: brightness(0.82) saturate(0.82);
    }
    38% {
        opacity: 1;
        filter: brightness(1.2) saturate(1.24);
    }
    100% {
        opacity: 1;
        filter: brightness(1) saturate(1);
    }
}

.tarot-card-fly {
    position: fixed;
    left: 0;
    top: 0;
    box-shadow:
        0 14px 34px rgba(0, 0, 0, 0.52),
        0 0 0 1px rgba(255, 255, 255, 0.18);
    will-change: transform, opacity;
}

.tarot-kingdom-ram-card {
    z-index: 3635;
    pointer-events: none;
    filter: saturate(1.12) brightness(1.08);
}

.tarot-kingdom-ram-card::after {
    /* 衝突時のフラッシュ(トレイル)は完全廃止 */
    content: none;
    display: none;
    animation: none;
    opacity: 0;
}

.tarot-card.is-call-stolen {
    animation: tarotKingdomCallStealHit 220ms ease-out 1;
}

.tarot-kingdom-call-ghost {
    position: fixed;
    z-index: 3655;
    pointer-events: none;
    user-select: none;
    font-size: 24px;
    line-height: 1;
    filter: drop-shadow(0 0 10px rgba(147, 197, 253, 0.58));
    will-change: transform, opacity, left, top;
}

.tarot-kingdom-call-ghost-taunt {
    position: fixed;
    z-index: 3657;
    pointer-events: none;
    user-select: none;
    font-size: 26px;
    line-height: 1;
    filter: drop-shadow(0 0 12px rgba(191, 219, 254, 0.66));
    will-change: transform, opacity, left, top;
}

.tarot-kingdom-call-ghost-taunt.is-taunt {
    animation: tarotKingdomCallGhostTaunt 260ms ease-in-out infinite;
}

.tarot-kingdom-role-clash-card {
    z-index: 3640;
    pointer-events: none;
    filter: none;
}

.tarot-kingdom-role-clash-card::after {
    /* role clash 側もフラッシュは完全廃止 */
    content: none;
    display: none;
    animation: none;
    opacity: 0;
}

.tarot-kingdom-role-clash-particle {
    position: fixed;
    z-index: 3661;
    pointer-events: none;
    user-select: none;
    font-size: 18px;
    line-height: 1;
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.82);
    filter: drop-shadow(0 0 8px rgba(0, 0, 0, 0.4));
    will-change: transform, opacity, filter;
}

.tarot-kingdom-role-clash-particle.run {
    animation-name: tarotKingdomRoleClashParticle;
    animation-duration: var(--fx-dur, 300ms);
    animation-fill-mode: forwards;
    animation-timing-function: cubic-bezier(0.22, 0.78, 0.24, 1);
}

@keyframes tarotKingdomCallStealHit {
    0% {
        filter: brightness(1) saturate(1);
        transform: translateY(0) scale(1);
    }
    36% {
        filter: brightness(1.34) saturate(1.18);
        transform: translateY(-1px) scale(0.96);
    }
    100% {
        filter: brightness(1) saturate(1);
        transform: translateY(0) scale(1);
    }
}

@keyframes tarotKingdomCallGhostTaunt {
    0% {
        transform: translate(-50%, -50%) rotate(-5deg) scale(0.98);
    }
    20% {
        transform: translate(calc(-50% - 1px), calc(-50% - 2px)) rotate(4deg) scale(1.02);
    }
    40% {
        transform: translate(calc(-50% + 1px), calc(-50% + 1px)) rotate(-4deg) scale(1);
    }
    60% {
        transform: translate(calc(-50% - 1px), calc(-50% - 1px)) rotate(5deg) scale(1.03);
    }
    80% {
        transform: translate(calc(-50% + 1px), calc(-50% + 1px)) rotate(-3deg) scale(1.01);
    }
    100% {
        transform: translate(-50%, -50%) rotate(3deg) scale(1.02);
    }
}

@keyframes tarotKingdomRoleClashTrail {
    0% {
        opacity: 0.16;
        transform: translateX(12px) scaleX(0.86);
    }
    56% {
        opacity: 0.9;
        transform: translateX(4px) scaleX(1.02);
    }
    100% {
        opacity: 0;
        transform: translateX(0) scaleX(1.08);
    }
}

@keyframes tarotKingdomRoleClashParticle {
    0% {
        opacity: 0;
        transform: translate(-50%, -50%) scale(0.74);
    }
    36% {
        opacity: 1;
        transform: translate(-50%, -58%) scale(1.06);
    }
    100% {
        opacity: 0;
        transform: translate(-50%, -70%) scale(1.14);
    }
}

@keyframes tarotKingdomRamTrail {
    0% {
        opacity: 0.16;
        transform: translateX(10px) scaleX(0.86);
    }
    55% {
        opacity: 0.9;
        transform: translateX(3px) scaleX(1);
    }
    100% {
        opacity: 0;
        transform: translateX(0) scaleX(1.06);
    }
}

.tarot-fortune-overlay {
    position: fixed;
    inset: 0;
    z-index: 3800;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 14px;
    background: rgba(0, 0, 0, 0.72);
}

.tarot-fortune-modal {
    position: relative;
    width: min(560px, calc(100% - 12px));
    box-sizing: border-box;
    border-radius: 8px;
    border: 18px solid transparent;
    border-image: url("./assets/ui/panels/panel-blue-square.png") 24 fill / 18px / 0 stretch;
    background: transparent;
    box-shadow: 0 18px 44px rgba(0, 0, 0, 0.45);
    padding: 16px 16px 14px;
    text-align: center;
    color: #f8fbff;
    max-height: min(90dvh, 720px);
    overflow-y: auto;
    --tarot-card-w: 88px;
    --tarot-card-h: 138px;
}

.tarot-fortune-modal::before,
.tarot-fortune-modal::after {
    content: "";
    position: absolute;
    inset: 14px;
    border-radius: 8px;
    pointer-events: none;
    opacity: 0;
    transition: opacity 220ms ease;
}

.tarot-fortune-modal::before {
    background:
        repeating-conic-gradient(
            from -22deg at 50% 46%,
            rgba(255, 244, 184, 0) 0deg,
            rgba(255, 244, 184, 0.16) 11deg,
            rgba(255, 244, 184, 0) 24deg
        );
    mix-blend-mode: screen;
}

.tarot-fortune-modal::after {
    inset: 18px;
    border: 1px solid rgba(255, 232, 163, 0.38);
    box-shadow:
        inset 0 0 28px rgba(255, 232, 163, 0.12),
        0 0 26px rgba(255, 232, 163, 0.18);
}

.tarot-fortune-modal > * {
    position: relative;
    z-index: 1;
}

.tarot-fortune-modal.is-major-arcana {
    box-shadow:
        0 18px 44px rgba(0, 0, 0, 0.45),
        0 0 34px rgba(255, 232, 163, 0.2),
        0 0 58px rgba(125, 211, 252, 0.12);
}

.tarot-fortune-modal.is-major-arcana::before {
    opacity: 0.48;
    animation: tarotFortuneArcanaRays 8.5s linear infinite;
}

.tarot-fortune-modal.is-major-arcana::after {
    opacity: 1;
    animation: tarotFortuneArcanaFrame 2.8s ease-in-out infinite;
}

.tarot-fortune-close {
    position: absolute;
    z-index: 2;
    top: 0;
    right: 0;
}

.tarot-fortune-kicker {
    font-size: 10px;
    font-weight: 800;
    color: rgba(219, 234, 254, 0.78);
    margin-bottom: 2px;
}

.tarot-fortune-title {
    font-size: 24px;
    font-weight: 900;
    letter-spacing: 0;
    color: #fff4b8;
    text-shadow: 0 2px 2px rgba(0, 0, 0, 0.45);
    margin-bottom: 4px;
    padding-inline: 56px;
}

.tarot-fortune-sub {
    font-size: 12px;
    color: #dbeafe;
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.45);
    margin-bottom: 12px;
}

.tarot-fortune-arcana-badge {
    width: max-content;
    max-width: 100%;
    min-height: 24px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 12px;
    padding: 3px 12px;
    border: 1px solid rgba(255, 232, 163, 0.5);
    border-radius: 8px;
    background:
        linear-gradient(90deg, rgba(82, 52, 18, 0.5), rgba(164, 111, 36, 0.6), rgba(82, 52, 18, 0.5));
    color: #fff4b8;
    font-size: 10px;
    font-weight: 900;
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.62);
    box-shadow:
        inset 0 1px 0 rgba(255, 244, 184, 0.24),
        0 0 14px rgba(255, 232, 163, 0.18);
    animation: tarotFortuneArcanaBadge 1.9s ease-in-out infinite;
}

.tarot-fortune-arcana-badge[hidden] {
    display: none;
}

.tarot-fortune-stage {
    display: grid;
    grid-template-columns: minmax(96px, 0.8fr) minmax(0, 1.2fr);
    gap: 14px;
    align-items: center;
}

.tarot-fortune-card-host {
    min-height: calc(var(--tarot-card-h, 138px) + 10px);
    display: flex;
    align-items: center;
    justify-content: center;
}

.tarot-fortune-reading {
    min-height: 128px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 8px;
    text-align: left;
    padding: 12px 14px;
    border-radius: 8px;
    background: rgba(4, 12, 24, 0.5);
    box-shadow: inset 0 0 0 1px rgba(248, 226, 168, 0.16);
}

.tarot-fortune-modal.is-major-arcana .tarot-fortune-reading {
    background:
        linear-gradient(180deg, rgba(12, 22, 38, 0.72), rgba(4, 12, 24, 0.58)),
        repeating-linear-gradient(135deg, rgba(255, 232, 163, 0.08) 0 1px, transparent 1px 12px);
    box-shadow:
        inset 0 0 0 1px rgba(255, 232, 163, 0.3),
        inset 0 0 28px rgba(255, 232, 163, 0.08),
        0 0 18px rgba(255, 232, 163, 0.16);
}

.tarot-fortune-card-shell {
    position: relative;
    width: var(--tarot-card-w, 64px);
    min-width: var(--tarot-card-w, 64px);
    height: var(--tarot-card-h, 100px);
    padding: 0;
    margin: 0;
    border: 0;
    border-radius: 8px;
    background: transparent;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
}

.tarot-fortune-card-shell.is-clickable {
    filter: drop-shadow(0 0 18px rgba(248, 226, 168, 0.22));
}

.tarot-fortune-card-shell.is-major-arcana {
    filter:
        drop-shadow(0 0 14px rgba(255, 232, 163, 0.5))
        drop-shadow(0 0 26px rgba(125, 211, 252, 0.22));
    animation: tarotFortuneArcanaCard 2.2s ease-in-out infinite;
}

.tarot-fortune-card-shell.is-major-arcana::before {
    content: "";
    position: absolute;
    inset: -11px;
    border-radius: 12px;
    pointer-events: none;
    background:
        conic-gradient(
            from 0deg,
            rgba(255, 244, 184, 0.08),
            rgba(255, 232, 163, 0.5),
            rgba(125, 211, 252, 0.22),
            rgba(255, 244, 184, 0.08)
        );
    opacity: 0.72;
    transform: rotate(0deg);
    animation: tarotFortuneArcanaHalo 3.6s linear infinite;
    z-index: -1;
}

.tarot-fortune-card-shell .tarot-fortune-card-art {
    transform-origin: center center;
}

.tarot-fortune-card-shell.is-static,
.tarot-fortune-card-shell.is-revealed {
    cursor: default;
}

.tarot-fortune-card-shell:focus-visible {
    outline: 2px solid rgba(248, 226, 168, 0.92);
    outline-offset: 4px;
}

.tarot-fortune-card-shell:disabled {
    opacity: 1;
}

.tarot-fortune-card-shell.is-reversed .tarot-fortune-card-art {
    transform: translate(-50%, -50%) rotate(180deg);
}

.tarot-fortune-result-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    align-items: center;
}

.tarot-fortune-result-meta[hidden],
.tarot-fortune-reward[hidden] {
    display: none;
}

.tarot-fortune-card-name,
.tarot-fortune-orientation {
    display: inline-flex;
    align-items: center;
    min-height: 24px;
    padding: 3px 8px;
    border-radius: 999px;
    font-size: 12px;
    font-weight: 800;
    color: #fff7cc;
    background: rgba(127, 78, 20, 0.45);
    box-shadow: inset 0 0 0 1px rgba(248, 226, 168, 0.22);
}

.tarot-fortune-orientation {
    color: #dbeafe;
    background: rgba(33, 82, 142, 0.42);
}

.tarot-fortune-modal.is-major-arcana .tarot-fortune-card-name,
.tarot-fortune-modal.is-major-arcana .tarot-fortune-orientation {
    color: #fff4b8;
    background: rgba(127, 78, 20, 0.62);
    box-shadow:
        inset 0 0 0 1px rgba(255, 232, 163, 0.34),
        0 0 12px rgba(255, 232, 163, 0.12);
}

.tarot-fortune-text {
    font-size: 14px;
    line-height: 1.68;
    color: #f8fbff;
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.45);
    min-height: 42px;
    overflow-wrap: break-word;
    white-space: pre-line;
}

.tarot-fortune-text.is-result {
    --fortune-tone: 125, 211, 252;
    display: grid;
    gap: 8px;
    white-space: normal;
}

.tarot-fortune-text.is-result[data-fortune-tone="excellent"] {
    --fortune-tone: 250, 204, 21;
}

.tarot-fortune-text.is-result[data-fortune-tone="favorable"] {
    --fortune-tone: 74, 222, 128;
}

.tarot-fortune-text.is-result[data-fortune-tone="caution"] {
    --fortune-tone: 251, 146, 60;
}

.tarot-fortune-text.is-result[data-fortune-tone="storm"] {
    --fortune-tone: 248, 113, 113;
}

.tarot-fortune-summary,
.tarot-fortune-reading-section {
    margin: 0;
    border-radius: 8px;
}

.tarot-fortune-summary {
    padding: 9px 10px 10px;
    background:
        linear-gradient(135deg, rgba(var(--fortune-tone), 0.18), rgba(5, 14, 28, 0.42));
    box-shadow:
        inset 0 0 0 1px rgba(var(--fortune-tone), 0.34),
        0 5px 12px rgba(0, 0, 0, 0.16);
}

.tarot-fortune-section-label {
    display: block;
    margin-bottom: 3px;
    color: rgba(219, 234, 254, 0.86);
    font-size: 10px;
    font-weight: 900;
    letter-spacing: 0.08em;
    line-height: 1.3;
}

.tarot-fortune-summary-value {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 10px;
}

.tarot-fortune-wind {
    color: rgb(var(--fortune-tone));
    font-family: Georgia, "Yu Mincho", "Hiragino Mincho ProN", serif;
    font-size: clamp(22px, 5vw, 29px);
    line-height: 1.08;
    letter-spacing: 0.04em;
    text-shadow:
        0 2px 2px rgba(0, 0, 0, 0.72),
        0 0 12px rgba(var(--fortune-tone), 0.22);
}

.tarot-fortune-score {
    flex: 0 0 auto;
    color: #eef6ff;
    font-size: 12px;
    font-weight: 900;
    font-variant-numeric: tabular-nums;
}

.tarot-fortune-meter {
    display: grid;
    grid-template-columns: repeat(10, minmax(0, 1fr));
    gap: 3px;
    margin-top: 7px;
}

.tarot-fortune-meter-segment {
    height: 5px;
    border-radius: 999px;
    background: rgba(219, 234, 254, 0.12);
    box-shadow: inset 0 0 0 1px rgba(219, 234, 254, 0.08);
}

.tarot-fortune-meter-segment.is-filled {
    background: rgb(var(--fortune-tone));
    box-shadow: 0 0 6px rgba(var(--fortune-tone), 0.44);
}

.tarot-fortune-reading-section {
    padding: 8px 10px;
    background: rgba(3, 10, 22, 0.42);
    box-shadow: inset 0 0 0 1px rgba(219, 234, 254, 0.1);
}

.tarot-fortune-reading-section p {
    margin: 0;
    color: #f8fbff;
    font-size: 14px;
    line-height: 1.62;
}

.tarot-fortune-advice {
    background:
        linear-gradient(135deg, rgba(248, 226, 168, 0.12), rgba(3, 10, 22, 0.46));
    box-shadow: inset 0 0 0 1px rgba(248, 226, 168, 0.2);
}

.tarot-fortune-advice .tarot-fortune-section-label {
    color: #ffe8a3;
}

.tarot-fortune-reward {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    gap: 8px;
    align-items: baseline;
    font-size: 12px;
    line-height: 1.45;
    padding-top: 8px;
    border-top: 1px solid rgba(248, 226, 168, 0.16);
    overflow-wrap: break-word;
}

.tarot-fortune-reward-label {
    color: rgba(219, 234, 254, 0.78);
    font-size: 10px;
    font-weight: 900;
    letter-spacing: 0.06em;
}

.tarot-fortune-reward-value {
    color: #ffe8a3;
    font-size: 12px;
    font-weight: 900;
}

.tarot-fortune-actions {
    display: flex;
    justify-content: center;
    margin-top: 14px;
}

.tarot-fortune-done {
    min-height: 34px;
    min-width: 108px;
    border: 1px solid rgba(248, 226, 168, 0.42);
    border-radius: 8px;
    background: linear-gradient(180deg, rgba(143, 95, 32, 0.92), rgba(86, 47, 17, 0.92));
    color: #fff7cc;
    font-size: 13px;
    font-weight: 900;
    padding: 6px 16px;
    box-shadow: 0 8px 18px rgba(0, 0, 0, 0.26);
}

@keyframes tarotFortuneArcanaRays {
    from {
        transform: rotate(0deg) scale(1);
    }
    to {
        transform: rotate(360deg) scale(1);
    }
}

@keyframes tarotFortuneArcanaFrame {
    0%,
    100% {
        filter: brightness(1);
        opacity: 0.8;
    }
    50% {
        filter: brightness(1.2);
        opacity: 1;
    }
}

@keyframes tarotFortuneArcanaBadge {
    0%,
    100% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-1px);
    }
}

@keyframes tarotFortuneArcanaHalo {
    from {
        transform: rotate(0deg);
    }
    to {
        transform: rotate(360deg);
    }
}

@keyframes tarotFortuneArcanaCard {
    0%,
    100% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-2px);
    }
}

@media (prefers-reduced-motion: reduce) {
    .tarot-fortune-modal.is-major-arcana::before,
    .tarot-fortune-modal.is-major-arcana::after,
    .tarot-fortune-arcana-badge,
    .tarot-fortune-card-shell.is-major-arcana,
    .tarot-fortune-card-shell.is-major-arcana::before {
        animation: none;
    }
}

