@keyframes tarotPotPulse {
    0%, 100% { transform: translateY(0); filter: brightness(1); }
    50% { transform: translateY(-1px); filter: brightness(1.08); }
}

@keyframes tarotPotSheen {
    0%, 40% { transform: translateX(-120%); }
    55%, 100% { transform: translateX(140%); }
}

@keyframes tarotPotRoll {
    0% { transform: translateY(0) scale(1); filter: brightness(1); }
    50% { transform: translateY(-1px) scale(1.04); filter: brightness(1.16); }
    100% { transform: translateY(0) scale(1); filter: brightness(1); }
}

@keyframes tarotPulse {
    0% { box-shadow: 0 0 0 0 rgba(245, 158, 11, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.15); }
    50% { box-shadow: 0 0 0 4px rgba(245, 158, 11, 0.12), inset 0 1px 0 rgba(255, 255, 255, 0.15); }
    100% { box-shadow: 0 0 0 0 rgba(245, 158, 11, 0), inset 0 1px 0 rgba(255, 255, 255, 0.15); }
}

