.ship-exploration-loading-lines i::after {
    content: "";
    display: block;
    width: 42%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255, 248, 220, 0.75), transparent);
    animation: ship-exploration-loading-shimmer 1.15s ease-in-out infinite;
}

@keyframes ship-exploration-loading-sweep {
    0%, 100% { transform: rotate(-34deg); }
    50% { transform: rotate(34deg); }
}

@keyframes ship-exploration-loading-shimmer {
    0% { transform: translateX(-120%); }
    100% { transform: translateX(260%); }
}

@media (prefers-reduced-motion: reduce) {
    .ship-exploration-loading-compass::before,
    .ship-exploration-loading-route span::after,
    .ship-exploration-loading-lines i::after {
        animation: none;
    }
}

