/* Tarot Kingdom fixed exploration stages */
.ship-exploration-stage {
    overflow: hidden;
}

.ship-exploration-stage-label {
    display: block;
    color: #e5bd63;
    font-size: 11px;
    font-weight: 900;
    letter-spacing: 0.12em;
}

.ship-exploration-stage-monsters {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 5px;
    margin-top: 9px;
    padding: 6px;
    border: 1px solid rgba(88, 49, 19, 0.2);
    border-radius: 7px;
    background:
        linear-gradient(180deg, rgba(255, 248, 218, 0.34), rgba(76, 43, 19, 0.1));
}

.ship-exploration-stage-monster {
    min-width: 0;
    display: grid;
    grid-template-rows: 48px auto;
    justify-items: center;
    gap: 2px;
}

.ship-exploration-stage-monster-visual {
    position: relative;
    width: 100%;
    height: 48px;
    overflow: hidden;
}

.ship-exploration-stage-monster-sprite {
    position: absolute;
    z-index: 1;
    bottom: var(--exploration-monster-compact-result-bottom, 4px);
    left: 50%;
    transform-origin: center bottom;
    transform:
        translateX(calc(-50% + var(--exploration-monster-compact-anchor-offset-x, 0px)))
        scale(var(--exploration-monster-compact-scale, 1)) !important;
}

.ship-exploration-stage-monster.is-silhouette .ship-exploration-stage-monster-sprite {
    opacity: 0.74;
    filter:
        brightness(0)
        saturate(0)
        drop-shadow(0 3px 2px rgba(0, 0, 0, 0.54));
}

.ship-exploration-stage-monster.is-revealed .ship-exploration-stage-monster-sprite {
    filter: drop-shadow(0 4px 3px rgba(0, 0, 0, 0.38));
}

.ship-exploration-stage-monster-defeat {
    position: absolute;
    top: 0;
    right: 1px;
    z-index: 3;
    width: 20px;
    height: 20px;
    display: grid;
    place-items: center;
    border: 1px solid #f7dca1;
    border-radius: 50%;
    background: #9f241f;
    color: #fff8df;
    font-family: serif;
    font-size: 11px;
    font-weight: 900;
    line-height: 1;
    text-shadow: 0 1px 0 #3a0806;
    box-shadow: 0 2px 4px rgba(42, 11, 7, 0.46);
    transform: rotate(-8deg);
}

.ship-exploration-stage-monster-name {
    width: 100%;
    overflow: hidden;
    color: #4b2b15;
    font-size: 9px;
    font-weight: 900;
    line-height: 1.2;
    text-align: center;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.ship-exploration-stage-monster.is-silhouette .ship-exploration-stage-monster-name {
    color: #695642;
    letter-spacing: 0.06em;
}

.ship-exploration-stage-supply-slots {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 5px;
}

.ship-exploration-stage-supply-slots span {
    min-width: 0;
    padding: 6px 4px;
    overflow: hidden;
    border: 1px dashed rgba(211, 179, 102, 0.35);
    color: #8d846f;
    font-size: 10px;
    text-align: center;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.ship-exploration-stage-supply-slots span.is-filled {
    border-style: solid;
    border-color: #c79c47;
    color: #f0dfaa;
    background: rgba(94, 67, 18, 0.24);
}

@media (min-width: 521px) {
    .ship-exploration-stage-monster-sprite {
        bottom: var(--exploration-monster-result-bottom, 5px);
        transform:
            translateX(calc(-50% + var(--exploration-monster-anchor-offset-x, 0px)))
            scale(var(--exploration-monster-scale, 1)) !important;
    }
}

