}

.player-profile-equipment {
    display: grid;
    gap: 10px;
    margin-bottom: 14px;
}

.player-profile-equip-row {
    display: grid;
    grid-template-columns: 72px minmax(0, 1fr);
    gap: 10px;
    align-items: center;
    padding: 10px 12px;
    border-radius: 12px;
    border: 1px solid rgba(148, 163, 184, 0.16);
    background: rgba(8, 15, 29, 0.58);
}

.player-profile-equip-row span {
    font-size: 12px;
    font-weight: 700;
    color: #94a3b8;
}

.player-profile-equip-row strong {
    min-width: 0;
    font-size: 13px;
    color: #f8fafc;
    line-height: 1.5;
    word-break: break-word;
}

.player-profile-empty {
    padding: 14px;
    border-radius: 12px;
    border: 1px dashed rgba(148, 163, 184, 0.2);
    color: var(--text-sub);
    font-size: 12px;
    line-height: 1.6;
    background: rgba(8, 15, 29, 0.34);
}

#itemDetailButtons {
    flex-direction: column;
    align-items: stretch;
