}

.item-detail-close {
    width: 100%;
    margin-top: 8px;
    background: #4b5563;
}

.item-detail-action-note {
    width: 100%;
    padding: 10px 12px;
    border-radius: 12px;
    text-align: left;
    font-size: 12px;
    line-height: 1.5;
    color: #dbeafe;
    background: rgba(15, 23, 42, 0.72);
    border: 1px solid rgba(148, 163, 184, 0.16);
}

#battleModal.melee-battle-overlay {
    align-items: center;
    justify-content: center;
    padding: calc(10px + var(--safe-top)) 10px calc(10px + var(--safe-bottom));
    background: linear-gradient(180deg, rgba(5, 8, 14, 0.9), rgba(2, 6, 12, 0.96));
}

#battleModal .melee-battle-shell {
    width: min(96vw, 840px);
    max-width: 840px;
    max-height: min(94dvh, 780px);
    overflow: hidden;
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 18px;
    border: 1px solid transparent;
    border-image: url("./assets/ui/panels/panel-dark-gold.png") 32 fill / 14px / 0 stretch;
    border-radius: 0;
    color: #f8fafc;
    box-shadow: 0 22px 54px rgba(0, 0, 0, 0.56);
}

.melee-battle-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    min-height: 50px;
    padding: 8px 10px;
    border: 1px solid transparent;
    border-image: url("./assets/ui/panels/panel-dark-wide.png") 34 fill / 11px / 0 stretch;
}

.melee-battle-kicker {
    color: #f8d888;
    font-size: 10px;
    font-weight: 900;
    letter-spacing: 0.08em;
}

.melee-battle-title-block h2 {
    margin: 0;
    color: #fff7d6;
    font-size: 22px;
    line-height: 1.1;
    letter-spacing: 0;
}

.melee-battle-mode {
    flex: 0 0 auto;
    min-width: 58px;
    padding: 7px 9px;
    text-align: center;
    color: #27160b;
    font-size: 11px;
    font-weight: 900;
    border: 1px solid transparent;
    border-image: url("./assets/ui/buttons/button-gold-large.png") 24 fill / 9px / 0 stretch;
}

#battleStage.melee-battle-stage {
    flex: 0 0 auto;
    min-height: clamp(390px, 58dvh, 520px);
    display: block;
    padding: 0;
    position: relative;
    overflow: hidden;
    isolation: isolate;
    border: 1px solid transparent;
    border-image: url("./assets/ui/panels/panel-navy-wide.png") 34 / 12px / 0 stretch;
    background:
        linear-gradient(180deg, rgba(2, 7, 12, 0.08) 0%, rgba(7, 18, 24, 0.16) 42%, rgba(19, 12, 6, 0.72) 100%),
        linear-gradient(90deg, rgba(44, 12, 18, 0.34), transparent 28%, transparent 72%, rgba(10, 36, 32, 0.3)),
        url("./Sprites/background/deck.webp") center bottom / auto 150% no-repeat;
    box-shadow:
        inset 0 0 0 1px rgba(255, 240, 180, 0.08),
        inset 0 -64px 120px rgba(0, 0, 0, 0.54),
        0 18px 52px rgba(0, 0, 0, 0.44);
}

#battleStage.melee-battle-stage.is-damage-shake {
    animation: meleeDamageShake var(--melee-shake-duration, 260ms) cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

#battleStage.melee-battle-stage::before {
    content: "";
    position: absolute;
    left: 50%;
    top: 47%;
    z-index: 4;
    width: min(150px, 18%);
    height: 78%;
    display: none;
    place-items: center;
    transform: translate(-50%, -50%);
    border-left: 0;
    background:
        linear-gradient(90deg, transparent, rgba(248, 216, 136, 0.14), transparent),
        linear-gradient(180deg, transparent, rgba(248, 216, 136, 0.24), transparent);
    opacity: 0.88;
    pointer-events: none;
}

@keyframes meleeDamageShake {
    0%, 100% { transform: translate3d(0, 0, 0); }
    18% { transform: translate3d(calc(var(--melee-shake-x, 5px) * -1), var(--melee-shake-y, 1px), 0); }
    36% { transform: translate3d(var(--melee-shake-x, 5px), calc(var(--melee-shake-y, 1px) * -1), 0); }
    54% { transform: translate3d(calc(var(--melee-shake-x, 5px) * -0.62), 0, 0); }
    72% { transform: translate3d(calc(var(--melee-shake-x, 5px) * 0.62), var(--melee-shake-y, 1px), 0); }
}

#battleStage.melee-battle-stage.is-camera-hit-zoom {
    animation: meleeCameraHitZoom 260ms cubic-bezier(0.22, 0.8, 0.32, 1) both;
}

#battleStage.melee-battle-stage.is-camera-hit-zoom-crit {
    animation: meleeCameraHitZoomCrit 420ms cubic-bezier(0.18, 0.85, 0.28, 1) both;
}

@keyframes meleeCameraHitZoom {
    0%   { transform: scale(1); }
    30%  { transform: scale(1.045); }
    100% { transform: scale(1); }
}

@keyframes meleeCameraHitZoomCrit {
    0%   { transform: translate3d(0,0,0) scale(1); }
    12%  { transform: translate3d(-6px,1px,0) scale(1.09); }
    28%  { transform: translate3d(6px,-1px,0) scale(1.06); }
    46%  { transform: translate3d(-3px,0,0) scale(1.02); }
    70%  { transform: translate3d(2px,1px,0) scale(1); }
    100% { transform: translate3d(0,0,0) scale(1); }
}

#battleStage.melee-battle-stage.is-camera-hit-zoom-crit::before {
    display: grid;
    background: radial-gradient(circle at center, rgba(255,238,180,0.55), transparent 70%);
    width: 100%;
    height: 100%;
    left: 0;
    top: 0;
    transform: none;
    animation: meleeCritFlash 420ms ease-out both;
}

@keyframes meleeCritFlash {
    0%   { opacity: 0; }
    12%  { opacity: 1; }
    100% { opacity: 0; }
}

#battleStage.melee-battle-stage::after {
    content: "";
    position: absolute;
    inset: 8px;
    z-index: 1;
    pointer-events: none;
    background: linear-gradient(180deg, transparent 54%, rgba(0, 0, 0, 0.3));
    box-shadow:
        inset 0 0 46px rgba(0, 0, 0, 0.48),
        inset 0 0 0 1px rgba(255, 240, 180, 0.08);
}

.battle-player-area.melee-combatant {
    width: calc(50% + 28px);
    height: 100%;
    min-width: 0;
    position: absolute;
    top: 0;
    bottom: 0;
    display: block;
    overflow: visible;
    padding: 0;
    z-index: 3;
    border: 0;
}

.melee-combatant-enemy {
    left: 0;
}

.melee-combatant-player {
    right: 0;
}

.battle-player-area.melee-combatant::before {
    content: none;
    position: absolute;
    left: 50%;
    bottom: 110px;
    width: 156px;
    height: 24px;
    transform: translateX(-50%);
    border-radius: 50%;
    background:
        radial-gradient(ellipse, rgba(0, 0, 0, 0.56), transparent 72%),
        radial-gradient(ellipse, rgba(248, 216, 136, 0.16), transparent 58%);
    z-index: 1;
    pointer-events: none;
}

.battle-player-area.melee-combatant::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 0;
    pointer-events: none;
}

.melee-combatant-enemy.battle-player-area::after {
    background: linear-gradient(90deg, rgba(127, 29, 29, 0.22), transparent 58%);
}

.melee-combatant-player.battle-player-area::after {
    background: linear-gradient(270deg, rgba(20, 83, 72, 0.22), transparent 58%);
}

.melee-combatant-enemy.battle-player-area::before {
    left: 40%;
}

.melee-combatant-player.battle-player-area::before {
    left: 60%;
}

.battle-avatar-container.melee-avatar {
    --avatar-combat-scale: 2.18;
    --avatar-combat-scale-hit: var(--avatar-combat-scale);
    --avatar-foot-shadow-width: 70px;
    --avatar-foot-shadow-height: 14px;
    --avatar-foot-shadow-bottom: -5px;
    --avatar-attack-start-x: -50%;
    --avatar-attack-x: 38px;
    --avatar-attack-recoil-x: 24px;
    --avatar-attack-y: 0px;
}

.melee-combatant-enemy .battle-avatar-container.melee-avatar {
    --avatar-attack-x: 38px;
    --avatar-attack-recoil-x: 24px;
    --avatar-facing-scale-x: -1;
    left: 40%;
}

.melee-combatant-player .battle-avatar-container.melee-avatar {
    --avatar-attack-x: -38px;
    --avatar-attack-recoil-x: -24px;
    --avatar-facing-scale-x: 1;
    left: 60%;
    bottom: 118px;
}

.battle-avatar-container.melee-avatar.is-avatar-attack-left {
    --avatar-attack-x: -38px;
    --avatar-attack-recoil-x: -24px;
}

.battle-avatar-container.melee-avatar.is-avatar-attack-right {
    --avatar-attack-x: 38px;
    --avatar-attack-recoil-x: 24px;
}

.melee-status-tray {
    position: absolute;
    left: 50%;
    bottom: 86px;
    z-index: 7;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
    min-width: 30px;
    min-height: 24px;
    padding: 3px 5px;
    border: 1px solid rgba(105, 78, 45, 0.58);
    border-radius: 5px;
    background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.08), transparent 44%),
        rgba(8, 10, 14, 0.72);
    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.08),
        0 10px 18px rgba(0, 0, 0, 0.34);
    transform: translateX(-50%);
    pointer-events: none;
}

.melee-status-tray.is-empty {
    opacity: 0;
}

.melee-status-tray.is-enemy-side {
    left: 20%;
}

.melee-status-tray.is-player-side {
    left: 80%;
}

.melee-status-tray .melee-status-icon {
    width: 21px;
    height: 21px;
    flex: 0 0 21px;
    filter:
        drop-shadow(0 1px 0 rgba(0, 0, 0, 0.9))
        drop-shadow(0 0 5px rgba(240, 211, 142, 0.28));
}

.melee-minor-arcana-effect {
    position: absolute;
    left: 50%;
    top: 50%;
    bottom: auto;
    z-index: 2;
    display: grid;
    justify-items: center;
    gap: 7px;
    width: 150px;
    --minor-entry-x: 0px;
    --minor-exit-x: 0px;
    pointer-events: none;
    transform: translate(-50%, -50%);
    opacity: 0;
    filter: drop-shadow(0 18px 24px rgba(0, 0, 0, 0.52));
    animation: meleeMinorArcanaCenter 2800ms cubic-bezier(0.16, 0.72, 0.22, 1) both;
}

.melee-minor-arcana-effect.is-enemy-side {
    left: 50%;
    --minor-entry-x: clamp(-220px, -18vw, -118px);
    --minor-exit-x: -18px;
}

.melee-minor-arcana-effect.is-player-side {
    left: 50%;
    --minor-entry-x: clamp(118px, 18vw, 220px);
    --minor-exit-x: 18px;
}

.melee-minor-arcana-card {
    position: relative;
    width: 90px;
    aspect-ratio: 48 / 80;
    border-radius: 8px;
    background:
        radial-gradient(circle at 50% 35%, rgba(255, 242, 178, 0.28), transparent 62%),
        rgba(9, 14, 24, 0.56);
    box-shadow:
        0 0 0 2px rgba(35, 20, 8, 0.72),
        0 0 24px rgba(244, 211, 126, 0.42),
        inset 0 1px 0 rgba(255, 255, 255, 0.18);
    overflow: hidden;
}

.melee-minor-arcana-art {
    border-color: rgba(255, 236, 174, 0.86);
    border-radius: 8px;
    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.26),
        0 0 16px rgba(244, 211, 126, 0.34);
}

.melee-minor-arcana-name {
    max-width: 166px;
    padding: 5px 9px 6px;
    overflow: hidden;
    border: 1px solid rgba(244, 211, 126, 0.62);
    border-radius: 7px;
    background: rgba(16, 10, 5, 0.9);
    color: #ffe8a8;
    font-size: 12px;
    font-weight: 1000;
    line-height: 1.15;
    text-align: center;
    text-overflow: ellipsis;
    text-shadow: 0 1px 2px #000;
    white-space: nowrap;
}

.melee-sprite-attack-effect {
    position: absolute;
    left: 50%;
    top: 43%;
    z-index: 9;
    display: grid;
    place-items: center;
    pointer-events: none;
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.78);
    animation: meleeElementalAttackBurst 1320ms cubic-bezier(0.16, 0.72, 0.22, 1) both;
}

.melee-sprite-attack-effect.is-enemy-side {
    left: 34%;
}

.melee-sprite-attack-effect.is-player-side {
    left: 66%;
}

.melee-attack-effect-sprite {
    display: block;
    background-repeat: no-repeat;
    image-rendering: pixelated;
    filter:
        drop-shadow(0 0 12px rgba(255, 242, 178, 0.28))
        drop-shadow(0 12px 18px rgba(0, 0, 0, 0.42));
}

.melee-sprite-attack-effect[data-element="wind"] .melee-attack-effect-sprite {
    filter:
        drop-shadow(0 0 12px rgba(186, 230, 253, 0.34))
        drop-shadow(0 12px 18px rgba(0, 0, 0, 0.42));
}

.melee-sprite-attack-effect[data-element="earth"] .melee-attack-effect-sprite {
    filter:
        drop-shadow(0 0 12px rgba(187, 247, 208, 0.3))
        drop-shadow(0 12px 18px rgba(0, 0, 0, 0.42));
}

.melee-sprite-attack-effect[data-element="water"] .melee-attack-effect-sprite {
    filter:
        drop-shadow(0 0 12px rgba(125, 211, 252, 0.34))
        drop-shadow(0 12px 18px rgba(0, 0, 0, 0.42));
}

@keyframes meleeElementalAttackBurst {
    0% {
        opacity: 0;
        transform: translate(-50%, calc(-50% + 18px)) scale(0.64);
    }
    12% {
        opacity: 1;
        transform: translate(-50%, -50%) scale(1.08);
    }
    74% {
        opacity: 1;
        transform: translate(-50%, calc(-50% - 6px)) scale(1);
    }
    100% {
        opacity: 0;
        transform: translate(-50%, calc(-50% - 16px)) scale(0.9);
    }
}

@keyframes meleeMinorArcanaCenter {
    0% {
        opacity: 0;
        transform: translate(calc(-50% + var(--minor-entry-x)), calc(-50% + 12px)) scale(0.88);
    }
    16% {
        opacity: 1;
        transform: translate(-50%, calc(-50% - 2px)) scale(1.06);
    }
