@keyframes meleeDamageNumberPop {
    0% {
        opacity: 0;
        transform: translate(calc(-50% + var(--feedback-x, 0px)), 8px) scale(0.86);
    }
    18% {
        opacity: 1;
        transform: translate(calc(-50% + var(--feedback-x, 0px)), -7px) scale(1.08);
    }
    34% {
        opacity: 1;
        transform: translate(calc(-50% + var(--feedback-x, 0px)), -2px) scale(1);
    }
    76% {
        opacity: 1;
        transform: translate(calc(-50% + var(--feedback-x, 0px)), -26px) scale(1);
    }
    100% {
        opacity: 0;
        transform: translate(calc(-50% + var(--feedback-x, 0px)), -38px) scale(0.98);
    }
}

@keyframes meleeHealNumberPop {
    0% {
        opacity: 0;
        transform: translate(calc(-50% + var(--feedback-x, 0px)), 8px) scale(0.86);
    }
    20% {
        opacity: 1;
        transform: translate(calc(-50% + var(--feedback-x, 0px)), -6px) scale(1.06);
    }
    76% {
        opacity: 1;
        transform: translate(calc(-50% + var(--feedback-x, 0px)), -24px) scale(1);
    }
    100% {
        opacity: 0;
        transform: translate(calc(-50% + var(--feedback-x, 0px)), -38px) scale(0.98);
    }
}

@keyframes meleeStatusCardPop {
    0% {
        opacity: 0;
        transform: translate(calc(-50% + var(--feedback-x, 0px)), 6px) scale(0.92);
    }
    18% {
        opacity: 1;
        transform: translate(calc(-50% + var(--feedback-x, 0px)), -2px) scale(1.02);
    }
    28% {
        transform: translate(calc(-50% + var(--feedback-x, 0px)), 0) scale(1);
    }
    82% {
        opacity: 1;
        transform: translate(calc(-50% + var(--feedback-x, 0px)), -16px) scale(1);
    }
    100% {
        opacity: 0;
        transform: translate(calc(-50% + var(--feedback-x, 0px)), -28px) scale(0.98);
    }
}

@keyframes meleeDamageDigitSnap {
    0% {
        transform: translateY(8px) scale(0.88);
        opacity: 0;
    }
    60% {
        transform: translateY(-2px) scale(1.05);
        opacity: 1;
    }
    100% {
        transform: translateY(0) scale(1);
        opacity: 1;
    }
}

@keyframes meleeDamageImpactRing {
    0% {
        opacity: 0;
        transform: translate(-50%, -50%) scale(0.5);
    }
    35% {
        opacity: 0.42;
    }
    100% {
        opacity: 0;
        transform: translate(-50%, -50%) scale(1.08);
    }
}

