    padding: 14px;
    border-radius: 18px;
    background:
        linear-gradient(180deg, rgba(30, 41, 59, 0.92), rgba(15, 23, 42, 0.94)),
        radial-gradient(circle at 18% 0%, rgba(250, 204, 21, 0.2), transparent 58%);
    border: 1px solid rgba(250, 204, 21, 0.22);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.equipment-gacha-chest-wrap {
    width: 100%;
    aspect-ratio: 1 / 1;
    display: grid;
    place-items: center;
    border-radius: 12px;
    background: rgba(2, 6, 23, 0.34);
    border: 1px solid rgba(148, 163, 184, 0.16);
    overflow: hidden;
}

