    image-rendering: pixelated;
    background-repeat: no-repeat;
    background-size: 800% 100%;
    background-position: 0 0;
    filter: drop-shadow(0 12px 18px rgba(0, 0, 0, 0.42));
}

.equipment-gacha-chest.is-idle {
    background-image: url("./Sprites/items/Chest/chest1_idle_strip8.png");
    animation: equipment-gacha-idle 900ms steps(8) infinite;
}

.equipment-gacha-chest.is-opening {
    background-image: url("./Sprites/items/Chest/chest1_open_strip8.png");
    animation: equipment-gacha-open 720ms steps(8) 1 forwards;
}

.equipment-gacha-chest.is-open {
    background-image: url("./Sprites/items/Chest/chest1_open_strip8.png");
    background-position: 100% 0;
}

.equipment-gacha-btn {
    min-height: 54px;
    align-self: end;
    border-radius: 12px;
    color: #111827;
    background: linear-gradient(180deg, #facc15, #d97706);
    border-color: rgba(253, 224, 71, 0.5);
    font-weight: 800;
}

.equipment-gacha-btn:disabled {
    opacity: 0.72;
}

