    grid-column: 2;
    min-height: 20px;
    margin: -4px 0 0;
    font-size: 13px;
    line-height: 1.5;
    color: #fde68a;
}

@keyframes equipment-gacha-idle {
    from { background-position: 0 0; }
    to { background-position: 100% 0; }
}

@keyframes equipment-gacha-open {
    from { background-position: 0 0; transform: scale(1); }
    55% { transform: scale(1.08); }
    to { background-position: 100% 0; transform: scale(1); }
}

