    font-weight: 700;
    color: rgba(251, 191, 36, 0.9);
    letter-spacing: 0.04em;
}
.ship-skill-sheet-close {
    margin: -10px -10px -10px 0;
}

/* ── スキルグリッド ───────────────────────────────── */
.ship-skill-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
    gap: 10px;
}

/* ── スキルカード ─────────────────────────────────── */
.ship-skill-card {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    padding: 12px 10px 10px;
    border-radius: 18px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    background: rgba(15, 23, 42, 0.7);
    cursor: pointer;
    transition: opacity 0.15s, transform 0.15s, border-color 0.2s;
    -webkit-tap-highlight-color: transparent;
    overflow: hidden;
}
.ship-skill-card::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    opacity: 0.15;
    transition: opacity 0.2s;
    pointer-events: none;
}
.ship-skill-card:active {
    transform: scale(0.96);
}
.ship-skill-card:disabled,
.ship-skill-card[data-ct-remaining]:not([data-ct-remaining="0"]) {
    cursor: not-allowed;
}
.ship-skill-card[data-ct-remaining]:not([data-ct-remaining="0"]) .ship-skill-card-name,
.ship-skill-card[data-ct-remaining]:not([data-ct-remaining="0"]) .ship-skill-card-desc {
    opacity: 0.5;
}

/* 属性別カラー */
.ship-skill-card[data-element="fire"] {
    border-color: rgba(251, 146, 60, 0.45);
    background: linear-gradient(160deg, rgba(120, 53, 15, 0.6), rgba(15, 23, 42, 0.7));
}
.ship-skill-card[data-element="fire"]::before {
    background: radial-gradient(80% 60% at 50% 0%, rgba(251, 146, 60, 1), transparent);
}
.ship-skill-card[data-element="wind"] {
    border-color: rgba(99, 102, 241, 0.45);
    background: linear-gradient(160deg, rgba(30, 27, 75, 0.7), rgba(15, 23, 42, 0.7));
}
.ship-skill-card[data-element="wind"]::before {
    background: radial-gradient(80% 60% at 50% 0%, rgba(129, 140, 248, 1), transparent);
}
.ship-skill-card[data-element="water"] {
    border-color: rgba(14, 165, 233, 0.45);
    background: linear-gradient(160deg, rgba(8, 47, 73, 0.7), rgba(15, 23, 42, 0.7));
}
.ship-skill-card[data-element="water"]::before {
    background: radial-gradient(80% 60% at 50% 0%, rgba(56, 189, 248, 1), transparent);
}
.ship-skill-card[data-element="earth"] {
    border-color: rgba(34, 197, 94, 0.45);
    background: linear-gradient(160deg, rgba(20, 83, 45, 0.6), rgba(15, 23, 42, 0.7));
}
.ship-skill-card[data-element="earth"]::before {
    background: radial-gradient(80% 60% at 50% 0%, rgba(74, 222, 128, 1), transparent);
}
.ship-skill-card[data-element="none"] {
    border-color: rgba(251, 191, 36, 0.45);
    background: linear-gradient(160deg, rgba(69, 26, 3, 0.6), rgba(15, 23, 42, 0.7));
}
.ship-skill-card[data-element="none"]::before {
    background: radial-gradient(80% 60% at 50% 0%, rgba(251, 191, 36, 0.8), rgba(167, 139, 250, 0.6), transparent);
}

/* CTリング */
.ship-skill-ct-ring-wrap {
    position: relative;
    width: 56px;
    height: 56px;
    flex-shrink: 0;
}
.ship-skill-ct-ring-wrap svg {
    width: 100%;
    height: 100%;
    transform: rotate(-90deg);
}
.ship-skill-ct-ring-bg {
    fill: none;
    stroke: rgba(255, 255, 255, 0.08);
    stroke-width: 3;
}
.ship-skill-ct-ring-fill {
    fill: none;
    stroke-width: 3;
    stroke-linecap: round;
    transition: stroke-dashoffset 0.5s linear;
}
.ship-skill-card[data-element="fire"]    .ship-skill-ct-ring-fill { stroke: #fb923c; }
.ship-skill-card[data-element="wind"]   .ship-skill-ct-ring-fill { stroke: #818cf8; }
.ship-skill-card[data-element="water"]  .ship-skill-ct-ring-fill { stroke: #38bdf8; }
.ship-skill-card[data-element="earth"]  .ship-skill-ct-ring-fill { stroke: #4ade80; }
.ship-skill-card[data-element="none"]   .ship-skill-ct-ring-fill { stroke: #fbbf24; }

.ship-skill-ct-inner {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 1px;
}
.ship-skill-ct-icon {
    font-size: 18px;
    line-height: 1;
    pointer-events: none;
    user-select: none;
}
.ship-skill-ct-sec {
    font-size: 9px;
    font-weight: 700;
    color: rgba(226, 232, 240, 0.85);
    letter-spacing: -0.02em;
    min-height: 11px;
}

/* カード情報 */
.ship-skill-card-name {
    font-size: 13px;
    font-weight: 900;
    color: #f1f5f9;
    text-align: center;
    letter-spacing: 0.02em;
    transition: opacity 0.2s;
}
.ship-skill-card-meta {
    display: flex;
    align-items: center;
    gap: 5px;
    flex-wrap: wrap;
    justify-content: center;
}
.ship-skill-card-range {
    font-size: 9px;
    color: rgba(148, 163, 184, 0.8);
    background: rgba(15, 23, 42, 0.5);
    border-radius: 4px;
    padding: 1px 5px;
}
.ship-skill-card-cast {
    font-size: 9px;
    color: rgba(148, 163, 184, 0.8);
}
.ship-skill-card-desc {
    font-size: 9px;
    color: rgba(148, 163, 184, 0.75);
    text-align: center;
    line-height: 1.4;
    max-height: 2.8em;
    overflow: hidden;
    text-overflow: ellipsis;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    -webkit-box-orient: vertical;
    transition: opacity 0.2s;
}

/* 自動発動バッジ */
.ship-skill-auto-badge {
    position: absolute;
    top: 7px;
    right: 7px;
    font-size: 8px;
    font-weight: 700;
    color: rgba(251, 191, 36, 0.95);
    background: rgba(69, 26, 3, 0.85);
    border: 1px solid rgba(251, 191, 36, 0.4);
    border-radius: 6px;
    padding: 1px 5px;
    letter-spacing: 0.04em;
    pointer-events: none;
}

/* READY フラッシュ */
@keyframes ship-skill-ready-flash {
    0%   { box-shadow: 0 0 0 0 rgba(255,255,255,0.4); }
    70%  { box-shadow: 0 0 0 8px rgba(255,255,255,0); }
    100% { box-shadow: 0 0 0 0 rgba(255,255,255,0); }
}
.ship-skill-card.is-ready-flash {
    animation: ship-skill-ready-flash 0.6s ease-out;
}

.ship-skill-empty-msg {
    text-align: center;
    color: rgba(148, 163, 184, 0.5);
    font-size: 12px;
    padding: 24px 0;
}

