.troy-orders-ticket {
    position: relative;
    display: flex;
    width: 100%;
    min-height: 246px;
    flex-direction: column;
    gap: 8px;
    padding: 16px 15px 14px;
    border: 28px solid transparent;
    border-image: url('/assets/ui/panels/panel-parchment-large.png') 36 fill / 28px / 0 stretch;
    background: transparent;
    color: #35230f;
    text-align: left;
    cursor: pointer;
    box-shadow: 0 16px 26px rgba(0, 0, 0, 0.28);
    transform-origin: 50% 30%;
    transition: transform 0.12s ease, filter 0.12s ease;
    user-select: none;
    touch-action: none;
}

.troy-orders-ticket:hover,
.troy-orders-ticket:focus-visible {
    filter: brightness(1.05);
    transform: translateY(-2px);
    outline: none;
}

.troy-orders-ticket.is-tilt-left {
    rotate: -0.7deg;
}

.troy-orders-ticket.is-tilt-right {
    rotate: 0.7deg;
}

.troy-orders-ticket.is-selected {
    filter: brightness(1.08) saturate(1.05);
}

.troy-orders-ticket.is-dragging {
    z-index: 20;
    cursor: grabbing;
    filter: brightness(1.08) saturate(1.06);
    box-shadow: 0 24px 44px rgba(0, 0, 0, 0.46);
}

.troy-orders-ticket.is-drop-group {
    filter: brightness(1.12) saturate(1.12);
    outline: 3px solid rgba(174, 106, 32, 0.72);
    outline-offset: 4px;
}

.troy-orders-ticket.is-drop-before::before,
.troy-orders-ticket.is-drop-after::before {
    content: "";
    position: absolute;
    top: 18px;
    bottom: 18px;
    width: 6px;
    border-radius: 999px;
    background: #f2c56c;
    box-shadow: 0 0 0 2px rgba(60, 31, 8, 0.28), 0 0 14px rgba(242, 197, 108, 0.72);
    z-index: 4;
}

.troy-orders-ticket.is-drop-before::before {
    left: -10px;
}

.troy-orders-ticket.is-drop-after::before {
    right: -10px;
}

.troy-orders-ticket.is-grouped {
    min-height: 270px;
    filter: saturate(1.04);
    z-index: 0;
}

.troy-orders-ticket.is-grouped::after {
    content: "";
    position: absolute;
    inset: 12px -10px -12px 12px;
    z-index: -1;
    border: 28px solid transparent;
    border-image: url('/assets/ui/panels/panel-parchment-large.png') 36 fill / 28px / 0 stretch;
    opacity: 0.82;
    transform: rotate(2.2deg);
    pointer-events: none;
}

