    }

    .troy-orders-payment-box {
        grid-template-columns: 1fr;
    }

    .troy-orders-change-row strong {
        font-size: 28px;
    }

    .troy-orders-item-row {
        grid-template-columns: minmax(0, 1fr) 82px 78px;
    }

    .troy-orders-item-row [data-toggle-served],
    .troy-orders-item-row [data-remove-item] {
        grid-column: span 1;
    }

    .troy-orders-settle {
        grid-template-columns: 1fr;
    }

    .troy-orders-group-row {
        grid-template-columns: 22px minmax(0, 1fr);
    }

    .troy-orders-group-current-head {
        align-items: stretch;
        flex-direction: column;
    }

    .troy-orders-group-current-head button {
        width: 100%;
    }

    .troy-orders-group-current-row {
        grid-template-columns: 1fr;
    }

    .troy-orders-group-current-row b {
        text-align: left;
    }

    .troy-orders-group-row b {
        grid-column: 2;
        text-align: left;
    }

    .troy-orders-custom-price-row {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .troy-orders-custom-price-row label {
        grid-column: 1 / -1;
        order: -1;
    }

    .troy-orders-custom-presets {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .troy-orders-confirm-actions {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 480px) {
    .troy-orders-summary {
        grid-template-columns: 1fr;
