/* --- Inventory tab reference style --- */
#tabContentInventory {
    padding-bottom: calc(var(--nav-height) + 22px);
    --inventory-panel-bg: linear-gradient(180deg, rgba(7, 8, 10, 0.9), rgba(3, 4, 6, 0.98));
    --inventory-gold: #ffe4a0;
    --inventory-ink: #261306;
    --inventory-sticky-top: calc(134px + var(--safe-top));
    --inventory-switch-sticky-height: 72px;
    --inventory-selection-bar-height: 68px;
}

#tabContentInventory .inventory-mobile-switch {
    position: sticky;
    top: var(--inventory-sticky-top);
    z-index: 80;
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 4px;
    margin: 10px var(--app-gutter) 0;
    padding: 5px;
    overflow: visible;
    border-radius: 8px;
    border: 12px solid transparent;
    background: radial-gradient(ellipse at 50% 0%, rgba(255, 221, 142, 0.14), transparent 62%),
        var(--inventory-panel-bg);
    box-shadow: 0 12px 22px rgba(0, 0, 0, 0.3);
    backdrop-filter: none;
    border-image: url("./assets/ui/panels/panel-dark-gold.png") 32 fill / 12px / 0 stretch;
}

#tabContentInventory .inventory-panel-btn {
    min-width: 0;
    min-height: 58px;
    padding: 7px 4px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 3px;
    border: 1px solid transparent;
    border-right: 1px solid rgba(220, 169, 82, 0.22);
    border-radius: 7px;
    color: #d8c39b;
    font-size: 13px;
    font-weight: 900;
    text-shadow: 0 1px 0 #000;
    background: linear-gradient(180deg, rgba(18, 20, 24, 0.74), rgba(3, 4, 6, 0.88));
    box-shadow: none;
    flex-direction: column;
    border-image: url("./assets/ui/panels/panel-dark-square.png") 24 fill / 9px / 0 stretch;
    line-height: 1;
}

#tabContentInventory .inventory-panel-btn:last-child {
    border-right: 0;
}

#tabContentInventory .inventory-panel-btn::before {
    content: "";
    width: 28px;
    height: 28px;
    flex: 0 0 34px;
    background-position: center;
    background-repeat: no-repeat;
    background-size: 28px 28px;
    filter: drop-shadow(0 2px 2px rgba(0, 0, 0, 0.62));
    flex-basis: 28px;
}

#tabContentInventory .inventory-panel-btn[data-inventory-group-switch="Equipment"]::before {
    background-image: var(--icon-slot-equipment);
}

#tabContentInventory .inventory-panel-btn[data-inventory-group-switch="Tarot"]::before {
    background-image: var(--icon-slot-tarot);
}

#tabContentInventory .inventory-panel-btn[data-inventory-group-switch="All"]::before {
    background-image: var(--icon-slot-all);
}

#tabContentInventory .inventory-panel-btn.active {
    color: #d8c39b;
    background: radial-gradient(circle at 50% 18%, rgba(255, 249, 211, 0.38), transparent 45%),
        linear-gradient(180deg, rgba(230, 176, 66, 0.92), rgba(142, 82, 21, 0.96));
    border-color: rgba(255, 229, 149, 0.42);
    border-image: url("./assets/ui/panels/panel-gold-square.png") 24 fill / 9px / 0 stretch;
    text-shadow: 0 1px 0 #000;
}

#tabContentInventory .avatar-card.inventory-section {
    display: block;
    margin: 0 var(--app-gutter) 10px;
    padding: 12px;
}

#tabContentInventory .avatar-card.inventory-section:not(.active) {
    display: block;
}

#tabContentInventory[data-inventory-panel="items"][data-inventory-group="Tarot"] .avatar-card.inventory-section {
    display: none;
}

#tabContentInventory .inventory-avatar-stage,
#tabContentInventory .inventory-loadout-stats {
    display: none;
}

#tabContentInventory .avatar-card.inventory-section::before {
    content: "現在の装備";
    position: relative;
    z-index: 1;
    display: flex;
    width: 100%;
    align-items: center;
    min-height: 34px;
    margin: -2px 0 12px;
    padding: 0 14px;
    border-radius: 6px;
    color: #f2cf8a;
    font-size: 18px;
    font-weight: 900;
    text-shadow: 0 1px 0 #000;
    background: linear-gradient(180deg, rgba(75, 38, 14, 0.62), rgba(20, 12, 8, 0.88));
    max-width: none;
    justify-content: center;
    box-sizing: border-box;
}

#tabContentInventory #equipmentGrid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
    margin: 0;
    padding: 8px;
    border: 1px solid rgba(220, 169, 82, 0.34);
    border-radius: 8px;
    background: linear-gradient(180deg, rgba(7, 10, 14, 0.86), rgba(2, 4, 7, 0.94));
}

#tabContentInventory .equip-slot {
    min-height: 84px;
    padding: 10px;
    display: grid;
    grid-template-columns: 40px minmax(0, 1fr) 58px;
    align-items: center;
    gap: 7px;
    border-radius: 8px;
    border: 1px solid rgba(220, 169, 82, 0.28);
    background: linear-gradient(180deg, rgba(13, 19, 27, 0.84), rgba(5, 7, 10, 0.94));
    box-shadow: inset 0 1px 0 rgba(255, 239, 192, 0.08);
    border-image: url("./assets/ui/panels/panel-navy-wide.png") 34 fill / 11px / 0 stretch;
    border-color: transparent;
    cursor: pointer;
    position: relative;
}

#tabContentInventory .equip-slot-icon {
    width: 40px;
    height: 40px;
    margin: 0;
    display: block;
    border-radius: 50%;
    color: transparent;
    font-size: 0;
    background-position: center;
    background-repeat: no-repeat;
    background-size: 40px 40px;
    filter: drop-shadow(0 3px 4px rgba(0, 0, 0, 0.48));
    grid-column: 1;
    grid-row: 1;
    position: relative;
    z-index: 1;
}

#tabContentInventory .weapon-slot .equip-slot-icon {
    background-image: var(--icon-slot-weapon);
}

#tabContentInventory .shield-slot .equip-slot-icon {
    background-image: var(--icon-slot-shield);
}

#tabContentInventory .armor-slot .equip-slot-icon {
    background-image: var(--icon-slot-head),
        radial-gradient(circle at 50% 50%, rgba(255, 226, 142, 0.2), rgba(20, 14, 8, 0.92) 62%, transparent 64%),
        linear-gradient(180deg, rgba(168, 104, 35, 0.86), rgba(74, 42, 16, 0.94));
    background-position: center, center, center;
    background-repeat: no-repeat, no-repeat, no-repeat;
    background-size: 74% 74%, 100% 100%, 100% 100%;
}

#tabContentInventory .accessory-slot .equip-slot-icon {
    background-image: var(--icon-slot-accessory);
}

#tabContentInventory .equip-slot-content {
    min-width: 0;
    gap: 2px;
    text-align: left;
    grid-column: 2;
    grid-row: 1;
    display: flex;
    flex-direction: column;
    justify-content: center;
    padding-top: 2px;
    position: relative;
    z-index: 1;
}

#tabContentInventory .equip-slot-label {
    color: #d1ad72;
    font-size: 13px;
    font-weight: 900;
    letter-spacing: 0;
}

#tabContentInventory .equip-slot-name {
    color: #f7e8c1;
    font-size: 14px;
    font-weight: 900;
    display: block;
    max-width: 100%;
    line-height: 1.24;
    letter-spacing: 0;
    overflow-wrap: anywhere;
    text-shadow: 0 1px 0 #000;
    position: relative;
    z-index: 3;
}

#tabContentInventory .equip-slot-stats {
    justify-content: flex-start;
    min-height: 14px;
    margin-top: 1px;
    display: flex;
    flex-wrap: wrap;
    gap: 3px 6px;
    color: #f4efe3;
    font-size: 11px;
    font-weight: 900;
    line-height: 1.2;
    text-shadow: 0 1px 0 rgba(0, 0, 0, 0.94), 0 0 5px rgba(0, 0, 0, 0.72);
    position: relative;
    z-index: 3;
}

#tabContentInventory .inventory-section.active[data-panel="items"] {
    margin: 0 var(--app-gutter);
    padding: 14px;
}

#tabContentInventory .inventory-section[data-panel="items"] > .section-header {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: 8px;
    margin-bottom: 12px;
}

#tabContentInventory .inventory-browse-tools {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 40px;
    align-items: center;
    gap: 6px;
    margin: 0 0 8px;
}

#tabContentInventory .inventory-search-input {
    width: 100%;
    min-width: 0;
