.rpg-message-popup {
    position: fixed;
    left: max(14px, env(safe-area-inset-left));
    right: max(14px, env(safe-area-inset-right));
    bottom: calc(var(--rpg-message-bottom, 78px) + env(safe-area-inset-bottom));
    z-index: 10020;
    width: min(460px, calc(100vw - 28px));
    margin-inline: auto;
    padding: 16px 20px;
    border: 14px solid transparent;
    border-radius: 8px;
    box-sizing: border-box;
    font-size: 15px;
    font-weight: 900;
    line-height: 1.45;
    letter-spacing: 0;
    text-align: center;
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    max-height: min(260px, calc(100dvh - 118px));
    overflow-y: auto;
    filter: drop-shadow(0 10px 16px rgba(0, 0, 0, 0.42));
    animation: rpgMessagePopupIn 140ms ease-out;
    pointer-events: none;
}

.rpg-message-popup.is-normal {
    border-image: url("./assets/ui/panels/speech-parchment.png") 28 fill / 14px / 0 stretch;
    color: #241207;
    text-shadow: 0 1px 0 rgba(255, 246, 210, 0.55);
}

