    color: #fff;
    text-shadow: 0 2px 0 rgba(0, 0, 0, 0.65);
}

@keyframes rpgMessagePopupIn {
    from {
        opacity: 0;
        transform: translateY(10px) scale(0.98);
    }
    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

