#tabContentInventory .tarot-loadout-grid::before {
    content: attr(data-deck-count) "/5";
    position: absolute;
    right: 0;
    top: -30px;
    min-width: 42px;
    min-height: 22px;
    padding: 3px 8px;
    box-sizing: border-box;
    display: grid;
    place-items: center;
    border: 1px solid rgba(255, 226, 151, 0.34);
    border-radius: 999px;
    background: rgba(5, 7, 10, 0.82);
    color: #f4dfae;
    font-size: 12px;
    font-weight: 900;
    line-height: 1;
    letter-spacing: 0;
    text-shadow: 0 1px 0 rgba(0, 0, 0, 0.86);
}

#tabContentInventory .tarot-loadout-grid.is-guardian::before {
    content: attr(data-deck-count) "/1";
}

#tabContentInventory .tarot-loadout-grid[data-deck-complete="true"]::before {
    color: #fff7d1;
    background: rgba(92, 63, 16, 0.9);
    border-color: rgba(255, 226, 151, 0.58);
}

#tabContentInventory .tarot-loadout-card {
    position: relative;
    width: 48px;
    height: 80px;
    min-width: 48px;
    min-height: 80px;
    padding: 0;
    border: 0;
    border-radius: 4px;
    background: transparent;
    box-shadow: none;
    display: grid;
    place-items: center;
    overflow: visible;
    appearance: none;
    cursor: pointer;
    touch-action: manipulation;
    user-select: none;
    transition: translate 150ms ease, filter 150ms ease, opacity 150ms ease;
    --tarot-suit-glow: rgba(218, 231, 246, 0.42);
    --tarot-suit-line: #edf3fb;
}

#tabContentInventory .tarot-loadout-card.is-selected {
    z-index: 3;
    translate: 0 -4px;
    filter: brightness(1.12);
}

#tabContentInventory .tarot-loadout-card.is-selected::after {
    content: "";
    position: absolute;
    right: 6px;
    bottom: -7px;
    left: 6px;
    height: 3px;
    border-radius: 999px;
    background: var(--tarot-suit-line);
    box-shadow: 0 0 7px var(--tarot-suit-glow);
}

#tabContentInventory .tarot-loadout-grid.is-busy {
