/* Tarot Kingdom monster battle stage */
#tarotKingdomRoot #tarotKingdomBattleStage[hidden] {
    display: none !important;
}

#tarotKingdomRoot #tarotKingdomBattleStage:not([hidden]) {
    display: block;
}

#tarotKingdomRoot #tarotKingdomBattleStage {
    position: relative;
    isolation: isolate;
    box-sizing: border-box;
    width: 100%;
    margin: 8px 0;
    padding: 12px;
    overflow: hidden;
    border: 1px solid rgba(235, 198, 103, 0.52);
    border-radius: 16px;
    color: #f8fafc;
    background:
        radial-gradient(circle at 20% 58%, rgba(202, 67, 51, 0.16), transparent 34%),
        radial-gradient(circle at 82% 40%, rgba(58, 129, 171, 0.16), transparent 38%),
        linear-gradient(180deg, rgba(15, 24, 36, 0.97), rgba(3, 7, 13, 0.98));
    box-shadow:
        inset 0 0 0 2px rgba(255, 239, 180, 0.04),
        inset 0 -28px 52px rgba(0, 0, 0, 0.28),
        0 10px 24px rgba(0, 0, 0, 0.28);
}

#tarotKingdomRoot #tarotKingdomBattleStage::before {
    content: "";
    position: absolute;
    z-index: -1;
    inset: 0;
    opacity: 0.24;
    pointer-events: none;
    background:
        linear-gradient(90deg, transparent 49.7%, rgba(255, 255, 255, 0.045) 50%, transparent 50.3%),
        repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.025) 0 1px, transparent 1px 7px);
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-arena {
    display: grid;
    grid-template-columns: minmax(164px, 1fr) minmax(112px, 0.72fr) minmax(190px, 1.05fr);
    gap: 14px;
    align-items: stretch;
    min-height: 268px;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-enemy,
#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-party-side {
    position: relative;
    min-width: 0;
    padding: 10px;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 13px;
    background: linear-gradient(180deg, rgba(15, 23, 42, 0.7), rgba(2, 6, 23, 0.42));
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-enemy {
    display: grid;
    grid-template-rows: auto auto minmax(116px, 1fr);
    border-color: rgba(248, 113, 113, 0.25);
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-party-side {
    display: flex;
    flex-direction: column;
    border-color: rgba(125, 211, 252, 0.23);
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-side-heading {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    min-width: 0;
    gap: 8px;
    margin-bottom: 6px;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-side-heading strong {
    min-width: 0;
    overflow: hidden;
    color: #fff7db;
    font-size: 14px;
    font-weight: 900;
    letter-spacing: 0.03em;
    text-overflow: ellipsis;
    text-shadow: 0 1px 8px rgba(0, 0, 0, 0.8);
    white-space: nowrap;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-eyebrow {
    flex: 0 0 auto;
    color: #fca5a5;
    font-size: 9px;
    font-weight: 950;
    letter-spacing: 0.15em;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-party-side .tarot-kingdom-battle-eyebrow {
    color: #7dd3fc;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-hp {
    min-width: 0;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-hp-label {
    display: flex;
    justify-content: space-between;
    gap: 6px;
    margin-bottom: 3px;
    color: #fecaca;
    font-size: 10px;
    font-weight: 900;
    line-height: 1;
    font-variant-numeric: tabular-nums;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-hp-track,
#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-player-hp-track {
    position: relative;
    height: 8px;
    overflow: hidden;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 999px;
    background: rgba(0, 0, 0, 0.58);
    box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.78);
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-hp-fill,
#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-player-hp-fill {
    display: block;
    width: 100%;
    height: 100%;
    border-radius: inherit;
    background: linear-gradient(90deg, #dc2626, #fb7185 68%, #fecdd3);
    box-shadow: 0 0 10px rgba(244, 63, 94, 0.48);
    transition: width 360ms cubic-bezier(0.22, 0.8, 0.25, 1), background-color 240ms ease;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-player-hp-fill {
    background: linear-gradient(90deg, #15803d, #4ade80 68%, #bbf7d0);
    box-shadow: 0 0 8px rgba(34, 197, 94, 0.36);
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-enemy-visual {
    position: relative;
    display: grid;
    place-items: end center;
    min-height: 116px;
    overflow: visible;
}

#tarotKingdomRoot #tarotKingdomEnemySprite.tarot-kingdom-battle-enemy-sprite {
    --tarot-kingdom-enemy-scale: 2;
    position: relative;
    z-index: 1;
    width: 81px;
    height: 84px;
    background-repeat: no-repeat;
    background-position: 0 0;
    image-rendering: pixelated;
    image-rendering: crisp-edges;
    transform: scale(var(--tarot-kingdom-enemy-scale));
    transform-origin: 50% 100%;
    filter: drop-shadow(0 5px 2px rgba(0, 0, 0, 0.58));
    will-change: transform, filter, opacity;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-center {
    display: flex;
    flex-direction: column;
    justify-content: center;
    min-width: 0;
    gap: 10px;
    text-align: center;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-turn {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 5px;
    padding: 5px 8px;
    border: 1px solid rgba(250, 204, 21, 0.32);
    border-radius: 999px;
    color: #fde68a;
    background: rgba(63, 44, 6, 0.48);
    font-size: 10px;
    font-weight: 900;
    letter-spacing: 0.04em;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-feed {
    display: grid;
    align-content: center;
    min-height: 62px;
    max-height: 108px;
    overflow: hidden;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-event {
    padding: 7px 8px;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 9px;
    color: #cbd5e1;
    background: rgba(2, 6, 23, 0.68);
    font-size: 10px;
    font-weight: 800;
    line-height: 1.35;
    overflow-wrap: anywhere;
    animation: tarotKingdomBattleEventIn 260ms ease-out both;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-event.is-attack {
    border-color: rgba(125, 211, 252, 0.38);
    color: #bae6fd;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-event.is-skill {
    border-color: rgba(250, 204, 21, 0.54);
    color: #fef08a;
    background: rgba(113, 63, 18, 0.48);
    box-shadow: 0 0 18px rgba(250, 204, 21, 0.12);
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-event.is-enemy,
#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-event.is-danger,
#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-event.is-defeat {
    border-color: rgba(248, 113, 113, 0.42);
    color: #fecaca;
    background: rgba(69, 10, 10, 0.52);
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-event.is-victory {
    border-color: rgba(74, 222, 128, 0.48);
    color: #bbf7d0;
    background: rgba(20, 83, 45, 0.48);
}

#tarotKingdomRoot #tarotKingdomBattleParty.tarot-kingdom-battle-party {
    display: grid;
    flex: 1 1 auto;
    align-content: center;
    min-height: 0;
    gap: 7px;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-player {
    position: relative;
    display: grid;
    grid-template-columns: 58px minmax(0, 1fr);
    grid-template-areas: "avatar info";
    align-items: center;
    min-width: 0;
    min-height: 68px;
    gap: 4px 7px;
    padding: 5px 7px;
    border: 1px solid rgba(125, 211, 252, 0.16);
    border-radius: 10px;
    background: rgba(8, 22, 36, 0.68);
    transition: border-color 180ms ease, background-color 180ms ease, filter 180ms ease, opacity 180ms ease;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-player-avatar {
    grid-area: avatar;
    display: grid;
    place-items: center;
    width: 56px;
    height: 60px;
    overflow: visible;
    --avatar-combat-scale: 0.78;
    --avatar-attack-x: -22px;
    --avatar-attack-recoil-x: -14px;
    --avatar-slash-left: -16px;
    --avatar-slash-top: 12px;
    --avatar-foot-shadow-width: 42px;
    --avatar-foot-shadow-height: 8px;
    image-rendering: pixelated;
    filter: drop-shadow(0 3px 2px rgba(0, 0, 0, 0.54));
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-player-info {
    grid-area: info;
    display: grid;
    min-width: 0;
    gap: 3px;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-player-header {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    min-width: 0;
    gap: 5px;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-player-name {
    min-width: 0;
    overflow: hidden;
    color: #e0f2fe;
    font-size: 11px;
    font-weight: 900;
    line-height: 1.1;
    text-align: left;
    text-overflow: ellipsis;
    white-space: nowrap;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-player-rank {
    flex: 0 1 auto;
    overflow: hidden;
    color: #bae6fd;
    font-size: 8px;
    font-weight: 800;
    text-overflow: ellipsis;
    white-space: nowrap;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-player-stats {
    overflow: hidden;
    color: #fde68a;
    font-size: 8px;
    font-weight: 900;
    letter-spacing: 0.02em;
    text-overflow: ellipsis;
    white-space: nowrap;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-player-status {
    color: #94a3b8;
    font-size: 8px;
    font-weight: 950;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-player-hp {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    min-width: 0;
    gap: 5px;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-player-hp-text {
    color: #bbf7d0;
    font-size: 8px;
    font-weight: 900;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-player.is-turn {
    border-color: rgba(250, 204, 21, 0.74);
    background: linear-gradient(90deg, rgba(113, 63, 18, 0.58), rgba(8, 22, 36, 0.72));
    box-shadow: 0 0 14px rgba(250, 204, 21, 0.2), inset 3px 0 0 #facc15;
    animation: tarotKingdomBattleTurnPulse 1.35s ease-in-out infinite;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-player.is-turn .tarot-kingdom-battle-player-status {
    color: #fde68a;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-player.is-hit {
    animation: tarotKingdomBattlePlayerHit 360ms ease-out both;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-player.is-ko {
    border-color: rgba(148, 163, 184, 0.13);
    opacity: 0.48;
    filter: grayscale(1);
    background: rgba(15, 23, 42, 0.64);
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-player.is-ko::after {
    content: "KO";
    position: absolute;
    right: 8px;
    bottom: 5px;
    color: #fecaca;
    font-size: 9px;
    font-weight: 950;
    letter-spacing: 0.12em;
    text-shadow: 0 1px 4px #000;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-enemy.is-attacking .tarot-kingdom-battle-enemy-visual {
    animation:
        tarotKingdomBattleEnemyAdvance
            var(--tk-enemy-attack-advance-ms, 180ms)
            cubic-bezier(0.16, 0.78, 0.2, 1)
            var(--tk-enemy-attack-elapsed-delay, 0ms)
            1
            forwards,
        tarotKingdomBattleEnemyReturn
            var(--tk-enemy-attack-return-ms, 180ms)
            cubic-bezier(0.38, 0, 0.72, 0.42)
            calc(var(--tk-enemy-attack-animation-ms, 680ms) + var(--tk-enemy-attack-elapsed-delay, 0ms))
            1
            forwards;
    will-change: transform;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-enemy.is-hurt .tarot-kingdom-battle-enemy-sprite,
#tarotKingdomRoot #tarotKingdomEnemySprite.is-hurt {
    animation: tarotKingdomBattleEnemyHurt 360ms ease-out both;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-enemy.is-time-stopped .tarot-kingdom-battle-enemy-sprite,
#tarotKingdomRoot #tarotKingdomEnemySprite.is-time-stopped {
    animation: none !important;
}

#tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-enemy.is-defeated .tarot-kingdom-battle-enemy-sprite,
#tarotKingdomRoot #tarotKingdomEnemySprite.is-defeated {
    opacity: 0.32;
    filter: grayscale(1) brightness(0.62) drop-shadow(0 5px 2px rgba(0, 0, 0, 0.58));
    transform: translateY(11px) rotate(-7deg) scale(var(--tarot-kingdom-enemy-scale));
    transition: opacity 480ms ease, filter 480ms ease, transform 480ms ease;
}

#tarotKingdomRoot #tarotKingdomBattleStage.is-victory {
    border-color: rgba(74, 222, 128, 0.62);
    box-shadow: inset 0 0 42px rgba(34, 197, 94, 0.12), 0 0 24px rgba(34, 197, 94, 0.14);
}

#tarotKingdomRoot #tarotKingdomBattleStage.is-defeat {
    border-color: rgba(248, 113, 113, 0.56);
    box-shadow: inset 0 0 48px rgba(127, 29, 29, 0.2), 0 0 24px rgba(127, 29, 29, 0.16);
}

#tarotKingdomRoot #tarotKingdomBattleStage.is-defeat .tarot-kingdom-battle-party {
    filter: grayscale(0.85) brightness(0.68);
}

#tarotKingdomRoot #tarotKingdomBattleStage.is-retreat .tarot-kingdom-battle-player.is-retreating {
    z-index: 12;
    opacity: 1;
    filter: none;
}

#tarotKingdomRoot #tarotKingdomBattleStage.is-retreat .tarot-kingdom-battle-player.is-retreating .tarot-kingdom-battle-player-avatar {
    animation: tarotKingdomPlayerRetreat 1600ms linear both;
}

#tarotKingdomRoot #tarotKingdomBattleStage.is-retreat .tarot-kingdom-battle-player.is-retreating .tarot-kingdom-battle-player-info {
    animation: tarotKingdomRetreatInfoFade 520ms ease-out both;
}

@keyframes tarotKingdomPlayerRetreat {
    0% {
        opacity: 1;
        transform: translateX(0) scaleX(-1);
    }
    14% {
        opacity: 1;
        transform: translateX(0) scaleX(-1);
    }
    82% {
        opacity: 1;
        transform: translateX(108px) scaleX(-1);
    }
    100% {
        opacity: 0;
        transform: translateX(148px) scaleX(-1);
    }
}

@keyframes tarotKingdomRetreatInfoFade {
    from { opacity: 1; }
    to { opacity: 0; }
}

@keyframes tarotKingdomBattleEventIn {
    from { opacity: 0; transform: translateY(6px) scale(0.98); }
    to { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes tarotKingdomBattleTurnPulse {
    0%, 100% { box-shadow: 0 0 10px rgba(250, 204, 21, 0.13), inset 3px 0 0 #facc15; }
    50% { box-shadow: 0 0 20px rgba(250, 204, 21, 0.3), inset 3px 0 0 #fde047; }
}

@keyframes tarotKingdomBattleEnemyAdvance {
    from { transform: translateX(0); }
    to { transform: translateX(clamp(44px, 12vw, 92px)); }
}

@keyframes tarotKingdomBattleEnemyReturn {
    from { transform: translateX(clamp(44px, 12vw, 92px)); }
    to { transform: translateX(0); }
}

@keyframes tarotKingdomBattleEnemyHurt {
    0%, 100% { transform: translateX(0) scale(var(--tarot-kingdom-enemy-scale)); filter: drop-shadow(0 5px 2px rgba(0, 0, 0, 0.58)); }
    22% { transform: translateX(-10px) scale(var(--tarot-kingdom-enemy-scale)); filter: brightness(2.4) sepia(1) saturate(4) hue-rotate(315deg); }
    48% { transform: translateX(7px) scale(var(--tarot-kingdom-enemy-scale)); }
    70% { transform: translateX(-4px) scale(var(--tarot-kingdom-enemy-scale)); }
}

@media (prefers-reduced-motion: reduce) {
    #tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-enemy.is-attacking .tarot-kingdom-battle-enemy-visual {
        animation: none;
        transform: none;
    }

    #tarotKingdomRoot #tarotKingdomBattleStage.is-retreat .tarot-kingdom-battle-player.is-retreating .tarot-kingdom-battle-player-avatar {
        animation: tarotKingdomPlayerRetreatReduced 1600ms ease-out both;
    }
}

@keyframes tarotKingdomPlayerRetreatReduced {
    0%, 70% {
        opacity: 1;
        transform: scaleX(-1);
    }
    100% {
        opacity: 0;
        transform: scaleX(-1);
    }
}

@keyframes tarotKingdomBattlePlayerHit {
    0%, 100% { transform: translateX(0); filter: none; }
    24% { transform: translateX(9px); filter: brightness(1.8) sepia(0.8) saturate(2.5); }
    48% { transform: translateX(-6px); }
    70% { transform: translateX(3px); }
}

@media (max-width: 720px) {
    #tarotKingdomRoot #tarotKingdomBattleStage,
    #tabContentTarot #tarotKingdomRoot #tarotKingdomBattleStage {
        margin: 5px 0;
        padding: 8px;
        border-radius: 12px;
    }

    #tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-arena,
    #tabContentTarot #tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-arena {
        grid-template-columns: minmax(100px, 0.85fr) minmax(72px, 0.62fr) minmax(126px, 1.12fr);
        min-height: 208px;
        gap: 6px;
    }

    #tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-enemy,
    #tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-party-side,
    #tabContentTarot #tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-enemy,
    #tabContentTarot #tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-party-side {
        padding: 6px;
        border-radius: 9px;
    }

    #tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-side-heading,
    #tabContentTarot #tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-side-heading {
        display: block;
        margin-bottom: 4px;
    }

    #tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-side-heading strong,
    #tabContentTarot #tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-side-heading strong {
        display: block;
        font-size: 10px;
    }

    #tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-eyebrow,
    #tabContentTarot #tarotKingdomRoot #tarotKingdomBattleStage .tarot-kingdom-battle-eyebrow {
