@keyframes tarotKingdomActorParalysis {
    0%, 43%, 67%, 100% { translate: 0 0; }
    46%, 55% { translate: -1px 0; }
    49%, 61% { translate: 1px -1px; }
    52%, 64% { translate: -1px 1px; }
}

@keyframes tarotKingdomActorDrowsy {
    0%, 100% { translate: 0 0; }
    50% { translate: 0 2px; }
}

@keyframes tarotKingdomActorTremble {
    0%, 100% { translate: -1px 0; }
    50% { translate: 1px 0; }
}

@keyframes tarotKingdomActorConfusion {
    0%, 100% { translate: 0 0; }
    22% { translate: -2px 0; }
    48% { translate: 2px 0; }
    72% { translate: -1px 0; }
    88% { translate: 2px 0; }
}

@keyframes tarotKingdomActorBurn {
    0%, 100% { translate: 0 0; }
    45% { translate: 0 -1px; }
    55% { translate: 1px 0; }
}

@keyframes tarotKingdomActorBurdened {
    0%, 100% { translate: 0 0; }
    50% { translate: 0 1px; }
}

@keyframes tarotKingdomStatusSpark {
    0%, 34%, 67%, 100% { opacity: 0.18; scale: 0.82; }
    38%, 55%, 72%, 88% { opacity: 0.92; scale: 1; }
}

@keyframes tarotKingdomStatusFloat {
    0% { opacity: 0; translate: 0 4px; }
    35%, 70% { opacity: 0.78; }
    100% { opacity: 0; translate: 0 -7px; }
}

@keyframes tarotKingdomStatusFlame {
    from { opacity: 0.48; scale: 0.84 0.9; translate: 0 1px; }
    to { opacity: 0.9; scale: 1 1.08; translate: 0 -1px; }
}

@keyframes tarotKingdomStatusTremor {
    0%, 100% { translate: -1px 0; }
    50% { translate: 1px 1px; }
}

@keyframes tarotKingdomStatusConfusionSway {
    0%, 100% { translate: -3px 0; }
    50% { translate: 3px 0; }
}

@keyframes tarotKingdomStatusMist {
    0% { opacity: 0.3; scale: 0.96 1; translate: -1px 0; }
    55% { opacity: 0.48; scale: 1.03 0.98; translate: 1px -1px; }
    100% { opacity: 0.36; scale: 1 1.03; translate: 0 1px; }
}

@keyframes tarotKingdomStatusDrop {
    0% { opacity: 0; translate: 0 -4px; }
    35%, 75% { opacity: 0.78; }
    100% { opacity: 0; translate: 0 5px; }
}

@keyframes tarotKingdomStatusPulse {
    0%, 100% { opacity: 0.34; scale: 0.8; }
    50% { opacity: 0.82; scale: 1; }
}

@keyframes tarotKingdomStatusTrail {
    0%, 100% { opacity: 0.22; translate: 2px 0; }
    50% { opacity: 0.78; translate: -2px 0; }
}

@keyframes tarotKingdomShieldRing {
    0%, 100% { opacity: 0.42; scale: 0.98 1; }
    50% { opacity: 0.68; scale: 1 1.01; }
}

